1	import fs from "node:fs";
2	import path from "node:path";
3	import {
4		createManagedSkills,
5		resolveDisabledSkillIds,
6		syncManagedMcpServers,
7		writeSharedDisabledSkillIds,
8	} from "@superset/agent-setup";
9	import { getBundledPluginDir } from "@superset/agent-setup/config";
10	import { settings } from "@superset/local-db";
11	import {
12		getPluginByName,
13		type InstalledPlugin,
14		type PluginMcpServerConfig,
15		SUPERSET_MANAGED_SKILLS,
16	} from "@superset/shared/plugins";
17	import { localDb } from "main/lib/local-db";
18	
19	/**
20	 * Installed-plugin state and its materialization into agent configs. State
21	 * lives on the local-db settings singleton (not renderer localStorage)
22	 * because the boot-time sync below runs in main before any renderer exists.
23	 * Sync is declarative: every call converges agent configs on the full
24	 * installed set, so installs and uninstalls both land on app restart even if
25	 * a mid-session sync was missed.
26	 */
27	
28	export function getInstalledPlugins(): InstalledPlugin[] {
29		return localDb.select().from(settings).get()?.installedPlugins ?? [];
30	}
31	
32	function saveInstalledPlugins(next: InstalledPlugin[]): void {
33		localDb
34			.insert(settings)
35			.values({ id: 1, installedPlugins: next })
36			.onConflictDoUpdate({
37				target: settings.id,
38				set: { installedPlugins: next },
39			})
40			.run();
41	}
42	
43	function desiredMcpServers(
44		installed: InstalledPlugin[],
45	): Record<string, PluginMcpServerConfig> {
46		const desired: Record<string, PluginMcpServerConfig> = {};
47		for (const install of installed) {
48			// Disabled installs and unknown names (a catalog entry removed after
49			// install) contribute nothing, so their servers reap on the next sync.
50			// Per-agent skipping of servers the user configured themselves happens
51			// inside syncManagedMcpServers, scoped to each agent's own config.
52			if (install.enabled === false) continue;
53			const plugin = getPluginByName(install.name);
54			if (!plugin) continue;
55			Object.assign(desired, plugin.mcpServers);
56		}
57		return desired;
58	}
59	
60	export function syncInstalledPluginMcpServers(): void {
61		syncManagedMcpServers(desiredMcpServers(getInstalledPlugins()));
62	}
63	
64	/** Returns the updated install list; unknown plugin names return null. */
65	export function installPlugin(name: string): InstalledPlugin[] | null {
66		const plugin = getPluginByName(name);
67		if (!plugin) return null;
68	
69		const installed = getInstalledPlugins();
70		const next = installed.some((entry) => entry.name === name)
71			? installed
72			: [
73					...installed,
74					{
75						name: plugin.name,
76						version: plugin.version,
77						installedAt: new Date().toISOString(),
78					},
79				];
80		saveInstalledPlugins(next);
81		syncInstalledPluginMcpServers();
82		return next;
83	}
84	
85	export function uninstallPlugin(name: string): InstalledPlugin[] {
86		const next = getInstalledPlugins().filter((entry) => entry.name !== name);
87		saveInstalledPlugins(next);
88		syncInstalledPluginMcpServers();
89		return next;
90	}
91	
92	/**
93	 * Allowlisted against the shipped skill set — the name never touches the
94	 * filesystem unless it's one of ours.
95	 */
96	function resolveBundledSkillPath(name: string): string | null {
97		if (!SUPERSET_MANAGED_SKILLS.some((skill) => skill.name === name)) {
98			return null;
99		}
100		return path.join(getBundledPluginDir(), "skills", name, "SKILL.md");
101	}
102	
103	/**
104	 * Raw SKILL.md content (including frontmatter) of a bundled managed skill,
105	 * for the preview modal. Frontmatter must stay in — the in-app editor's
106	 * markdown view splits/reattaches it around edits, so a stripped read here
107	 * would delete it on the next save.
108	 */
109	export function getBundledSkillContent(name: string): string | null {
110		const skillPath = resolveBundledSkillPath(name);
111		if (!skillPath) return null;
112		try {
113			return fs.readFileSync(skillPath, "utf-8");
114		} catch {
115			return null;
116		}
117	}
118	
119	/** Absolute path to a bundled skill's SKILL.md, for Open/Reveal in Finder. */
120	export function getBundledSkillPath(name: string): string | null {
121		const skillPath = resolveBundledSkillPath(name);
122		if (!skillPath || !fs.existsSync(skillPath)) return null;
123		return skillPath;
124	}
125	
126	const SKILL_ICON_FILES = [
127		{ file: "icon.svg", mime: "image/svg+xml" },
128		{ file: "icon.png", mime: "image/png" },
129	] as const;
130	
131	/**
132	 * Data URIs of per-skill icons distributed inside the skill folders
133	 * (`skills/<name>/icon.svg|png`) — the Superset convention for skill authors
134	 * to ship artwork with their skill, mirroring how Codex plugins carry
135	 * `interface` icons. Skills without one fall back to a default glyph in the
136	 * renderer.
137	 */
138	export function getBundledSkillIcons(): Record<string, string> {
139		const icons: Record<string, string> = {};
140		for (const skill of SUPERSET_MANAGED_SKILLS) {
141			for (const { file, mime } of SKILL_ICON_FILES) {
142				const iconPath = path.join(
143					getBundledPluginDir(),
144					"skills",
145					skill.name,
146					file,
147				);
148				try {
149					const data = fs.readFileSync(iconPath);
150					icons[skill.name] = `data:${mime};base64,${data.toString("base64")}`;
151					break;
152				} catch {
153					// No icon in this format; try the next or fall through.
154				}
155			}
156		}
157		return icons;
158	}
159	
160	/**
161	 * Toggling re-syncs immediately: disable reaps, enable rewrites. A plugin
162	 * present only via the user's own config has no record yet — toggling adopts
163	 * it (creates the record) so the choice has somewhere to live.
164	 */
165	export function setPluginEnabled(
166		name: string,
167		enabled: boolean,
168	): InstalledPlugin[] {
169		const installed = getInstalledPlugins();
170		const hasRecord = installed.some((entry) => entry.name === name);
171		const plugin = getPluginByName(name);
172		const next = hasRecord
173			? installed.map((entry) =>
174					entry.name === name ? { ...entry, enabled } : entry,
175				)
176			: plugin
177				? [
178						...installed,
179						{
180							name: plugin.name,
181							version: plugin.version,
182							installedAt: new Date().toISOString(),
183							enabled,
184						},
185					]
186				: installed;
187		saveInstalledPlugins(next);
188		syncInstalledPluginMcpServers();
189		return next;
190	}
191	
192	export function getDisabledSkills(): string[] {
193		return localDb.select().from(settings).get()?.disabledSkills ?? [];
194	}
195	
196	// Serializes the createManagedSkills resyncs triggered by setSkillEnabled and
197	// writeBundledSkillContent so overlapping calls can't interleave:
198	// createManagedSkills does multi-await fs work, and without this a second
199	// call's resync could finish before the first's, leaving disk state
200	// contradicting whichever write actually happened last.
201	let managedSkillsSyncQueue: Promise<void> = Promise.resolve();
202	function queueManagedSkillsSync(disabledSkills: readonly string[]): void {
203		managedSkillsSyncQueue = managedSkillsSyncQueue
204			.catch(() => {}) // a prior failure must not stall later syncs
205			.then(() => createManagedSkills({ disabledSkills }));
206	}
207	
208	/**
209	 * Overwrites a bundled skill's SKILL.md, then re-provisions it out to
210	 * ~/.agents/skills, the Claude plugin mirror, and the slash-command file —
211	 * same convention as setSkillEnabled below.
212	 */
213	export function writeBundledSkillContent(name: string, content: string): void {
214		const skillPath = resolveBundledSkillPath(name);
215		if (!skillPath) {
216			throw new Error(`Unknown skill: ${name}`);
217		}
218		fs.writeFileSync(skillPath, content, "utf-8");
219		queueManagedSkillsSync(resolveDisabledSkillIds(getDisabledSkills()));
220	}
221	
222	/**
223	 * Toggling re-syncs immediately: disable reaps the skill from every agent
224	 * (and the Claude plugin mirror), enable rewrites it. Mirrored to the shared
225	 * disabled-skills file so CLI-launched host-services on this machine honor
226	 * the choice instead of re-provisioning a skill the user just disabled.
227	 * Returns null for a name outside SUPERSET_MANAGED_SKILLS.
228	 */
229	export function setSkillEnabled(
230		name: string,
231		enabled: boolean,
232	): string[] | null {
233		if (!SUPERSET_MANAGED_SKILLS.some((skill) => skill.name === name)) {
234			return null;
235		}
236		const current = new Set(getDisabledSkills());
237		if (enabled) {
238			current.delete(name);
239		} else {
240			current.add(name);
241		}
242		const next = [...current];
243		localDb
244			.insert(settings)
245			.values({ id: 1, disabledSkills: next })
246			.onConflictDoUpdate({
247				target: settings.id,
248				set: { disabledSkills: next },
249			})
250			.run();
251		writeSharedDisabledSkillIds(next);
252		// resolveDisabledSkillIds folds in SUPERSET_DISABLED_SKILLS — passing
253		// `next` straight through would silently re-enable an env-disabled skill
254		// on the next unrelated toggle.
255		queueManagedSkillsSync(resolveDisabledSkillIds(next));
256		return next;
257	}
