1	import fs from "node:fs";
2	import { cp, rm } from "node:fs/promises";
3	import os from "node:os";
4	import path from "node:path";
5	import { writeFileIfChanged } from "./agent-wrappers-common";
6	import { getBundledPluginDir } from "./config";
7	
8	export const MANAGED_SKILL_MARKER = "<!-- superset-managed-skill v1 -->";
9	
10	/**
11	 * Sentinel file marking a directory as Superset-managed (used for the Claude
12	 * plugin dir, whose manifest is JSON and can't carry the markdown marker).
13	 */
14	export const MANAGED_SENTINEL_NAME = ".superset-managed";
15	
16	/** Namespace subdirectory for managed commands under ~/.agents/commands. */
17	export const MANAGED_COMMAND_NAMESPACE = "superset";
18	
19	/**
20	 * Claude Code loads any ~/.claude/skills/<name> directory containing a
21	 * .claude-plugin/plugin.json as a "skills-directory plugin" named
22	 * `<name>@skills-dir`, namespacing its skills as `<name>:<skill>`.
23	 */
24	const CLAUDE_PLUGIN_DIR_NAME = "superset";
25	
26	/**
27	 * Skills exposed as slash commands to the in-app chat. Deliberately a curated
28	 * allowlist (the chat menu shouldn't mirror every skill); everything else in
29	 * the bundled plugin is provisioned automatically.
30	 */
31	const COMMAND_SKILLS = ["feedback", "10x", "setup", "doctor"] as const;
32	
33	export interface ManagedSkillsOptions {
34		homeDir?: string;
35		templatesDir?: string;
36		/** Skill names to withhold provisioning for (and reap if already provisioned). */
37		disabledSkills?: readonly string[];
38	}
39	
40	/**
41	 * Inserts the managed marker right after the frontmatter block so both the
42	 * writer and the reaper can tell managed files apart from user-authored ones.
43	 */
44	export function withManagedMarker(content: string): string {
45		if (content.includes(MANAGED_SKILL_MARKER)) return content;
46		const frontmatterEnd = content.startsWith("---\n")
47			? content.indexOf("\n---\n", 4)
48			: -1;
49		if (frontmatterEnd === -1) return `${MANAGED_SKILL_MARKER}\n${content}`;
50		const insertAt = frontmatterEnd + "\n---\n".length;
51		return `${content.slice(0, insertAt)}${MANAGED_SKILL_MARKER}\n${content.slice(insertAt)}`;
52	}
53	
54	/** Rewrites the frontmatter `name:` so it matches the destination directory. */
55	export function setFrontmatterName(content: string, name: string): string {
56		if (!content.startsWith("---\n")) return content;
57		const frontmatterEnd = content.indexOf("\n---\n", 4);
58		if (frontmatterEnd === -1) return content;
59		const frontmatter = content.slice(0, frontmatterEnd);
60		const rewritten = frontmatter.replace(/^name:[^\n]*$/m, `name: ${name}`);
61		return rewritten + content.slice(frontmatterEnd);
62	}
63	
64	function isUserOwnedFile(filePath: string): boolean {
65		if (!fs.existsSync(filePath)) return false;
66		return !fs.readFileSync(filePath, "utf-8").includes(MANAGED_SKILL_MARKER);
67	}
68	
69	function isManagedDir(dirPath: string): boolean {
70		if (fs.existsSync(path.join(dirPath, MANAGED_SENTINEL_NAME))) return true;
71		const skillMd = path.join(dirPath, "SKILL.md");
72		return fs.existsSync(skillMd) && !isUserOwnedFile(skillMd);
73	}
74	
75	function listFilesRecursive(root: string, relative = ""): string[] {
76		const files: string[] = [];
77		const absolute = relative ? path.join(root, relative) : root;
78		for (const entry of fs.readdirSync(absolute, { withFileTypes: true })) {
79			const entryRelative = relative
80				? path.join(relative, entry.name)
81				: entry.name;
82			if (entry.isDirectory()) {
83				files.push(...listFilesRecursive(root, entryRelative));
84			} else if (entry.isFile()) {
85				files.push(entryRelative);
86			}
87		}
88		return files;
89	}
90	
91	/**
92	 * Mirrors src into dest file-by-file (writeFileIfChanged semantics), removing
93	 * previously-managed files that no longer exist in src. Files for which
94	 * `isExcluded` returns true are treated as absent from src — skipped on the
95	 * way in, and reaped on the way out if a prior sync already wrote them.
96	 */
97	async function syncDir(
98		src: string,
99		dest: string,
100		isExcluded?: (relativePath: string) => boolean,
101	): Promise<void> {
102		const sourceFiles = listFilesRecursive(src).filter(
103			(file) => !isExcluded?.(file),
104		);
105		for (const file of sourceFiles) {
106			const source = path.join(src, file);
107			const target = path.join(dest, file);
108			fs.mkdirSync(path.dirname(target), { recursive: true });
109			// Skills may bundle scripts/; keep them runnable after provisioning.
110			const executable = (fs.statSync(source).mode & 0o111) !== 0;
111			writeFileIfChanged(
112				target,
113				fs.readFileSync(source, "utf-8"),
114				executable ? 0o755 : 0o644,
115			);
116		}
117		const wanted = new Set(sourceFiles.map((f) => path.join(dest, f)));
118		if (fs.existsSync(dest)) {
119			for (const file of listFilesRecursive(dest)) {
120				const absolute = path.join(dest, file);
121				if (file === MANAGED_SENTINEL_NAME || wanted.has(absolute)) continue;
122				await rm(absolute);
123				let parent = path.dirname(absolute);
124				while (
125					parent !== dest &&
126					fs.existsSync(parent) &&
127					fs.readdirSync(parent).length === 0
128				) {
129					await rm(parent, { recursive: true });
130					parent = path.dirname(parent);
131				}
132			}
133		}
134	}
135	
136	/**
137	 * Provisions the bundled plugin as a Claude Code skills-directory plugin
138	 * inside one Claude config dir — `~/.claude` for the default account, or a
139	 * profile dir whose own `skills/` the user owns (a shared profile links
140	 * `skills/` at the default account instead, and gets it that way).
141	 */
142	async function provisionClaudePlugin(
143		bundledPluginDir: string,
144		claudeDir: string,
145		disabledSkills: ReadonlySet<string>,
146	): Promise<void> {
147		const target = path.join(claudeDir, "skills", CLAUDE_PLUGIN_DIR_NAME);
148		const sentinel = path.join(target, MANAGED_SENTINEL_NAME);
149		if (fs.existsSync(target) && !fs.existsSync(sentinel)) {
150			console.log(`[agent-setup] Skipping user-owned plugin dir at ${target}`);
151			return;
152		}
153		await syncDir(bundledPluginDir, target, (relativePath) => {
154			const [dir, skillName] = relativePath.split(path.sep);
155			return dir === "skills" && disabledSkills.has(skillName ?? "");
156		});
157		writeFileIfChanged(sentinel, `${MANAGED_SKILL_MARKER}\n`, 0o644);
158	}
159	
160	function readPluginSkill(
161		bundledPluginDir: string,
162		pluginSkill: string,
163	): string | null {
164		const sourcePath = path.join(
165			bundledPluginDir,
166			"skills",
167			pluginSkill,
168			"SKILL.md",
169		);
170		if (!fs.existsSync(sourcePath)) return null;
171		return fs.readFileSync(sourcePath, "utf-8");
172	}
173	
174	/**
175	 * Every skill in the bundled plugin ships everywhere automatically unless the
176	 * user disabled it — adding a skill to plugins/superset/skills/ requires no
177	 * code change here. Returns null on enumeration failure: the caller must
178	 * abort (an empty desired set would make the reaper delete every
179	 * previously-provisioned skill).
180	 */
181	function listBundledSkills(bundledPluginDir: string): string[] | null {
182		const skillsDir = path.join(bundledPluginDir, "skills");
183		try {
184			return fs
185				.readdirSync(skillsDir, { withFileTypes: true })
186				.filter(
187					(entry) =>
188						entry.isDirectory() &&
189						fs.existsSync(path.join(skillsDir, entry.name, "SKILL.md")),
190				)
191				.map((entry) => entry.name);
192		} catch (error) {
193			console.warn("[agent-setup] Failed to enumerate bundled skills:", error);
194			return null;
195		}
196	}
197	
198	/** Copies a bundled skill's extra files (anything besides SKILL.md) verbatim. */
199	async function copyBundledExtras(
200		sourceDir: string,
201		targetDir: string,
202	): Promise<void> {
203		for (const entry of fs.readdirSync(sourceDir, { withFileTypes: true })) {
204			if (entry.name === "SKILL.md") continue;
205			await cp(
206				path.join(sourceDir, entry.name),
207				path.join(targetDir, entry.name),
208				{ recursive: true },
209			);
210		}
211	}
212	
213	async function reapStaleSkillDirs(
214		root: string,
215		desiredNames: Set<string>,
216	): Promise<void> {
217		if (!fs.existsSync(root)) return;
218		for (const entry of fs.readdirSync(root, { withFileTypes: true })) {
219			if (!entry.isDirectory() || desiredNames.has(entry.name)) continue;
220			const dirPath = path.join(root, entry.name);
221			if (!isManagedDir(dirPath)) continue;
222			await rm(dirPath, { recursive: true });
223			console.log(`[agent-setup] Reaped stale managed skill ${entry.name}`);
224		}
225	}
226	
227	async function reapStaleCommands(
228		namespaceDir: string,
229		desiredFiles: Set<string>,
230	): Promise<void> {
231		if (!fs.existsSync(namespaceDir)) return;
232		for (const entry of fs.readdirSync(namespaceDir, { withFileTypes: true })) {
233			if (!entry.isFile() || !entry.name.endsWith(".md")) continue;
234			if (desiredFiles.has(entry.name)) continue;
235			const filePath = path.join(namespaceDir, entry.name);
236			if (isUserOwnedFile(filePath)) continue;
237			await rm(filePath);
238			console.log(`[agent-setup] Reaped stale managed command ${entry.name}`);
239		}
240	}
241	
242	export async function createManagedSkills(
243		options: ManagedSkillsOptions = {},
244	): Promise<void> {
245		const homeDir = options.homeDir ?? os.homedir();
246		const bundledPluginDir = options.templatesDir
247			? path.join(options.templatesDir, "plugin")
248			: getBundledPluginDir();
249		const disabledSkills = new Set(options.disabledSkills ?? []);
250	
251		if (!fs.existsSync(path.join(bundledPluginDir, "skills"))) {
252			console.warn(
253				`[agent-setup] Bundled plugin missing at ${bundledPluginDir}; skipping managed skills`,
254			);
255			return;
256		}
257	
258		const agentsSkillsRoot = path.join(homeDir, ".agents", "skills");
259		const commandNamespaceDir = path.join(
260			homeDir,
261			".agents",
262			"commands",
263			MANAGED_COMMAND_NAMESPACE,
264		);
265	
266		try {
267			await provisionClaudePlugin(
268				bundledPluginDir,
269				path.join(homeDir, ".claude"),
270				disabledSkills,
271			);
272		} catch (error) {
273			console.warn("[agent-setup] Failed to provision Claude plugin:", error);
274		}
275	
276		const bundledSkills = listBundledSkills(bundledPluginDir);
277		if (bundledSkills === null) {
278			console.warn(
279				"[agent-setup] Skipping skill provisioning and reaping — bundled plugin unreadable",
280			);
281			return;
282		}
283	
284		const desiredAgentsDirs = new Set<string>();
285		for (const pluginSkill of bundledSkills) {
286			if (disabledSkills.has(pluginSkill)) continue;
287			// Prefixed dir name carries the namespace for agents without plugin
288			// support; frontmatter `name` is rewritten to match because the skill
289			// spec requires name == parent directory.
290			const dirName = `${MANAGED_COMMAND_NAMESPACE}-${pluginSkill}`;
291			try {
292				const raw = readPluginSkill(bundledPluginDir, pluginSkill);
293				if (raw === null) continue;
294				desiredAgentsDirs.add(dirName);
295				const targetDir = path.join(agentsSkillsRoot, dirName);
296				const skillMdPath = path.join(targetDir, "SKILL.md");
297				if (isUserOwnedFile(skillMdPath)) {
298					console.log(
299						`[agent-setup] Skipping user-owned skill at ${skillMdPath}`,
300					);
301					continue;
302				}
303				fs.mkdirSync(targetDir, { recursive: true });
304				writeFileIfChanged(
305					skillMdPath,
306					withManagedMarker(setFrontmatterName(raw, dirName)),
307					0o644,
308				);
309				await copyBundledExtras(
310					path.join(bundledPluginDir, "skills", pluginSkill),
311					targetDir,
312				);
313			} catch (error) {
314				console.warn(
315					`[agent-setup] Failed to provision skill ${pluginSkill}:`,
316					error,
317				);
318			}
319		}
320	
321		const desiredCommandFiles = new Set<string>();
322		for (const pluginSkill of COMMAND_SKILLS) {
323			if (disabledSkills.has(pluginSkill)) continue;
324			const fileName = `${pluginSkill}.md`;
325			try {
326				const raw = readPluginSkill(bundledPluginDir, pluginSkill);
327				if (raw === null) continue;
328				desiredCommandFiles.add(fileName);
329				const filePath = path.join(commandNamespaceDir, fileName);
330				if (isUserOwnedFile(filePath)) {
331					console.log(`[agent-setup] Skipping user-owned command at ${filePath}`);
332					continue;
333				}
334				fs.mkdirSync(commandNamespaceDir, { recursive: true });
335				writeFileIfChanged(filePath, withManagedMarker(raw), 0o644);
336			} catch (error) {
337				console.warn(
338					`[agent-setup] Failed to provision command ${fileName}:`,
339					error,
340				);
341			}
342		}
343	
344		try {
345			// ~/.claude/skills holds only the plugin dir; anything else marker-bearing
346			// there (including dirs from earlier versions of this mechanism) is stale.
347			await reapStaleSkillDirs(
348				path.join(homeDir, ".claude", "skills"),
349				new Set([CLAUDE_PLUGIN_DIR_NAME]),
350			);
351			await reapStaleSkillDirs(agentsSkillsRoot, desiredAgentsDirs);
352			await reapStaleCommands(commandNamespaceDir, desiredCommandFiles);
353		} catch (error) {
354			console.warn("[agent-setup] Failed to reap stale managed skills:", error);
355		}
356	
357		console.log("[agent-setup] Managed skills provisioned");
358	}
359	
