1	/**
2	 * Makes a provider account (a CLAUDE_CONFIG_DIR / CODEX_HOME profile dir) a
3	 * complete environment rather than a bare login.
4	 *
5	 * The CLIs read *everything* — skills, plugins, subagents, commands, MCP
6	 * servers, settings — from their active config dir, so pointing one at a
7	 * second dir to switch accounts also swapped the user's whole setup for an
8	 * empty one. Provisioning shares each of those surfaces from the default
9	 * account (see profile-sharing.ts for the link/sync/merge rules) and leaves
10	 * exactly one thing per-account: the login, plus the transcript and session
11	 * state that belongs to it.
12	 *
13	 * Idempotent and safe to re-run: it is called when an account is added, when
14	 * one is selected, and for the selected accounts at host boot.
15	 */
16	
17	import fs from "node:fs";
18	import os from "node:os";
19	import path from "node:path";
20	import {
21		ensureClaudeManagedHooksAt,
22		ensureCodexManagedHooksAt,
23	} from "./agent-wrappers-claude-codex-opencode";
24	import { resolveDisabledSkillIds } from "./disabled-skills";
25	import { provisionManagedClaudePluginAt } from "./managed-skills";
26	import {
27		linkSharedDir,
28		mergeSharedJsonKeys,
29		readProfileLedger,
30		type SurfaceOutcome,
31		syncSharedFile,
32		writeProfileLedger,
33	} from "./profile-sharing";
34	
35	export interface ProfileProvisionReport {
36		configDir: string;
37		/** Surface name -> what provisioning did with it, for setup logs. */
38		surfaces: Record<string, SurfaceOutcome>;
39	}
40	
41	export interface ProvisionProfileOptions {
42		/** Overridden in tests; the real home in every other caller. */
43		homeDir?: string;
44	}
45	
46	function isPlainObject(value: unknown): value is Record<string, unknown> {
47		return typeof value === "object" && value !== null && !Array.isArray(value);
48	}
49	
50	/** Real path when the dir exists, plain resolution otherwise — a symlink
51	 * alias of a protected dir must compare equal to it. */
52	function canonical(target: string): string {
53		try {
54			return fs.realpathSync(target);
55		} catch {
56			return path.resolve(target);
57		}
58	}
59	
60	/**
61	 * True for the share's source and the other default homes — provisioning a
62	 * default home would link it into itself (discovery excludes them, but a
63	 * CLAUDE_CONFIG_DIR env entry can name one directly, including via symlink).
64	 */
65	function isProtectedTarget(
66		target: string,
67		homeDir: string,
68		defaultDir: string,
69	): boolean {
70		const resolved = canonical(target);
71		const protectedDirs = [
72			homeDir,
73			defaultDir,
74			path.join(homeDir, ".config"),
75			path.join(homeDir, ".config", "claude"),
76		];
77		return protectedDirs.some((dir) => resolved === canonical(dir));
78	}
79	
80	function logReport(provider: string, report: ProfileProvisionReport): void {
81		const summary = Object.entries(report.surfaces)
82			.map(([surface, outcome]) => `${surface}=${outcome}`)
