1	import { readExternallyConfiguredMcpServers } from "@superset/agent-setup";
2	import { TRPCError } from "@trpc/server";
3	import {
4		getBundledSkillContent,
5		getBundledSkillIcons,
6		getBundledSkillPath,
7		getDisabledSkills,
8		getInstalledPlugins,
9		installPlugin,
10		setPluginEnabled,
11		setSkillEnabled,
12		uninstallPlugin,
13		writeBundledSkillContent,
14	} from "main/lib/plugin-installs";
15	import { z } from "zod";
16	import { publicProcedure, router } from "../..";
17	
18	/**
19	 * Install state for the Plugins page. The catalog itself is static data the
20	 * renderer imports from @superset/shared/plugins; this router only owns the
21	 * installed set and the materialization side effects (main/lib/plugin-installs).
22	 */
23	export const createPluginsRouter = () => {
24		return router({
25			listInstalled: publicProcedure.query(() => {
26				return getInstalledPlugins();
27			}),
28	
29			/**
30			 * MCP server names the user configured directly in their agent configs
31			 * (outside Superset). The catalog marks matching plugins "already set
32			 * up" instead of offering Install — we never manage those entries.
33			 */
34			listExternalServers: publicProcedure.query(() => {
35				return readExternallyConfiguredMcpServers();
36			}),
37	
38			/** Per-skill icon data URIs shipped inside skill folders (icon.svg|png). */
39			listSkillIcons: publicProcedure.query(() => {
40				return getBundledSkillIcons();
41			}),
42	
43			/** SKILL.md body and absolute path of a bundled managed skill, for the preview modal. */
44			getSkillContent: publicProcedure
45				.input(z.object({ name: z.string().min(1) }))
46				.query(({ input }) => {
47					return {
48						content: getBundledSkillContent(input.name),
49						path: getBundledSkillPath(input.name),
50					};
51				}),
52	
53			/** Names of bundled managed skills the user disabled. */
54			getDisabledSkills: publicProcedure.query(() => {
55				return getDisabledSkills();
56			}),
57	
58			setSkillEnabled: publicProcedure
59				.input(z.object({ name: z.string().min(1), enabled: z.boolean() }))
60				.mutation(({ input }) => {
61					const disabled = setSkillEnabled(input.name, input.enabled);
62					if (disabled === null) {
63						throw new TRPCError({
64							code: "NOT_FOUND",
65							message: `Unknown skill: ${input.name}`,
66						});
67					}
68					return { disabled };
69				}),
70	
71			/** Overwrites a bundled skill's SKILL.md, from the in-app editor. */
72			writeSkillContent: publicProcedure
73				.input(z.object({ name: z.string().min(1), content: z.string() }))
74				.mutation(({ input }) => {
75					try {
76						writeBundledSkillContent(input.name, input.content);
77					} catch (error) {
78						throw new TRPCError({
79							code: "INTERNAL_SERVER_ERROR",
80							message:
81								error instanceof Error ? error.message : "Failed to save skill",
82						});
83					}
84					return { ok: true };
85				}),
86	
87			install: publicProcedure
88				.input(z.object({ name: z.string().min(1) }))
89				.mutation(({ input }) => {
90					const installed = installPlugin(input.name);
91					if (installed === null) {
92						throw new TRPCError({
93							code: "NOT_FOUND",
94							message: `Unknown plugin: ${input.name}`,
95						});
96					}
97					return { installed };
98				}),
99	
100			uninstall: publicProcedure
