22	export function PluginsView() {
23		const [search, setSearch] = useState("");
24		const [isManageOpen, setIsManageOpen] = useState(false);
25		const navigate = useNavigate();
26	
27		const { data: installed } = electronTrpc.plugins.listInstalled.useQuery();
28		const installedNames = useMemo(
29			() => new Set((installed ?? []).map((entry) => entry.name)),
30			[installed],
31		);
32		const disabledNames = useMemo(
33			() =>
34				new Set(
35					(installed ?? [])
36						.filter((entry) => entry.enabled === false)
37						.map((entry) => entry.name),
38				),
39			[installed],
40		);
41		const { data: externalServers } =
42			electronTrpc.plugins.listExternalServers.useQuery();
43		// One state: an install record OR the user's own config both count as
44		// installed (having it = installed).
45		const isInstalled = (plugin: PluginCatalogEntry) =>
46			installedNames.has(plugin.name) ||
47			isPluginExternallyConfigured(plugin, externalServers ?? []);
48	
49		const { install, uninstall, setEnabled, isBusy } = usePluginMutations();
50	
51		const handleOpen = (plugin: PluginCatalogEntry) => {
52			navigate({
53				to: "/plugins/$pluginName",
54				params: { pluginName: plugin.name },
55			});
56		};
57	
58		const query = search.trim().toLowerCase();
