1	/**
2	 * The curated plugin catalog the desktop Plugins page renders and installs
3	 * from. Static for the MVP — each entry is shaped as a pre-resolved plugin
4	 * manifest using the Codex plugin vocabulary
5	 * (developers.openai.com/plugins/build/plugins: `name`, `version`,
6	 * `description`, `interface`, and an `.mcp.json`-shaped `mcpServers` map), so
7	 * when the catalog grows real sources (git/npm/tarball) entries port
8	 * field-for-field instead of needing a data migration.
9	 *
10	 * Icons stay per-app (`packages/shared` isn't React-aware) — same split as
11	 * `INTEGRATIONS` in ../integrations.ts.
12	 */
13	
14	/**
15	 * One MCP server a plugin materializes into agent configs. Same shape as a
16	 * Codex/Claude `.mcp.json` value: remote servers carry `url` (+ transport
17	 * `type`), local ones `command`/`args`/`env`. Server auth happens in the
18	 * agent CLI on first use (Codex calls this ON_FIRST_USE) — org
19	 * integration_connections tokens are a separate plane and never ship here.
20	 */
21	export type PluginMcpServerConfig =
22		| {
23				type: "http" | "sse";
24				url: string;
25				headers?: Record<string, string>;
26		  }
27		| {
28				command: string;
29				args?: readonly string[];
30				env?: Record<string, string>;
31		  };
32	
33	export const PLUGIN_CATEGORIES = [
34		"Productivity",
35		"Communication",
36		"Developer tools",
37		"Design",
38		"Data & APIs",
39	] as const;
40	
41	export type PluginCategory = (typeof PLUGIN_CATEGORIES)[number];
42	
43	export interface PluginCatalogEntry {
44		/**
45		 * Stable kebab-case id — the key installs, the materialization ledger, and
46		 * analytics all hang off. Where a `integration_provider` slug exists for
47		 * the same product (linear, github, notion, sentry) the id matches it, so
48		 * a future join against `integration_connections` is free.
49		 */
50		name: string;
51		/** Semver; bumping forces re-materialization (Codex convention). */
52		version: string;
53		description: string;
54		interface: {
55			displayName: string;
56			category: PluginCategory;
57		};
58		/**
59		 * Server-name → config. Names land verbatim as config keys in agent CLIs
60		 * (`mcp__<name>__<tool>` namespacing comes from the CLI itself); ownership
61		 * is tracked by the materialization ledger, not the name.
62		 */
63		mcpServers: Record<string, PluginMcpServerConfig>;
64		/** Names of skills the plugin bundles (Codex manifests point `skills` at a directory; a resolved entry lists them). */
65		skills?: readonly string[];
66		/** Curation attribute, not manifest vocabulary: surfaces in Featured. */
67		featured?: boolean;
68	}
69	
70	/**
71	 * An MCP server found in the user's agent configs that Superset didn't write
72	 * — any scope (Claude user/project, Codex, Cursor). Carries enough of the
73	 * config to match against catalog entries by more than name: people name
74	 * servers freely ("linear-server"), so identity comes from where the server
75	 * points, not what it's called.
76	 */
77	export interface ExternalMcpServer {
78		name: string;
79		url?: string;
80		command?: string;
81		args?: readonly string[];
82		/** Where it was found, for display: "Claude Code (project)", "Codex", … */
83		source?: string;
84	}
85	
86	function urlHost(value: string): string | null {
87		try {
88			return new URL(value).hostname;
89		} catch {
90			return null;
91		}
92	}
93	
94	/**
95	 * "npx -y @playwright/mcp@latest" → "@playwright/mcp". Only the first
96	 * non-flag arg names the package — scanning further would match subcommands
97	 * (e.g. a literal `mcp` arg) and create false matches against unrelated
98	 * servers.
99	 */
100	function packageFromArgs(args: readonly string[] | undefined): string | null {
101		for (const arg of args ?? []) {
102			if (arg.startsWith("-")) continue;
103			const match = arg.match(/^(@?[^@]+(?:\/[^@]+)?)(?:@[^@]*)?$/);
104			return match?.[1] ?? null;
105		}
106		return null;
107	}
108	
109	function externalMatchesConfig(
110		server: ExternalMcpServer,
111		catalogName: string,
112		config: PluginMcpServerConfig,
113	): boolean {
114		if (server.name === catalogName) return true;
115		if ("url" in config && server.url) {
116			const catalogHost = urlHost(config.url);
117			if (catalogHost !== null && catalogHost === urlHost(server.url)) {
118				return true;
119			}
120		}
121		if ("command" in config) {
122			const pkg = packageFromArgs(config.args);
123			if (pkg !== null) {
124				const haystack = [server.command ?? "", ...(server.args ?? [])].join(" ");
125				if (haystack.includes(pkg)) return true;
126			}
127		}
128		return false;
129	}
130	
131	/**
132	 * Whether one catalog server is already covered by an entry the user wrote
133	 * themselves — matched by name, remote URL hostname, or the npm package a
134	 * stdio server runs (people name servers freely, e.g. "linear-server").
135	 * The materializer skips satisfied servers so installing never duplicates.
136	 */
137	export function isServerSatisfiedExternally(
138		catalogName: string,
139		config: PluginMcpServerConfig,
140		external: readonly ExternalMcpServer[],
141	): boolean {
142		return external.some((server) =>
143			externalMatchesConfig(server, catalogName, config),
144		);
145	}
146	
147	/** The user's own config entries that correspond to this plugin. */
148	export function getMatchingExternalServers(
149		plugin: PluginCatalogEntry,
150		external: readonly ExternalMcpServer[],
151	): ExternalMcpServer[] {
152		const entries = Object.entries(plugin.mcpServers);
153		return external.filter((server) =>
154			entries.some(([name, config]) =>
155				externalMatchesConfig(server, name, config),
156			),
157		);
158	}
159	
160	/** Whether the user already has any of this plugin's servers configured themselves. */
161	export function isPluginExternallyConfigured(
162		plugin: PluginCatalogEntry,
163		external: readonly ExternalMcpServer[],
164	): boolean {
165		return getMatchingExternalServers(plugin, external).length > 0;
166	}
167	
168	/** What a plugin puts on your machine, for at-a-glance labeling in the UI. */
169	export type PluginComponentKind = "mcp" | "cli" | "skills";
170	
171	/**
172	 * Derived from the manifest so labels can't drift from behavior: a remote
173	 * `url` server is "mcp", a `command` server runs a local process ("cli"),
174	 * bundled skills are "skills".
175	 */
176	export function getPluginComponentKinds(
177		plugin: PluginCatalogEntry,
178	): PluginComponentKind[] {
179		const kinds = new Set<PluginComponentKind>();
180		for (const config of Object.values(plugin.mcpServers)) {
181			kinds.add("url" in config ? "mcp" : "cli");
182		}
183		if (plugin.skills && plugin.skills.length > 0) {
184			kinds.add("skills");
185		}
186		return [...kinds];
187	}
188	
189	/**
190	 * The managed skills the `superset` plugin provisions into every agent CLI
191	 * (see packages/agent-setup/src/managed-skills.ts). The Plugins page lists
192	 * these read-only on its Skills tab; they are not installable units in the
193	 * MVP.
194	 */
195	export const SUPERSET_MANAGED_SKILLS = [
196		{
197			name: "10x",
198			description: "Personalized audit of Superset features you're not using yet",
199		},
200		{
201			name: "automate",
202			description: "Turn a recurring chore into a Superset automation",
203		},
204		{
205			name: "browser",
206			description: "Drive web pages from the in-app browser panes",
207		},
208		{
209			name: "computer",
210			description: "Drive native desktop apps and system browsers",
211		},
212		{
213			name: "contribute",
214			description: "Set up an open-source contribution to Superset",
215		},
216		{ name: "doctor", description: "Diagnose and fix Superset problems" },
217		{ name: "feedback", description: "Report bugs and request features" },
218		{
219			name: "orchestrate",
220			description: "Coordinate multiple coding agents across workspaces",
221		},
222		{ name: "setup", description: "Make a repository Superset-ready" },
223		{ name: "standup", description: "Digest of what your Superset agents did" },
224	] as const;
225	
226	export const PLUGIN_CATALOG: readonly PluginCatalogEntry[] = [
227		{
228			name: "superset",
229			version: "1.0.0",
230			description: "Manage Superset workspaces, tasks, and automations",
231			interface: { displayName: "Superset", category: "Productivity" },
232			/**
233			 * (CLOUD-SEVERANCE-P2) Upstream materializes a remote MCP server here,
234			 * at the `/mcp` route of the cloud data plane this fork severed (the
235			 * hostname is deliberately not written out: the main bundle keeps
236			 * source comments, and the gate scans artifact BYTES, so spelling it
237			 * would fail the build from a comment). There is no account, no
238			 * session and nothing to authenticate an agent CLI against it, so
239			 * that server could only ever fail — and unlike the app's own cloud
240			 * calls it is not merely dead code, it gets WRITTEN INTO THE USER'S
241			 * AGENT CONFIGS on install, on disk, where the in-process egress
242			 * fence never sees it.
243			 *
244			 * So this entry ships its bundled skills and no server. Everything
245			 * that reads `mcpServers` already handles an empty map: the kind
246			 * badges fall back to "Skill", external-server detection matches
247			 * nothing, and the sync writes (and reaps) nothing for it.
248			 */
249			mcpServers: {},
250			skills: SUPERSET_MANAGED_SKILLS.map((skill) => skill.name),
251			featured: true,
252		},
253		{
254			name: "linear",
255			version: "1.0.0",
256			description: "Plan and build products",
257			interface: { displayName: "Linear", category: "Productivity" },
258			mcpServers: {
259				linear: { type: "http", url: "https://mcp.linear.app/mcp" },
260			},
261			featured: true,
262		},
