109					const yamlPath = path.join(SKILLS_DIR, dir, "agents", "openai.yaml");
110					expect(existsSync(yamlPath)).toBe(true);
111					const yaml = readFileSync(yamlPath, "utf-8");
112					expect(yaml).toMatch(/^interface:\n/);
113					for (const key of [
114						"display_name",
115						"short_description",
116						"default_prompt",
117					]) {
118						expect(yaml).toMatch(new RegExp(`^  ${key}: "[^"\\n]+"$`, "m"));
119					}
120				});
121			});
122		}
123	});
