114	/**
115	 * Extra Claude profile dirs beyond the defaults. Default homes are excluded —
116	 * callers already cover `~/.claude` and `~/.config/claude`.
117	 */
118	export async function discoverClaudeProfiles(): Promise<ClaudeProfile[]> {
119		const home = homedir();
120		const excluded = new Set([
121			join(home, ".claude"),
122			join(home, ".config", "claude"),
123		]);
124		const started = Date.now();
125		const profiles: ClaudeProfile[] = [];
126	
127		for (const candidate of await candidateDirectories()) {
128			if (Date.now() - started > SCAN_TIME_BUDGET_MS) break;
129			if (excluded.has(candidate)) continue;
130			const identity = await readClaudeIdentity(candidate);
131			if (!identity) continue;
132			profiles.push({
133				configDir: candidate,
134				sourceLabel: tildeLabel(candidate),
135				email: identity.email,
136				credentialsPath: join(candidate, ".credentials.json"),
137				keychainServices: keychainServicesForConfigDir(candidate),
138			});
139		}
140		return profiles;
141	}
