143	/** Reads one keychain service's secret; null when absent or non-darwin. */
144	export async function readKeychainSecret(
145		service: string,
146	): Promise<string | null> {
147		if (platform() !== "darwin") return null;
148		try {
149			const { stdout } = await execFileAsync(
150				"security",
151				["find-generic-password", "-s", service, "-w"],
152				{ timeout: 5_000 },
153			);
