  if (!fs.existsSync(sentinel) || !fs.readFileSync(sentinel, 'utf8').includes(marker)) {
    throw new Error(`Refusing to remove unverified Claude skill directory: ${claudePlugin}`);
  }
  removals.push({type: 'dir', target: claudePlugin});
}

const agentsSkills = path.join(home, '.agents', 'skills');
if (fs.existsSync(agentsSkills)) {
  for (const entry of fs.readdirSync(agentsSkills, {withFileTypes: true})) {
    if (!entry.isDirectory() || !entry.name.startsWith('superset-')) continue;
    const target = path.join(agentsSkills, entry.name);
    const skillFile = path.join(target, 'SKILL.md');
    if (!fs.existsSync(skillFile) || !fs.readFileSync(skillFile, 'utf8').includes(marker)) {
      throw new Error(`Refusing to remove unverified agent skill directory: ${target}`);
    }
    removals.push({type: 'dir', target});
  }
}

const commands = path.join(home, '.agents', 'commands', 'superset');
if (fs.existsSync(commands)) {
  for (const entry of fs.readdirSync(commands, {withFileTypes: true})) {
    const target = path.join(commands, entry.name);
    if (!entry.isFile() || !fs.readFileSync(target, 'utf8').includes(marker)) {
      throw new Error(`Refusing to remove unverified command entry: ${target}`);
    }
  }
  removals.push({type: 'dir', target: commands});
}

const disabledState = path.join(home, '.superset', 'disabled-skills.json');
if (fs.existsSync(disabledState)) {
  const parsed = JSON.parse(fs.readFileSync(disabledState, 'utf8'));
  if (!parsed || typeof parsed !== 'object' || !Array.isArray(parsed.disabledSkillIds)) {
    throw new Error(`Refusing to remove unverified disabled-skills state: ${disabledState}`);
  }
  removals.push({type: 'file', target: disabledState});
}

for (const removal of removals) {
  if (removal.type === 'dir') fs.rmSync(removal.target, {recursive: true});
  else fs.rmSync(removal.target);
  console.log(`removed ${path.resolve(removal.target)}`);
}
