18	/**
19	 * Per-plugin brand icons. Icons stay per-app rather than in the shared
20	 * catalog (same split as INTEGRATIONS — packages/shared isn't React-aware).
21	 * Three tiers: full-bleed marks that ship their own square art, transparent
22	 * color marks rendered inside a
23	 * tile, and tinted glyphs for the rest. Black-mark brands (GitHub, Notion,
24	 * Vercel) stay on the foreground token so they invert with the theme.
25	 */
26	
27	/** Own square artwork — rendered edge to edge, no tile behind. */
28	const FULL_BLEED_ICONS: Record<string, string> = {
