30		posthog: posthogIconUrl,
31		notion: notionIconUrl,
32		supabase: supabaseIconUrl,
33		superhuman: superhumanIconUrl,
34		granola: granolaIconUrl,
35		monday: mondayIconUrl,
36	};
37	
38	/** Transparent full-color marks — rendered inside the tile. */
39	const IMAGE_ICONS: Record<string, string> = {
40		figma: figmaIconUrl,
41		slack: slackIconUrl,
42		neon: neonIconUrl,
43		circleback: circlebackIconUrl,
44	};
45	
46	const PLUGIN_ICONS: Record<
47		string,
48		{ icon: IconType; color?: string; scale?: string }
49	> = {
50		github: { icon: FaGithub },
51		sentry: { icon: SiSentry, color: "#7553FF" },
52		stripe: { icon: SiStripe, color: "#635BFF" },
53		context7: { icon: LuBookOpen },
54		playwright: { icon: LuDrama, color: "#2EAD33" },
55		"chrome-devtools": { icon: SiGooglechrome, color: "#4285F4" },
56		vercel: { icon: SiVercel, scale: "size-1/2" },
57	};
58	
59	interface PluginIconProps {
60		pluginName: string;
61		className?: string;
62	}
63	
64	export function PluginIcon({ pluginName, className }: PluginIconProps) {
65		const size = className ?? "size-9";
66	
67		const fullBleed = FULL_BLEED_ICONS[pluginName];
68		if (fullBleed !== undefined) {
69			return (
70				<img
71					src={fullBleed}
72					alt=""
73					className={cn("shrink-0 rounded-lg object-cover", size)}
74				/>
75			);
76		}
77	
78		const imageIcon = IMAGE_ICONS[pluginName];
79		const entry = PLUGIN_ICONS[pluginName];
80		const Icon = entry?.icon ?? LuPuzzle;
81		return (
82			<div
83				className={cn(
84					"flex shrink-0 items-center justify-center rounded-lg bg-muted/40 text-foreground",
85					size,
86				)}
87			>
88				{imageIcon !== undefined ? (
89					<img src={imageIcon} alt="" className="size-3/5 object-contain" />
90				) : (
91					<Icon
92						className={entry?.scale ?? "size-2/3"}
93						style={entry?.color ? { color: entry.color } : undefined}
94					/>
95				)}
96			</div>
97		);
98	}
