1	/**
2	 * Makes a provider account (a CLAUDE_CONFIG_DIR / CODEX_HOME profile dir) a
3	 * complete environment rather than a bare login.
4	 *
5	 * The CLIs read *everything* — skills, plugins, subagents, commands, MCP
6	 * servers, settings — from their active config dir, so pointing one at a
7	 * second dir to switch accounts also swapped the user's whole setup for an
8	 * empty one. Provisioning shares each of those surfaces from the default
9	 * account (see profile-sharing.ts for the link/sync/merge rules) and leaves
10	 * exactly one thing per-account: the login, plus the transcript and session
11	 * state that belongs to it.
12	 *
13	 * Idempotent and safe to re-run: it is called when an account is added, when
14	 * one is selected, and for the selected accounts at host boot.
15	 */
16	
17	import fs from "node:fs";
18	import os from "node:os";
19	import path from "node:path";
20	import {
21		ensureClaudeManagedHooksAt,
22		ensureCodexManagedHooksAt,
23	} from "./agent-wrappers-claude-codex-opencode";
24	import {
25		linkSharedDir,
26		mergeSharedJsonKeys,
27		readProfileLedger,
28		type SurfaceOutcome,
29		syncSharedFile,
30		writeProfileLedger,
31	} from "./profile-sharing";
32	
33	export interface ProfileProvisionReport {
34		configDir: string;
35		/** Surface name -> what provisioning did with it, for setup logs. */
36		surfaces: Record<string, SurfaceOutcome>;
37	}
38	
39	export interface ProvisionProfileOptions {
40		/** Overridden in tests; the real home in every other caller. */
41		homeDir?: string;
42	}
43	
44	function isPlainObject(value: unknown): value is Record<string, unknown> {
45		return typeof value === "object" && value !== null && !Array.isArray(value);
46	}
47	
48	/** Real path when the dir exists, plain resolution otherwise — a symlink
49	 * alias of a protected dir must compare equal to it. */
50	function canonical(target: string): string {
51		try {
52			return fs.realpathSync(target);
53		} catch {
54			return path.resolve(target);
55		}
56	}
57	
58	/**
59	 * True for the share's source and the other default homes — provisioning a
60	 * default home would link it into itself (discovery excludes them, but a
61	 * CLAUDE_CONFIG_DIR env entry can name one directly, including via symlink).
62	 */
63	function isProtectedTarget(
64		target: string,
65		homeDir: string,
66		defaultDir: string,
67	): boolean {
68		const resolved = canonical(target);
69		const protectedDirs = [
70			homeDir,
71			defaultDir,
72			path.join(homeDir, ".config"),
73			path.join(homeDir, ".config", "claude"),
74		];
75		return protectedDirs.some((dir) => resolved === canonical(dir));
76	}
77	
78	function logReport(provider: string, report: ProfileProvisionReport): void {
79		const summary = Object.entries(report.surfaces)
80			.map(([surface, outcome]) => `${surface}=${outcome}`)
81			.join(" ");
82		console.log(
83			`[agent-setup] Provisioned ${provider} account ${report.configDir}: ${summary}`,
84		);
85	}
86	
87	// ---------------------------------------------------------------------------
88	// Claude Code
89	// ---------------------------------------------------------------------------
90	
91	/**
92	 * Directories shared by symlink. Everything Claude Code loads as user-level
93	 * capability lives in one of these; what's left in a config dir is the login
94	 * and its own history (projects/, sessions/, shell-snapshots/, …).
95	 */
96	const CLAUDE_SHARED_DIRS = [
97		"skills",
98		"plugins",
99		"agents",
100		"commands",
101		"output-styles",
102	] as const;
103	
104	/** Files copied verbatim (the CLI rename-replaces them, so no symlink). */
105	const CLAUDE_SHARED_FILES = ["CLAUDE.md"] as const;
106	
107	/**
108	 * settings.json keys that must NOT follow the account. Everything else is
109	 * shared by default so a key added by a future CLI release comes along
110	 * without a code change here.
111	 */
112	const CLAUDE_PRIVATE_SETTINGS_KEYS = new Set([
113		// Provisioned per profile right after the merge — the hooks are identical,
114		// but they are ours to write, not the user's to share.
115		"hooks",
116		// Auth resolution: sharing these would let one account's credential
117		// mechanism silently answer for another.
118		"apiKeyHelper",
119		"awsAuthRefresh",
120		"awsCredentialExport",
121		"forceLoginMethod",
122		"forceLoginOrgUUID",
123	]);
124	
125	/** `env` entries holding a credential; the rest of `env` is shared. */
126	const CLAUDE_PRIVATE_ENV_KEYS = new Set([
127		"ANTHROPIC_API_KEY",
128		"ANTHROPIC_AUTH_TOKEN",
129		"CLAUDE_CODE_OAUTH_TOKEN",
130	]);
131	
132	/**
133	 * `.claude.json` keys that are shared — an allowlist, inverted from
134	 * settings.json on purpose: that file is mostly identity (oauthAccount,
135	 * userID), per-project transcript history, and server-driven caches, none of
136	 * which may cross accounts.
137	 */
138	const CLAUDE_SHARED_STATE_KEYS = ["mcpServers", "theme"] as const;
139	
140	function pickClaudeSettings(
141		source: Record<string, unknown>,
142	): Record<string, unknown> {
143		const shared: Record<string, unknown> = {};
144		for (const [key, value] of Object.entries(source)) {
145			if (CLAUDE_PRIVATE_SETTINGS_KEYS.has(key)) continue;
146			if (key === "env" && isPlainObject(value)) {
147				shared.env = Object.fromEntries(
148					Object.entries(value).filter(
149						([name]) => !CLAUDE_PRIVATE_ENV_KEYS.has(name),
150					),
151				);
152				continue;
153			}
154			shared[key] = value;
155		}
156		return shared;
157	}
158	
159	function pickClaudeState(
160		source: Record<string, unknown>,
161	): Record<string, unknown> {
162		const shared: Record<string, unknown> = {};
163		for (const key of CLAUDE_SHARED_STATE_KEYS) {
164			if (key in source) shared[key] = source[key];
165		}
166		return shared;
167	}
168	
169	/**
170	 * Brings one Claude config dir up to date with the default account. A no-op
171	 * for `~/.claude` itself, which is the source of every share.
172	 */
173	export async function provisionClaudeProfile(
174		configDir: string,
175		options: ProvisionProfileOptions = {},
176	): Promise<ProfileProvisionReport> {
