1	import {
2		isPluginExternallyConfigured,
3		PLUGIN_CATALOG,
4		PLUGIN_CATEGORIES,
5		type PluginCatalogEntry,
6	} from "@superset/shared/plugins";
7	import { Button } from "@superset/ui/button";
8	import { Input } from "@superset/ui/input";
9	import { Tabs, TabsContent, TabsList, TabsTrigger } from "@superset/ui/tabs";
10	import { Tooltip, TooltipContent, TooltipTrigger } from "@superset/ui/tooltip";
11	import { cn } from "@superset/ui/utils";
12	import { useNavigate } from "@tanstack/react-router";
13	import { useMemo, useState } from "react";
14	import { LuSearch, LuSettings2 } from "react-icons/lu";
15	import { electronTrpc } from "renderer/lib/electron-trpc";
16	import { PluginIcon } from "renderer/routes/_authenticated/_dashboard/plugins/components/PluginIcon";
17	import { usePluginMutations } from "renderer/routes/_authenticated/_dashboard/plugins/hooks/usePluginMutations";
18	import { ManageInstalledDialog } from "./components/ManageInstalledDialog";
19	import { PluginCard } from "./components/PluginCard";
20	
21	export function PluginsView() {
22		const [search, setSearch] = useState("");
23		const [isManageOpen, setIsManageOpen] = useState(false);
24		const navigate = useNavigate();
25	
26		const { data: installed } = electronTrpc.plugins.listInstalled.useQuery();
27		const installedNames = useMemo(
28			() => new Set((installed ?? []).map((entry) => entry.name)),
29			[installed],
30		);
31		const disabledNames = useMemo(
32			() =>
33				new Set(
34					(installed ?? [])
35						.filter((entry) => entry.enabled === false)
36						.map((entry) => entry.name),
37				),
38			[installed],
39		);
40		const { data: externalServers } =
41			electronTrpc.plugins.listExternalServers.useQuery();
42		// One state: an install record OR the user's own config both count as
43		// installed (having it = installed).
44		const isInstalled = (plugin: PluginCatalogEntry) =>
45			installedNames.has(plugin.name) ||
46			isPluginExternallyConfigured(plugin, externalServers ?? []);
47	
48		const { install, uninstall, setEnabled, isBusy } = usePluginMutations();
49	
50		const handleOpen = (plugin: PluginCatalogEntry) => {
51			navigate({
52				to: "/plugins/$pluginName",
53				params: { pluginName: plugin.name },
54			});
55		};
56	
57		const query = search.trim().toLowerCase();
58		const visiblePlugins = useMemo(() => {
59			if (query === "") return [...PLUGIN_CATALOG];
60			return PLUGIN_CATALOG.filter((plugin) =>
61				[
62					plugin.name,
63					plugin.interface.displayName,
64					plugin.description,
65					plugin.interface.category,
66				]
67					.join(" ")
68					.toLowerCase()
69					.includes(query),
70			);
71		}, [query]);
72	
73		const installedPlugins = visiblePlugins.filter(isInstalled);
74		const featured = visiblePlugins.filter((plugin) => plugin.featured);
75		// Featured plugins appear in their category section too — Featured is a
76		// spotlight, not a home.
77		const byCategory = PLUGIN_CATEGORIES.map((category) => ({
78			category,
79			plugins: visiblePlugins.filter(
80				(plugin) => plugin.interface.category === category,
81			),
82		})).filter(({ plugins }) => plugins.length > 0);
83	
84		const renderCard = (plugin: PluginCatalogEntry) => (
85			<PluginCard
86				key={plugin.name}
87				plugin={plugin}
88				isInstalled={isInstalled(plugin)}
89				isDisabled={disabledNames.has(plugin.name)}
90				isBusy={isBusy}
91				onOpen={handleOpen}
92				onInstall={(target) => install(target.name)}
93				onUninstall={(target) => uninstall(target.name)}
94				onSetEnabled={setEnabled}
95			/>
96		);
97	
98		return (
99			<div className="mx-auto w-full max-w-3xl px-6 pb-16">
100				<Tabs defaultValue="plugins">
101					<TabsList className="mb-6">
102						<TabsTrigger value="plugins">Plugins</TabsTrigger>
103					</TabsList>
104	
105					<TabsContent value="plugins" className="flex flex-col gap-6">
106						<div>
107							<h1 className="text-2xl font-semibold text-foreground">Plugins</h1>
108							<p className="mt-1 text-sm text-muted-foreground">
109								Work with your agents across your favorite tools
110							</p>
111						</div>
112	
113						<div className="relative">
114							<LuSearch className="absolute top-1/2 left-3 size-4 -translate-y-1/2 text-muted-foreground" />
115							<Input
116								value={search}
117								onChange={(event) => setSearch(event.target.value)}
118								placeholder="Search plugins"
119								className="rounded-full pl-9"
120							/>
121						</div>
122	
123						{installedPlugins.length > 0 && (
124							<section className="flex flex-col gap-3">
125								<div className="flex items-center justify-between">
126									<h2 className="text-sm font-semibold text-foreground">
127										Installed
128									</h2>
129									<Tooltip delayDuration={300}>
130										<TooltipTrigger asChild>
131											<Button
132												variant="ghost"
133												size="icon-xs"
134												className="text-muted-foreground"
135												aria-label="Manage plugins"
136												onClick={() => setIsManageOpen(true)}
137											>
138												<LuSettings2 className="size-4" />
139											</Button>
140										</TooltipTrigger>
141										<TooltipContent>Manage plugins</TooltipContent>
142									</Tooltip>
143								</div>
144								<div className="flex flex-wrap gap-2">
145									{installedPlugins.map((plugin) => (
146										<Tooltip key={plugin.name} delayDuration={300}>
147											<TooltipTrigger asChild>
148												<button
149													type="button"
150													aria-label={plugin.interface.displayName}
151													onClick={() => handleOpen(plugin)}
152													className={cn(
153														disabledNames.has(plugin.name) && "opacity-40",
154													)}
155												>
156													<PluginIcon
157														pluginName={plugin.name}
158														className="size-8"
159													/>
