import {
	isPluginExternallyConfigured,
	PLUGIN_CATALOG,
	PLUGIN_CATEGORIES,
	type PluginCatalogEntry,
} from "@superset/shared/plugins";
import { Button } from "@superset/ui/button";
import { Input } from "@superset/ui/input";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@superset/ui/tabs";
import { Tooltip, TooltipContent, TooltipTrigger } from "@superset/ui/tooltip";
import { cn } from "@superset/ui/utils";
import { useNavigate } from "@tanstack/react-router";
import { useMemo, useState } from "react";
import { LuSearch, LuSettings2 } from "react-icons/lu";
import { electronTrpc } from "renderer/lib/electron-trpc";
import { PluginIcon } from "renderer/routes/_authenticated/_dashboard/plugins/components/PluginIcon";
import { usePluginMutations } from "renderer/routes/_authenticated/_dashboard/plugins/hooks/usePluginMutations";
import { ManageInstalledDialog } from "./components/ManageInstalledDialog";
import { PluginCard } from "./components/PluginCard";

export function PluginsView() {
	const [search, setSearch] = useState("");
	const [isManageOpen, setIsManageOpen] = useState(false);
	const navigate = useNavigate();

	const { data: installed } = electronTrpc.plugins.listInstalled.useQuery();
	const installedNames = useMemo(
		() => new Set((installed ?? []).map((entry) => entry.name)),
		[installed],
	);
	const disabledNames = useMemo(
		() =>
			new Set(
				(installed ?? [])
					.filter((entry) => entry.enabled === false)
					.map((entry) => entry.name),
			),
		[installed],
	);
	const { data: externalServers } =
		electronTrpc.plugins.listExternalServers.useQuery();
	// One state: an install record OR the user's own config both count as
	// installed (having it = installed).
	const isInstalled = (plugin: PluginCatalogEntry) =>
		installedNames.has(plugin.name) ||
		isPluginExternallyConfigured(plugin, externalServers ?? []);

	const { install, uninstall, setEnabled, isBusy } = usePluginMutations();

	const handleOpen = (plugin: PluginCatalogEntry) => {
		navigate({
			to: "/plugins/$pluginName",
			params: { pluginName: plugin.name },
		});
	};

	const query = search.trim().toLowerCase();
	const visiblePlugins = useMemo(() => {
		if (query === "") return [...PLUGIN_CATALOG];
		return PLUGIN_CATALOG.filter((plugin) =>
			[
				plugin.name,
				plugin.interface.displayName,
				plugin.description,
				plugin.interface.category,
			]
				.join(" ")
				.toLowerCase()
				.includes(query),
		);
	}, [query]);

	const installedPlugins = visiblePlugins.filter(isInstalled);
	const featured = visiblePlugins.filter((plugin) => plugin.featured);
	// Featured plugins appear in their category section too — Featured is a
	// spotlight, not a home.
	const byCategory = PLUGIN_CATEGORIES.map((category) => ({
		category,
		plugins: visiblePlugins.filter(
			(plugin) => plugin.interface.category === category,
		),
	})).filter(({ plugins }) => plugins.length > 0);

	const renderCard = (plugin: PluginCatalogEntry) => (
		<PluginCard
			key={plugin.name}
			plugin={plugin}
			isInstalled={isInstalled(plugin)}
			isDisabled={disabledNames.has(plugin.name)}
			isBusy={isBusy}
			onOpen={handleOpen}
			onInstall={(target) => install(target.name)}
			onUninstall={(target) => uninstall(target.name)}
			onSetEnabled={setEnabled}
		/>
	);

	return (
		<div className="mx-auto w-full max-w-3xl px-6 pb-16">
			<Tabs defaultValue="plugins">
				<TabsList className="mb-6">
					<TabsTrigger value="plugins">Plugins</TabsTrigger>
				</TabsList>

				<TabsContent value="plugins" className="flex flex-col gap-6">
					<div>
						<h1 className="text-2xl font-semibold text-foreground">Plugins</h1>
						<p className="mt-1 text-sm text-muted-foreground">
							Work with your agents across your favorite tools
						</p>
					</div>

					<div className="relative">
						<LuSearch className="absolute top-1/2 left-3 size-4 -translate-y-1/2 text-muted-foreground" />
						<Input
							value={search}
							onChange={(event) => setSearch(event.target.value)}
							placeholder="Search plugins"
							className="rounded-full pl-9"
						/>
					</div>

					{installedPlugins.length > 0 && (
						<section className="flex flex-col gap-3">
							<div className="flex items-center justify-between">
								<h2 className="text-sm font-semibold text-foreground">
									Installed
								</h2>
								<Tooltip delayDuration={300}>
									<TooltipTrigger asChild>
										<Button
											variant="ghost"
											size="icon-xs"
											className="text-muted-foreground"
											aria-label="Manage plugins"
											onClick={() => setIsManageOpen(true)}
										>
											<LuSettings2 className="size-4" />
										</Button>
									</TooltipTrigger>
									<TooltipContent>Manage plugins</TooltipContent>
								</Tooltip>
							</div>
							<div className="flex flex-wrap gap-2">
								{installedPlugins.map((plugin) => (
									<Tooltip key={plugin.name} delayDuration={300}>
										<TooltipTrigger asChild>
											<button
												type="button"
												aria-label={plugin.interface.displayName}
												onClick={() => handleOpen(plugin)}
												className={cn(
													disabledNames.has(plugin.name) && "opacity-40",
												)}
											>
												<PluginIcon
													pluginName={plugin.name}
													className="size-8"
												/>
											</button>
										</TooltipTrigger>
										<TooltipContent>
											{plugin.interface.displayName}
											{disabledNames.has(plugin.name) ? " (disabled)" : ""}
										</TooltipContent>
									</Tooltip>
								))}
							</div>
						</section>
					)}

					{featured.length > 0 && (
						<section className="flex flex-col gap-3">
							<h2 className="text-sm font-semibold text-foreground">
								Featured
							</h2>
							<div className="grid grid-cols-1 gap-2 md:grid-cols-2">
								{featured.map(renderCard)}
							</div>
						</section>
					)}

					{byCategory.map(({ category, plugins }) => (
						<section key={category} className="flex flex-col gap-3">
							<h2 className="text-sm font-semibold text-foreground">
								{category}
							</h2>
							<div className="grid grid-cols-1 gap-2 md:grid-cols-2">
								{plugins.map(renderCard)}
							</div>
						</section>
					))}

					{visiblePlugins.length === 0 && (
						<p className="py-8 text-center text-sm text-muted-foreground">
							No plugins match "{search.trim()}"
						</p>
					)}

					<ManageInstalledDialog
						open={isManageOpen}
						onOpenChange={setIsManageOpen}
						installed={installed ?? []}
						isBusy={isBusy}
						onSetEnabled={setEnabled}
						onUninstall={uninstall}
					/>
				</TabsContent>

			</Tabs>
		</div>
	);
}

import {
	getMatchingExternalServers,
	type PluginCatalogEntry,
} from "@superset/shared/plugins";
import { Badge } from "@superset/ui/badge";
import { Button } from "@superset/ui/button";
import { Switch } from "@superset/ui/switch";
import { useNavigate } from "@tanstack/react-router";
import { useMemo } from "react";
import { LuArrowLeft, LuTrash2 } from "react-icons/lu";
import { electronTrpc } from "renderer/lib/electron-trpc";
import { PluginIcon } from "renderer/routes/_authenticated/_dashboard/plugins/components/PluginIcon";
import { PluginKindBadges } from "renderer/routes/_authenticated/_dashboard/plugins/components/PluginKindBadges";
import { usePluginMutations } from "renderer/routes/_authenticated/_dashboard/plugins/hooks/usePluginMutations";

export function PluginDetail({ plugin }: { plugin: PluginCatalogEntry }) {
	const navigate = useNavigate();
	const { data: installed } = electronTrpc.plugins.listInstalled.useQuery();
	const { data: externalServers } =
		electronTrpc.plugins.listExternalServers.useQuery();
	const { install, uninstall, setEnabled, isBusy } = usePluginMutations();

	const record = useMemo(
		() => (installed ?? []).find((entry) => entry.name === plugin.name),
		[installed, plugin.name],
	);
	const detectedServers = useMemo(
		() => getMatchingExternalServers(plugin, externalServers ?? []),
		[plugin, externalServers],
	);
	// One state: an install record OR the user's own config both count as
	// installed (having it = installed).
	const isInstalled = record !== undefined || detectedServers.length > 0;
	const isPluginEnabled = record?.enabled !== false;

	return (
		<div className="mx-auto w-full max-w-3xl px-6 pb-16">
			<Button
				variant="ghost"
				size="sm"
				className="mb-6 -ml-2 text-muted-foreground"
				onClick={() => navigate({ to: "/plugins" })}
			>
				<LuArrowLeft className="size-4" />
				Plugins
			</Button>

			<div className="flex items-start gap-4">
				<PluginIcon pluginName={plugin.name} className="size-14" />
				<div className="min-w-0 flex-1">
					<div className="flex items-center gap-2">
						<h1 className="text-xl font-semibold text-foreground">
							{plugin.interface.displayName}
						</h1>
						<PluginKindBadges plugin={plugin} />
					</div>
					<p className="mt-1 text-sm text-muted-foreground">
						{plugin.description}
					</p>
					<p className="mt-1 text-xs text-muted-foreground">
						v{plugin.version} · {plugin.interface.category}
						{record ? ` · installed ${record.installedAt.slice(0, 10)}` : ""}
					</p>
				</div>
				<div className="flex shrink-0 items-center gap-2">
					{isInstalled ? (
						<>
							<Switch
								checked={isPluginEnabled}
								disabled={isBusy}
								aria-label={`${plugin.interface.displayName} enabled`}
								onCheckedChange={(checked) => setEnabled(plugin.name, checked)}
							/>
							<Button
								variant="outline"
								size="sm"
								className="text-destructive"
								disabled={isBusy}
								onClick={() => uninstall(plugin.name)}
							>
								<LuTrash2 className="size-4" />
								Uninstall
							</Button>
						</>
					) : (
						<Button
							size="sm"
							className="rounded-full"
							disabled={isBusy}
							onClick={() => install(plugin.name)}
						>
							Install
						</Button>
					)}
				</div>
			</div>

			{isInstalled && (
				<p className="mt-3 text-xs text-muted-foreground">
					{!isPluginEnabled
						? "Disabled — kept installed, but Superset writes nothing into your agent configs."
						: record
							? "Enabled — servers are written into your agent configs."
							: "Provided by entries in your own agent config."}{" "}
					Changes take effect in new agent sessions.
				</p>
			)}
			{detectedServers.length > 0 && (
				<section className="mt-8 flex flex-col gap-3">
					<h2 className="text-sm font-semibold text-foreground">
						Detected in your agent configs
					</h2>
					<div className="flex flex-col divide-y divide-border/60 rounded-lg border border-border/60">
						{detectedServers.map((server) => (
							<div key={server.name} className="flex items-center gap-3 p-3">
								<div className="min-w-0 flex-1">
									<div className="flex items-center gap-1.5 text-sm font-medium text-foreground">
										{server.name}
										{server.source && (
											<span className="shrink-0 text-[10px] font-medium text-muted-foreground">
												{server.source}
											</span>
										)}
									</div>
									<p className="truncate font-mono text-xs text-muted-foreground">
										{server.url ??
											[server.command, ...(server.args ?? [])].join(" ")}
									</p>
								</div>
							</div>
						))}
					</div>
					<p className="text-xs text-muted-foreground">
						You added these yourself — Superset never touches them, and never
						writes duplicates of servers you already have.
					</p>
				</section>
			)}

			{Object.keys(plugin.mcpServers).length > 0 && (
				<section className="mt-8 flex flex-col gap-3">
					<h2 className="text-sm font-semibold text-foreground">MCP servers</h2>
					<div className="flex flex-col divide-y divide-border/60 rounded-lg border border-border/60">
						{Object.entries(plugin.mcpServers).map(([name, config]) => (
							<div key={name} className="flex items-center gap-3 p-3">
								<div className="min-w-0 flex-1">
									<div className="flex items-center gap-1.5 text-sm font-medium text-foreground">
										{name}
										<Badge
											variant="outline"
											className="h-4 shrink-0 rounded px-1 text-[9px] font-medium tracking-wide text-muted-foreground uppercase"
										>
											{"url" in config ? "MCP" : "CLI"}
										</Badge>
									</div>
									<p className="truncate font-mono text-xs text-muted-foreground">
										{"url" in config
											? config.url
											: [config.command, ...(config.args ?? [])].join(" ")}
									</p>
								</div>
							</div>
						))}
					</div>
					<p className="text-xs text-muted-foreground">
						Remote servers sign you in the first time an agent uses them.
					</p>
				</section>
			)}
		</div>
	);
}

