		fs.writeFileSync(tmpPath, content, { mode });
		fs.renameSync(tmpPath, filePath);
	} catch (error) {
		try {
			fs.unlinkSync(tmpPath);
		} catch {
			// Best effort.
		}
		throw error;
	}
	try {
		fs.chmodSync(filePath, mode);
	} catch {
		// Best effort.
	}
