","originalFile":"#!/usr/bin/env node

/**
 * (NO-BUNDLED-SKILLS) Blocks upstream's bundled Superset skill system from
 * returning while leaving user-owned and repo-local skill discovery intact.
 */

import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const repoRoot = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");

const FORBIDDEN_PATHS = [
	"plugins/superset",
	"scripts/sync-dev-skills.ts",
	"packages/agent-setup/src/managed-skills.ts",
	"packages/agent-setup/src/disabled-skills.ts",
	"apps/desktop/src/renderer/routes/_authenticated/_dashboard/plugins/components/SkillIcon",
	"apps/desktop/src/renderer/routes/_authenticated/_dashboard/plugins/components/PluginsView/components/SkillsList",
];

const SCAN_ROOTS = [".github", "apps", "packages", "scripts"];
const SCANNED_EXTENSIONS = new Set([
	".js",
	".mjs",
	".json",
	".sh",
	".ts",
	".tsx",
	".yaml",
	".yml",
]);
const EXCLUDED_FILES = new Set([
	"scripts/check-no-bundled-skills.mjs",
	"packages/agent-setup/src/legacy-managed-skills-cleanup.ts",
	"packages/agent-setup/src/legacy-managed-skills-cleanup.test.ts",
]);

const FORBIDDEN_SOURCE_PATTERNS = [
	["bundled plugin source", /plugins[\\/]superset/],
	["managed skill provisioner", /\bcreateManagedSkills\b/],
	["profile plugin provisioner", /\bprovisionManagedClaudePluginAt\b/],
	["bundled skill catalog", /\bSUPERSET_MANAGED_SKILLS\b/],
	["bundled plugin resolver", /\bgetBundledPluginDir\b/],
	["disabled-skill state writer", /\b(?:read|write)SharedDisabledSkillIds\b/],
	["disabled-skill resolver", /\bresolveDisabledSkillIds\b/],
	["disabled-skill environment switch", /\bSUPERSET_DISABLED_SKILLS\b/],
	["bundled skill namespace", /superset:(?:10x|automate|browser|computer|contribute|doctor|feedback|orchestrate|page|setup|standup)\b/],
	["desktop bundled-plugin copy target", /main[\\/]templates[\\/]plugin/],
	["CLI bundled-plugin copy target", /agent-templates[\\/]plugin/],
];

function relativePath(absolute) {
	return path.relative(repoRoot, absolute).split(path.sep).join("/");
}

function listFiles(root) {
	if (!fs.existsSync(root)) return [];
	const files = [];
	for (const entry of fs
		.readdirSync(root, { withFileTypes: true })
		.sort((a, b) => a.name.localeCompare(b.name))) {
		const absolute = path.join(root, entry.name);
		if (entry.isDirectory()) files.push(...listFiles(absolute));
		else if (entry.isFile()) files.push(absolute);
	}
	return files;
}

const failures = [];
for (const forbidden of FORBIDDEN_PATHS) {
	if (fs.existsSync(path.join(repoRoot, forbidden))) {
		failures.push(`${forbidden}: forbidden bundled-skill path exists`);
	}
}

const marketplacePath = path.join(repoRoot, ".claude-plugin", "marketplace.json");
if (fs.existsSync(marketplacePath)) {
	try {
		const marketplace = JSON.parse(fs.readFileSync(marketplacePath, "utf8"));
		const plugins = Array.isArray(marketplace?.plugins) ? marketplace.plugins : [];
		if (
			plugins.some(
				(plugin) =>
					plugin?.name === "superset" ||
					plugin?.source === "./plugins/superset",
			)
		) {
			failures.push(
				".claude-plugin/marketplace.json: bundled Superset plugin entry exists",
			);
		}
	} catch (error) {
		failures.push(
			`.claude-plugin/marketplace.json: cannot validate marketplace: ${error.message}`,
		);
	}
}

for (const root of SCAN_ROOTS) {
	for (const absolute of listFiles(path.join(repoRoot, root))) {
		const relative = relativePath(absolute);
		if (
			EXCLUDED_FILES.has(relative) ||
			!SCANNED_EXTENSIONS.has(path.extname(relative))
		) {
			continue;
		}
		const content = fs.readFileSync(absolute, "utf8");
		for (const [label, pattern] of FORBIDDEN_SOURCE_PATTERNS) {
			if (pattern.test(content)) failures.push(`${relative}: ${label}`);
		}
	}
}

if (failures.length > 0) {
	console.error("(NO-BUNDLED-SKILLS) forbidden Superset skill code found:");
	for (const failure of [...new Set(failures)].sort()) {
		console.error(`- ${failure}`);
	}
	process.exit(1);
}

