import fs from "node:fs";
import os from "node:os";
import path from "node:path";
import { resolveSupersetHomeDir } from "./paths";

// (NO-BUNDLED-SKILLS) Remove only artifacts written by the retired provisioner.
export const LEGACY_MANAGED_SKILL_MARKER =
	"<!-- superset-managed-skill v1 -->";

const LEGACY_SKILL_NAMES = [
	"10x",
	"automate",
	"browser",
	"computer",
	"contribute",
	"doctor",
	"feedback",
	"orchestrate",
	"page",
	"setup",
	"standup",
] as const;

const LEGACY_REPOSITORY = "https://github.com/superset-sh/superset";
const LEGACY_HOMEPAGE = "https://docs.superset.sh";
const LEGACY_AUTHOR_URL = "https://superset.sh";

export interface LegacyManagedSkillsCleanupOptions {
	homeDir?: string;
	supersetHomeDir?: string;
	/** Defaults to the standard ~/.claude config dir. */
	claudeConfigDirs?: readonly string[];
}

export interface LegacyManagedSkillsCleanupReport {
	removed: string[];
	preserved: string[];
}

function isNotFound(error: unknown): boolean {
	return (
		typeof error === "object" &&
		error !== null &&
		"code" in error &&
		(error as { code?: unknown }).code === "ENOENT"
	);
}

function lstatIfExists(target: string): fs.Stats | null {
	try {
		return fs.lstatSync(target);
	} catch (error) {
		if (isNotFound(error)) return null;
		throw error;
	}
}

function readRegularFile(target: string): string | null {
	const stat = lstatIfExists(target);
	if (stat === null || !stat.isFile() || stat.isSymbolicLink()) return null;
	return fs.readFileSync(target, "utf8");
}

function isPlainObject(value: unknown): value is Record<string, unknown> {
	return typeof value === "object" && value !== null && !Array.isArray(value);
}

function parseJsonObject(content: string | null): Record<string, unknown> | null {
	if (content === null) return null;
	try {
		const parsed: unknown = JSON.parse(content);
		return isPlainObject(parsed) ? parsed : null;
	} catch {
		return null;
	}
}

function isRealDirectory(target: string): boolean {
	const stat = lstatIfExists(target);
	return stat !== null && stat.isDirectory() && !stat.isSymbolicLink();
}

function removeDirectory(target: string, report: LegacyManagedSkillsCleanupReport) {
	try {
		fs.rmSync(target, { recursive: true });
		report.removed.push(target);
	} catch (error) {
		if (!isNotFound(error)) throw error;
	}
}

function removeFile(target: string, report: LegacyManagedSkillsCleanupReport) {
	try {
		fs.unlinkSync(target);
		report.removed.push(target);
	} catch (error) {
		if (!isNotFound(error)) throw error;
	}
}

function preserve(target: string, report: LegacyManagedSkillsCleanupReport) {
	if (lstatIfExists(target) !== null) report.preserved.push(target);
}

function cleanupMarkedClaudePlugin(
	claudeDir: string,
	report: LegacyManagedSkillsCleanupReport,
) {
	const target = path.join(claudeDir, "skills", "superset");
	if (!isRealDirectory(target)) {
		preserve(target, report);
		return;
	}
	const sentinel = readRegularFile(path.join(target, ".superset-managed"));
	if (!sentinel?.includes(LEGACY_MANAGED_SKILL_MARKER)) {
		preserve(target, report);
		return;
	}
	removeDirectory(target, report);
}

function hasLegacyDevManifest(target: string): boolean {
	const manifest = parseJsonObject(
		readRegularFile(path.join(target, ".claude-plugin", "plugin.json")),
	);
	if (manifest === null) return false;
	const author = manifest.author;
	return (
		manifest.name === "superset-dev" &&
		manifest.repository === LEGACY_REPOSITORY &&
		manifest.homepage === LEGACY_HOMEPAGE &&
		isPlainObject(author) &&
		author.name === "Superset" &&
		author.url === LEGACY_AUTHOR_URL
	);
}

function cleanupLegacyDevPlugin(
	claudeDir: string,
	report: LegacyManagedSkillsCleanupReport,
) {
	const target = path.join(claudeDir, "skills", "superset-dev");
	if (!isRealDirectory(target)) {
		preserve(target, report);
		return;
	}
	if (!hasLegacyDevManifest(target)) {
		preserve(target, report);
		return;
	}
	removeDirectory(target, report);
}

function cleanupAgentSkillDirs(
	homeDir: string,
	report: LegacyManagedSkillsCleanupReport,
) {
	for (const name of LEGACY_SKILL_NAMES) {
		const target = path.join(homeDir, ".agents", "skills", `superset-${name}`);
		if (!isRealDirectory(target)) {
			preserve(target, report);
			continue;
		}
		const skill = readRegularFile(path.join(target, "SKILL.md"));
		if (!skill?.includes(LEGACY_MANAGED_SKILL_MARKER)) {
			preserve(target, report);
			continue;
		}
		removeDirectory(target, report);
	}
}

function cleanupAgentCommands(
	homeDir: string,
	report: LegacyManagedSkillsCleanupReport,
) {
	const target = path.join(homeDir, ".agents", "commands", "superset");
	if (!isRealDirectory(target)) {
		preserve(target, report);
		return;
	}
	const entries = fs.readdirSync(target, { withFileTypes: true });
	if (
		entries.length === 0 ||
		entries.some((entry) => {
			if (!entry.isFile() || entry.isSymbolicLink()) return true;
			const content = readRegularFile(path.join(target, entry.name));
			return !content?.includes(LEGACY_MANAGED_SKILL_MARKER);
		})
	) {
		preserve(target, report);
		return;
	}
	removeDirectory(target, report);
}

function cleanupDisabledSkillsState(
	supersetHomeDir: string,
	report: LegacyManagedSkillsCleanupReport,
) {
	const target = path.join(supersetHomeDir, "disabled-skills.json");
	const state = parseJsonObject(readRegularFile(target));
	if (state === null) {
		preserve(target, report);
		return;
	}
	const keys = Object.keys(state);
	const disabledSkillIds = state.disabledSkillIds;
	if (
		keys.length !== 1 ||
		keys[0] !== "disabledSkillIds" ||
		!Array.isArray(disabledSkillIds) ||
		!disabledSkillIds.every((value) => typeof value === "string")
	) {
		preserve(target, report);
		return;
	}
	removeFile(target, report);
}

export function cleanupLegacyManagedSkills(
	options: LegacyManagedSkillsCleanupOptions = {},
): LegacyManagedSkillsCleanupReport {
	const homeDir = options.homeDir ?? os.homedir();
	const supersetHomeDir =
		options.supersetHomeDir ??
		(options.homeDir === undefined
			? resolveSupersetHomeDir()
			: path.join(homeDir, ".superset"));
	const claudeConfigDirs = options.claudeConfigDirs ?? [path.join(homeDir, ".claude")];
	const report: LegacyManagedSkillsCleanupReport = {
		removed: [],
		preserved: [],
	};

	for (const claudeDir of new Set(claudeConfigDirs.map((dir) => path.resolve(dir)))) {
		cleanupMarkedClaudePlugin(claudeDir, report);
		cleanupLegacyDevPlugin(claudeDir, report);
	}
	cleanupAgentSkillDirs(homeDir, report);
	cleanupAgentCommands(homeDir, report);
	cleanupDisabledSkillsState(supersetHomeDir, report);

	return report;
}

