import { afterEach, beforeEach, describe, expect, it } from "bun:test";
import fs from "node:fs";
import os from "node:os";
import path from "node:path";
import {
	cleanupLegacyManagedSkills,
	LEGACY_MANAGED_SKILL_MARKER,
} from "./legacy-managed-skills-cleanup";

let root: string;
let homeDir: string;
let supersetHomeDir: string;

function write(target: string, content: string) {
	fs.mkdirSync(path.dirname(target), { recursive: true });
	fs.writeFileSync(target, content);
}

function writeJson(target: string, value: unknown) {
	write(target, `${JSON.stringify(value, null, 2)}\n`);
}

function seedManagedClaudePlugin(claudeDir: string) {
	write(
		path.join(claudeDir, "skills", "superset", ".superset-managed"),
		`${LEGACY_MANAGED_SKILL_MARKER}\n`,
	);
	write(
		path.join(claudeDir, "skills", "superset", "skills", "doctor", "SKILL.md"),
		"legacy",
	);
}

function seedManagedAgentSkill(name: string) {
	write(
		path.join(homeDir, ".agents", "skills", `superset-${name}`, "SKILL.md"),
		`${LEGACY_MANAGED_SKILL_MARKER}\nlegacy`,
	);
}

function seedManagedCommands() {
	for (const name of ["10x", "doctor", "feedback", "setup"]) {
		write(
			path.join(homeDir, ".agents", "commands", "superset", `${name}.md`),
			`${LEGACY_MANAGED_SKILL_MARKER}\nlegacy`,
		);
	}
}

function seedManagedDevPlugin(claudeDir: string) {
	writeJson(
		path.join(
			claudeDir,
			"skills",
			"superset-dev",
			".claude-plugin",
			"plugin.json",
		),
		{
			name: "superset-dev",
			repository: "https://github.com/superset-sh/superset",
			homepage: "https://docs.superset.sh",
			author: { name: "Superset", url: "https://superset.sh" },
		},
	);
}

beforeEach(() => {
	root = fs.mkdtempSync(path.join(os.tmpdir(), "legacy-skill-cleanup-"));
	homeDir = path.join(root, "home");
	supersetHomeDir = path.join(root, "superset-home");
});

afterEach(() => {
	fs.rmSync(root, { recursive: true, force: true });
});

describe("cleanupLegacyManagedSkills", () => {
	it("removes only marker-validated legacy artifacts and is idempotent", () => {
		const claudeDir = path.join(homeDir, ".claude");
		seedManagedClaudePlugin(claudeDir);
		seedManagedDevPlugin(claudeDir);
		seedManagedAgentSkill("doctor");
		seedManagedAgentSkill("page");
		seedManagedCommands();
		writeJson(path.join(supersetHomeDir, "disabled-skills.json"), {
			disabledSkillIds: ["doctor"],
		});

		const first = cleanupLegacyManagedSkills({ homeDir, supersetHomeDir });

		expect(first.removed).toHaveLength(10);
		expect(fs.existsSync(path.join(claudeDir, "skills", "superset"))).toBe(
			false,
		);
		expect(fs.existsSync(path.join(claudeDir, "skills", "superset-dev"))).toBe(
			false,
		);
		expect(
			fs.existsSync(path.join(homeDir, ".agents", "skills", "superset-doctor")),
		).toBe(false);
		expect(
			fs.existsSync(path.join(homeDir, ".agents", "skills", "superset-page")),
		).toBe(false);
		expect(
			fs.existsSync(path.join(homeDir, ".agents", "commands", "superset")),
		).toBe(false);
		expect(
			fs.existsSync(path.join(supersetHomeDir, "disabled-skills.json")),
		).toBe(false);

		expect(
			cleanupLegacyManagedSkills({ homeDir, supersetHomeDir }),
		).toEqual({ removed: [], preserved: [] });
	});

	it("preserves unmarked, mixed, unknown, and malformed paths", () => {
		const claudeDir = path.join(homeDir, ".claude");
		write(
			path.join(claudeDir, "skills", "superset", ".superset-managed"),
			"user-owned",
		);
		seedManagedAgentSkill("doctor");
		write(
			path.join(homeDir, ".agents", "skills", "superset-doctor", "SKILL.md"),
			"user-owned",
		);
		write(
			path.join(homeDir, ".agents", "skills", "superset-custom", "SKILL.md"),
			`${LEGACY_MANAGED_SKILL_MARKER}\ncustom`,
		);
		seedManagedCommands();
		write(
			path.join(homeDir, ".agents", "commands", "superset", "mine.md"),
			"user-owned",
		);
		writeJson(path.join(supersetHomeDir, "disabled-skills.json"), {
			disabledSkillIds: ["doctor"],
			mine: true,
		});
		writeJson(
			path.join(
				claudeDir,
				"skills",
				"superset-dev",
				".claude-plugin",
				"plugin.json",
			),
			{
				name: "superset-dev",
				repository: "https://example.com/user/repo",
				homepage: "https://docs.superset.sh",
				author: { name: "Superset", url: "https://superset.sh" },
			},
		);

		const report = cleanupLegacyManagedSkills({ homeDir, supersetHomeDir });

		expect(report.removed).toHaveLength(4);
		expect(report.preserved).toHaveLength(5);
		expect(fs.existsSync(path.join(claudeDir, "skills", "superset"))).toBe(
			true,
		);
		expect(
			fs.existsSync(path.join(homeDir, ".agents", "skills", "superset-custom")),
		).toBe(true);
		const commandsDir = path.join(homeDir, ".agents", "commands", "superset");
		expect(fs.existsSync(commandsDir)).toBe(true);
		expect(fs.existsSync(path.join(commandsDir, "mine.md"))).toBe(true);
		for (const name of ["10x", "doctor", "feedback", "setup"]) {
			expect(fs.existsSync(path.join(commandsDir, `${name}.md`))).toBe(false);
		}
	});

	it("cleans a direct legacy copy in a custom Claude config dir", () => {
		const customClaudeDir = path.join(root, "claude-profile");
		seedManagedClaudePlugin(customClaudeDir);

		cleanupLegacyManagedSkills({
			homeDir,
			supersetHomeDir,
			claudeConfigDirs: [customClaudeDir],
		});

		expect(
			fs.existsSync(path.join(customClaudeDir, "skills", "superset")),
		).toBe(false);
	});
});

import {
	isPluginExternallyConfigured,
	PLUGIN_CATALOG,
	PLUGIN_CATEGORIES,
	type PluginCatalogEntry,
} from "@superset/shared/plugins";
import { Button } from "@superset/ui/button";
import { Input } from "@superset/ui/input";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@superset/ui/tabs";
import { Tooltip, TooltipContent, TooltipTrigger } from "@superset/ui/tooltip";
import { cn } from "@superset/ui/utils";
import { useNavigate } from "@tanstack/react-router";
import { useMemo, useState } from "react";
import { LuSearch, LuSettings2 } from "react-icons/lu";
import { electronTrpc } from "renderer/lib/electron-trpc";
import { PluginIcon } from "renderer/routes/_authenticated/_dashboard/plugins/components/PluginIcon";
import { usePluginMutations } from "renderer/routes/_authenticated/_dashboard/plugins/hooks/usePluginMutations";
import { ManageInstalledDialog } from "./components/ManageInstalledDialog";
import { PluginCard } from "./components/PluginCard";

export function PluginsView() {
	const [search, setSearch] = useState("");
	const [isManageOpen, setIsManageOpen] = useState(false);
	const navigate = useNavigate();

	const { data: installed } = electronTrpc.plugins.listInstalled.useQuery();
	const installedNames = useMemo(
		() => new Set((installed ?? []).map((entry) => entry.name)),
		[installed],
	);
	const disabledNames = useMemo(
		() =>
			new Set(
				(installed ?? [])
					.filter((entry) => entry.enabled === false)
					.map((entry) => entry.name),
			),
		[installed],
	);
	const { data: externalServers } =
		electronTrpc.plugins.listExternalServers.useQuery();
	// One state: an install record OR the user's own config both count as
	// installed (having it = installed).
	const isInstalled = (plugin: PluginCatalogEntry) =>
		installedNames.has(plugin.name) ||
		isPluginExternallyConfigured(plugin, externalServers ?? []);

	const { install, uninstall, setEnabled, isBusy } = usePluginMutations();

	const handleOpen = (plugin: PluginCatalogEntry) => {
		navigate({
			to: "/plugins/$pluginName",
			params: { pluginName: plugin.name },
		});
	};

	const query = search.trim().toLowerCase();
	const visiblePlugins = useMemo(() => {
		if (query === "") return [...PLUGIN_CATALOG];
		return PLUGIN_CATALOG.filter((plugin) =>
			[
				plugin.name,
				plugin.interface.displayName,
				plugin.description,
				plugin.interface.category,
			]
				.join(" ")
				.toLowerCase()
				.includes(query),
		);
	}, [query]);

	const installedPlugins = visiblePlugins.filter(isInstalled);
	const featured = visiblePlugins.filter((plugin) => plugin.featured);
	// Featured plugins appear in their category section too — Featured is a
	// spotlight, not a home.
	const byCategory = PLUGIN_CATEGORIES.map((category) => ({
		category,
		plugins: visiblePlugins.filter(
			(plugin) => plugin.interface.category === category,
		),
	})).filter(({ plugins }) => plugins.length > 0);

	const renderCard = (plugin: PluginCatalogEntry) => (
		<PluginCard
			key={plugin.name}
			plugin={plugin}
			isInstalled={isInstalled(plugin)}
			isDisabled={disabledNames.has(plugin.name)}
			isBusy={isBusy}
			onOpen={handleOpen}
			onInstall={(target) => install(target.name)}
			onUninstall={(target) => uninstall(target.name)}
			onSetEnabled={setEnabled}
		/>
	);

	return (
		<div className="mx-auto w-full max-w-3xl px-6 pb-16">
			<Tabs defaultValue="plugins">
				<TabsList className="mb-6">
					<TabsTrigger value="plugins">Plugins</TabsTrigger>
				</TabsList>

				<TabsContent value="plugins" className="flex flex-col gap-6">
					<div>
						<h1 className="text-2xl font-semibold text-foreground">Plugins</h1>
						<p className="mt-1 text-sm text-muted-foreground">
							Work with your agents across your favorite tools
						</p>
					</div>

					<div className="relative">
						<LuSearch className="absolute top-1/2 left-3 size-4 -translate-y-1/2 text-muted-foreground" />
						<Input
							value={search}
							onChange={(event) => setSearch(event.target.value)}
							placeholder="Search plugins"
							className="rounded-full pl-9"
						/>
					</div>

					{installedPlugins.length > 0 && (
						<section className="flex flex-col gap-3">
							<div className="flex items-center justify-between">
								<h2 className="text-sm font-semibold text-foreground">
									Installed
								</h2>
								<Tooltip delayDuration={300}>
									<TooltipTrigger asChild>
										<Button
											variant="ghost"
											size="icon-xs"
											className="text-muted-foreground"
											aria-label="Manage plugins"
											onClick={() => setIsManageOpen(true)}
										>
											<LuSettings2 className="size-4" />
										</Button>
									</TooltipTrigger>
									<TooltipContent>Manage plugins</TooltipContent>
								</Tooltip>
							</div>
							<div className="flex flex-wrap gap-2">
								{installedPlugins.map((plugin) => (
									<Tooltip key={plugin.name} delayDuration={300}>
										<TooltipTrigger asChild>
											<button
												type="button"
												aria-label={plugin.interface.displayName}
												onClick={() => handleOpen(plugin)}
												className={cn(
													disabledNames.has(plugin.name) && "opacity-40",
												)}
											>
												<PluginIcon
													pluginName={plugin.name}
													className="size-8"
												/>
											</button>
										</TooltipTrigger>
										<TooltipContent>
											{plugin.interface.displayName}
											{disabledNames.has(plugin.name) ? " (disabled)" : ""}
										</TooltipContent>
									</Tooltip>
								))}
							</div>
						</section>
					)}

					{featured.length > 0 && (
						<section className="flex flex-col gap-3">
							<h2 className="text-sm font-semibold text-foreground">
								Featured
							</h2>
							<div className="grid grid-cols-1 gap-2 md:grid-cols-2">
								{featured.map(renderCard)}
							</div>
						</section>
					)}

					{byCategory.map(({ category, plugins }) => (
						<section key={category} className="flex flex-col gap-3">
							<h2 className="text-sm font-semibold text-foreground">
