/**
 * Keeps the selected provider accounts provisioned — see
 * packages/agent-setup/src/provider-profiles.ts for what that means. Split
 * from default-account.ts so the terminal's env-resolution path (loaded by
 * node --test) doesn't pull the whole agent-setup surface in.
 */

import { existsSync } from "node:fs";
import {
	provisionClaudeProfile,
	provisionCodexProfile,
} from "@superset/agent-setup";
import type { HostDb } from "../../../db/index.ts";
import {
	getDefaultAccountSelections,
	syncDefaultAccountPointers,
} from "./default-account.ts";
import { shareClaudeSessionState } from "./session-share.ts";

/**
 * Everything a Claude account needs on this host: the shared session state
 * (one `--resume` history across accounts — session-share.ts) plus the
 * config surfaces agent-setup shares (plugins, settings, MCP servers, and
 * user-owned capabilities).
 */
export async function provisionClaudeAccount(configDir: string): Promise<void> {
	shareClaudeSessionState(configDir);
	await provisionClaudeProfile(configDir);
}

/**
 * Re-shares the default account's config into whichever profiles are
 * currently selected. Runs at host boot so a profile keeps up with plugins,
 * settings, and user-owned capabilities added since it was selected, and so
 * one provisioned by an older build — or by a switch that failed halfway — is repaired
 * before the next agent launches on it.
 */
export async function provisionSelectedAccounts(db: HostDb): Promise<void> {
	// Heal the wrapper pointer files first — a build predating them (or a
	// crashed switch) leaves agents launching on a stale spawn-time default.
	syncDefaultAccountPointers(db);
	const { claudeConfigDir, codexHome } = getDefaultAccountSelections(db);
	const targets: Array<readonly [string, () => Promise<unknown>]> = [];
	// A pointer at a vanished dir is skipped, not recreated: agent launches
	// already fall back to the system-default login in that case.
	if (claudeConfigDir && existsSync(claudeConfigDir)) {
		targets.push([
			claudeConfigDir,
			() => provisionClaudeAccount(claudeConfigDir),
		]);
	}
	if (codexHome && existsSync(codexHome)) {
		targets.push([codexHome, () => provisionCodexProfile(codexHome)]);
	}
	for (const [dir, provision] of targets) {
		try {
			await provision();
		} catch (error) {
			console.warn(
				`[host-service] provisioning the selected account ${dir} failed (continuing):`,
				error,
			);
		}
	}
}

import fs from "node:fs";
import {
	runSetupAction,
	setupAgentCapabilities,
	setupSingleAgent,
	teardownSingleAgent,
} from "./agent-setup";
import { resolveDisabledAgentIds } from "./disabled-agent-hooks";
import { cleanupLegacyManagedSkillsHome } from "./legacy-managed-skills-cleanup";
import {
	getBashDir,
	getBinDir,
	getHooksDir,
	getOpenCodePluginDir,
	getZshDir,
} from "./paths";
import {
	createBashWrapper,
	createPwshWrapper,
	createZshWrapper,
	getCommandShellArgs,
	getShellArgs,
	getShellEnv,
} from "./shell-wrappers";

/**
 * Provisions everything Superset manages in the user's environment for the
 * supported terminal agents: lifecycle hooks, binary wrappers, and shell
 * integration. Agents in `options.disabledAgentIds` get their global-config
 * footprint removed instead. Runs on every host that serves terminals — the
 * Electron main process and the standalone (CLI-launched) host-service alike.
 *
 * Callers without their own settings store (headless hosts) omit
 * `disabledAgentIds`; the shared ~/.superset agent-hooks.json mirror and its
 * SUPERSET_DISABLED_AGENT_HOOKS env override apply instead, so a machine
 * running both the desktop and CLI hosts converges on one disable set.
 */
export function setupAgentIntegrations(
	options: { disabledAgentIds?: readonly string[] } = {},
): void {
	console.log("[agent-setup] Provisioning agent integrations...");
	const disabledAgentIds = resolveDisabledAgentIds(options.disabledAgentIds);

	// Keep the legacy disk sweep off the synchronous Electron startup path.
	setImmediate(() => {
		runSetupAction("legacy-managed-skills-cleanup", () => {
			const removed = cleanupLegacyManagedSkillsHome();
			if (removed.length > 0) {
				console.log(
					`[agent-setup] Removed ${removed.length} retired managed-skill path(s)`,
				);
			}
		});
	});

	fs.mkdirSync(getBinDir(), { recursive: true });
	fs.mkdirSync(getHooksDir(), { recursive: true });
	fs.mkdirSync(getZshDir(), { recursive: true });
	fs.mkdirSync(getBashDir(), { recursive: true });
	fs.mkdirSync(getOpenCodePluginDir(), { recursive: true });

	setupAgentCapabilities({ disabledAgentIds });

	runSetupAction("zsh-wrapper", createZshWrapper);
	runSetupAction("bash-wrapper", createBashWrapper);
	// (AY) PowerShell integration profile (OSC 133 C/D/A markers for the
	// shell-running blue dot). Written on every launch like the others.
	runSetupAction("pwsh-wrapper", createPwshWrapper);

	console.log("[agent-setup] Agent integrations provisioned");
}

export { setupSingleAgent, teardownSingleAgent };

export {
	ensureClaudeManagedHooksAt,
	ensureCodexManagedHooksAt,
} from "./agent-wrappers-claude-codex-opencode";
export {
	type ProfileProvisionReport,
	provisionClaudeProfile,
	provisionCodexProfile,
} from "./provider-profiles";

export { getCommandShellArgs, getShellArgs, getShellEnv };

export {
	getAgentSetupTemplatesDir,
	setAgentSetupTemplatesDir,
} from "./config";
export {
	readSharedDisabledAgentIds,
	writeSharedDisabledAgentIds,
} from "./disabled-agent-hooks";
export {
	readExternallyConfiguredMcpServers,
	type SyncManagedMcpServersOptions,
	syncManagedMcpServers,
} from "./managed-mcp-servers";
export { getBinDir, resolveSupersetHomeDir } from "./paths";

/**
 * Makes a provider account (a CLAUDE_CONFIG_DIR / CODEX_HOME profile dir) a
 * complete environment rather than a bare login.
 *
 * The CLIs read *everything* — skills, plugins, subagents, commands, MCP
 * servers, settings — from their active config dir, so pointing one at a
 * second dir to switch accounts also swapped the user's whole setup for an
 * empty one. Provisioning shares each of those surfaces from the default
 * account (see profile-sharing.ts for the link/sync/merge rules) and leaves
 * exactly one thing per-account: the login, plus the transcript and session
 * state that belongs to it.
 *
 * Idempotent and safe to re-run: it is called when an account is added, when
 * one is selected, and for the selected accounts at host boot.
 */

import fs from "node:fs";
import os from "node:os";
import path from "node:path";
import {
	ensureClaudeManagedHooksAt,
	ensureCodexManagedHooksAt,
} from "./agent-wrappers-claude-codex-opencode";
import { cleanupLegacyClaudeConfigDir } from "./legacy-managed-skills-cleanup";
import {
	linkSharedDir,
	mergeSharedJsonKeys,
	readProfileLedger,
	type SurfaceOutcome,
	syncSharedFile,
	writeProfileLedger,
} from "./profile-sharing";

export interface ProfileProvisionReport {
	configDir: string;
	/** Surface name -> what provisioning did with it, for setup logs. */
	surfaces: Record<string, SurfaceOutcome>;
}

export interface ProvisionProfileOptions {
	/** Overridden in tests; the real home in every other caller. */
	homeDir?: string;
}

function isPlainObject(value: unknown): value is Record<string, unknown> {
	return typeof value === "object" && value !== null && !Array.isArray(value);
}

/** Real path when the dir exists, plain resolution otherwise — a symlink
 * alias of a protected dir must compare equal to it. */
function canonical(target: string): string {
	try {
		return fs.realpathSync(target);
	} catch {
		return path.resolve(target);
	}
}

/**
 * True for the share's source and the other default homes — provisioning a
 * default home would link it into itself (discovery excludes them, but a
 * CLAUDE_CONFIG_DIR env entry can name one directly, including via symlink).
 */
function isProtectedTarget(
	target: string,
	homeDir: string,
	defaultDir: string,
): boolean {
	const resolved = canonical(target);
	const protectedDirs = [
		homeDir,
		defaultDir,
		path.join(homeDir, ".config"),
		path.join(homeDir, ".config", "claude"),
	];
	return protectedDirs.some((dir) => resolved === canonical(dir));
}

function logReport(provider: string, report: ProfileProvisionReport): void {
	const summary = Object.entries(report.surfaces)
		.map(([surface, outcome]) => `${surface}=${outcome}`)
		.join(" ");
	console.log(
		`[agent-setup] Provisioned ${provider} account ${report.configDir}: ${summary}`,
	);
}

// ---------------------------------------------------------------------------
// Claude Code
// ---------------------------------------------------------------------------

/**
 * Directories shared by symlink. Everything Claude Code loads as user-level
 * capability lives in one of these; what's left in a config dir is the login
 * and its own history (projects/, sessions/, shell-snapshots/, …).
 */
const CLAUDE_SHARED_DIRS = [
	"skills",
	"plugins",
	"agents",
	"commands",
	"output-styles",
] as const;

/** Files copied verbatim (the CLI rename-replaces them, so no symlink). */
const CLAUDE_SHARED_FILES = ["CLAUDE.md"] as const;

/**
 * settings.json keys that must NOT follow the account. Everything else is
 * shared by default so a key added by a future CLI release comes along
 * without a code change here.
 */
const CLAUDE_PRIVATE_SETTINGS_KEYS = new Set([
	// Provisioned per profile right after the merge — the hooks are identical,
	// but they are ours to write, not the user's to share.
	"hooks",
	// Auth resolution: sharing these would let one account's credential
	// mechanism silently answer for another.
	"apiKeyHelper",
	"awsAuthRefresh",
	"awsCredentialExport",
	"forceLoginMethod",
	"forceLoginOrgUUID",
]);

/** `env` entries holding a credential; the rest of `env` is shared. */
const CLAUDE_PRIVATE_ENV_KEYS = new Set([
	"ANTHROPIC_API_KEY",
	"ANTHROPIC_AUTH_TOKEN",
	"CLAUDE_CODE_OAUTH_TOKEN",
]);

/**
 * `.claude.json` keys that are shared — an allowlist, inverted from
 * settings.json on purpose: that file is mostly identity (oauthAccount,
 * userID), per-project transcript history, and server-driven caches, none of
 * which may cross accounts.
 */
const CLAUDE_SHARED_STATE_KEYS = ["mcpServers", "theme"] as const;

function pickClaudeSettings(
	source: Record<string, unknown>,
): Record<string, unknown> {
	const shared: Record<string, unknown> = {};
	for (const [key, value] of Object.entries(source)) {
		if (CLAUDE_PRIVATE_SETTINGS_KEYS.has(key)) continue;
		if (key === "env" && isPlainObject(value)) {
			shared.env = Object.fromEntries(
				Object.entries(value).filter(
					([name]) => !CLAUDE_PRIVATE_ENV_KEYS.has(name),
				),
			);
			continue;
		}
		shared[key] = value;
	}
	return shared;
}

function pickClaudeState(
	source: Record<string, unknown>,
): Record<string, unknown> {
	const shared: Record<string, unknown> = {};
	for (const key of CLAUDE_SHARED_STATE_KEYS) {
		if (key in source) shared[key] = source[key];
	}
	return shared;
}

/**
 * Brings one Claude config dir up to date with the default account. A no-op
 * for `~/.claude` itself, which is the source of every share.
 */
export async function provisionClaudeProfile(
	configDir: string,
	options: ProvisionProfileOptions = {},
): Promise<ProfileProvisionReport> {
	const homeDir = options.homeDir ?? os.homedir();
	const defaultDir = path.join(homeDir, ".claude");
	const target = path.resolve(configDir);
	const surfaces: Record<string, SurfaceOutcome> = {};
	if (isProtectedTarget(target, homeDir, defaultDir)) {
		return { configDir: target, surfaces };
	}

	cleanupLegacyClaudeConfigDir(target);
	fs.mkdirSync(target, { recursive: true });
	const ledger = readProfileLedger(target, defaultDir);

	for (const name of CLAUDE_SHARED_DIRS) {
		surfaces[`${name}/`] = linkSharedDir(
			path.join(defaultDir, name),
			path.join(target, name),
		);
	}
	for (const name of CLAUDE_SHARED_FILES) {
		surfaces[name] = syncSharedFile({
			sourcePath: path.join(defaultDir, name),
			targetPath: path.join(target, name),
			surface: name,
			ledger,
		});
	}

	surfaces["settings.json"] = mergeSharedJsonKeys({
		sourcePath: path.join(defaultDir, "settings.json"),
		targetPath: path.join(target, "settings.json"),
		surface: "settings.json",
		ledger,
		pick: pickClaudeSettings,
	});

	// Only the default account keeps its state next door at `~/.claude.json`;
	// a custom config dir keeps it inside.
	surfaces[".claude.json"] = mergeSharedJsonKeys({
		sourcePath: path.join(homeDir, ".claude.json"),
		targetPath: path.join(target, ".claude.json"),
		surface: ".claude.json",
		ledger,
		pick: pickClaudeState,
		// Without this the profile's first launch opens the first-boot wizard,
		// where a stray Enter starts a login that silently rebinds the profile.
		force: { hasCompletedOnboarding: true },
		// No parsable state file means no completed login yet — writing one
		// would fabricate an account that doesn't exist.
		requireExistingTarget: true,
	});

	writeProfileLedger(target, ledger);
	// After the settings merge: the merge only writes shared keys, and the
	// hook entries have to survive it.
	ensureClaudeManagedHooksAt(target);

	const report = { configDir: target, surfaces };
	logReport("Claude", report);
	return report;
}

// ---------------------------------------------------------------------------
// Codex
// ---------------------------------------------------------------------------

/** `prompts/` holds custom slash-command prompts; the rest of a Codex home
 * is auth, history, and rollouts. */
const CODEX_SHARED_DIRS = ["prompts"] as const;

/**
 * `config.toml` carries the model, approval policy, and MCP servers;
 * `AGENTS.md` the global instructions. Neither holds credentials — Codex
 * keeps those in `auth.json`, which stays per-account.
 */
const CODEX_SHARED_FILES = ["config.toml", "AGENTS.md"] as const;

function defaultCodexHome(homeDir: string, homeDirOverridden: boolean): string {
	// An overridden homeDir (tests) must win over the ambient CODEX_HOME, or
	// the provision would share from the real machine's Codex home.
	if (homeDirOverridden) return path.join(homeDir, ".codex");
	const fromEnv = process.env.CODEX_HOME?.trim();
	return fromEnv ? path.resolve(fromEnv) : path.join(homeDir, ".codex");
}

/** Brings one Codex home up to date with the default one. */
export async function provisionCodexProfile(
	home: string,
	options: ProvisionProfileOptions = {},
): Promise<ProfileProvisionReport> {
	const homeDir = options.homeDir ?? os.homedir();
	const defaultDir = defaultCodexHome(homeDir, options.homeDir !== undefined);
	const target = path.resolve(home);
	const surfaces: Record<string, SurfaceOutcome> = {};
	if (isProtectedTarget(target, homeDir, defaultDir)) {
		return { configDir: target, surfaces };
	}

	fs.mkdirSync(target, { recursive: true });
	const ledger = readProfileLedger(target, defaultDir);

	for (const name of CODEX_SHARED_DIRS) {
		surfaces[`${name}/`] = linkSharedDir(
			path.join(defaultDir, name),
			path.join(target, name),
		);
	}
	for (const name of CODEX_SHARED_FILES) {
		surfaces[name] = syncSharedFile({
			sourcePath: path.join(defaultDir, name),
			targetPath: path.join(target, name),
			surface: name,
			ledger,
		});
	}

	writeProfileLedger(target, ledger);
	ensureCodexManagedHooksAt(target);

	const report = { configDir: target, surfaces };
	logReport("Codex", report);
	return report;
}

import type { McpServer } from "@modelcontextprotocol/sdk/server/mcp.js";
import {
	ANCHOR_MESSAGE,
	hasCompleteWorkspaceLink,
	isAnchoredPublish,
	pageFields,
	WORKSPACE_LINK_MESSAGE,
} from "@superset/trpc/page-schema";
import { z } from "zod";
import { createMcpCaller } from "../../caller";
import { defineTool } from "../../define-tool";
import { optionalish } from "../../optionalish";

export function register(server: McpServer): void {
	defineTool(server, {
		name: "pages_publish",
		annotations: { destructiveHint: false },
		description:
			"Publish an HTML document as a page and return its public URL. Pages render in a locked-down iframe (no `allow-same-origin`, so every storage API throws on access) and a document that ignores those constraints looks correct locally and breaks silently once published. A page is ONE self-contained file: inline every stylesheet and script, and embed images as data: URIs — external references will not resolve. Every call creates a new version; pass `pageId` to add a version to an existing page instead of creating a new one. Pass the document itself in `html`, not a file path. Every page belongs to a workspace: pass `workspaceId` (from `$SUPERSET_WORKSPACE_ID`, or `superset workspaces list`) plus an `entryPath` naming where the page lives in it.",
		inputSchema: z
			.object({
				html: z
					.string()
					.min(1)
					.describe(
						"The complete HTML document, as text. Must be self-contained.",
					),
				filename: optionalish(pageFields.filename).describe(
					"Filename recorded for this version, e.g. `report.html`. Defaults to `page.html`.",
				),
				pageId: optionalish(pageFields.id).describe(
					"Publish a new version of this existing page. Omit to create a new page.",
				),
				title: optionalish(pageFields.title).describe(
					"Page title. Defaults to the filename.",
				),
				description: optionalish(pageFields.description).describe(
					"Short description shown alongside the page.",
				),
				label: optionalish(pageFields.label).describe(
					"What changed in this version, shown in the version history. Display-only.",
				),
				visibility: optionalish(pageFields.visibility).describe(
					"`org` lets anyone in the organization open it; `just_me` keeps it private to the publisher.",
				),
				workspaceId: pageFields.workspaceId.describe(
					"The workspace this page belongs to. Required: a page that names no workspace is listed by nothing and cannot be versioned later. Get it from the `SUPERSET_WORKSPACE_ID` environment variable, or by running `superset workspaces list`.",
				),
				entryPath: optionalish(pageFields.entryPath).describe(
					"Where this page lives in the workspace, as a path relative to the workspace root, e.g. `reports/q3-pipeline.html`. Together with `workspaceId` it is the key a later publish reuses to add a version rather than minting a second page, so reuse the same value when updating. Required unless `pageId` is given.",
				),
			})
			.refine(hasCompleteWorkspaceLink, WORKSPACE_LINK_MESSAGE)
			.refine(isAnchoredPublish, ANCHOR_MESSAGE),
		handler: async (input, ctx) => {
			const caller = createMcpCaller(ctx);
			const { html, filename, description, label, ...rest } = input;

			return caller.page.publish({
				...rest,
				content: Buffer.from(html, "utf8").toString("base64"),
				contentType: "text/html",
				filename: filename ?? "page.html",
				// These two are the only fields where "" passes validation, and
				// republish patches on `!== undefined` — so forwarding an empty
				// string would silently wipe an existing value. Treat it as unset.
				...(description ? { description } : {}),
				...(label ? { label } : {}),
			});
		},
	});
}

import { afterEach, beforeEach, describe, expect, it } from "bun:test";
import fs from "node:fs";
import os from "node:os";
import path from "node:path";
import {
	cleanupLegacyClaudeConfigDir,
	cleanupLegacyManagedSkillsHome,
	LEGACY_MANAGED_SKILL_MARKER,
} from "./legacy-managed-skills-cleanup";

let root: string;
let homeDir: string;
let supersetHomeDir: string;

function write(target: string, content: string): void {
	fs.mkdirSync(path.dirname(target), { recursive: true });
	fs.writeFileSync(target, content);
}

function writeJson(target: string, value: unknown): void {
	write(target, `${JSON.stringify(value, null, 2)}\n`);
}

function seedManagedClaudePlugin(claudeDir: string, name = "superset"): void {
	write(
		path.join(claudeDir, "skills", name, ".superset-managed"),
		`${LEGACY_MANAGED_SKILL_MARKER}\n`,
	);
	write(
		path.join(claudeDir, "skills", name, "skills", "doctor", "SKILL.md"),
		"legacy",
	);
}

function seedManagedAgentSkill(name: string): void {
	write(
		path.join(homeDir, ".agents", "skills", name, "SKILL.md"),
		`${LEGACY_MANAGED_SKILL_MARKER}\nlegacy`,
	);
}

function seedManagedCommands(): void {
	for (const name of ["10x", "doctor", "feedback", "setup"]) {
		write(
			path.join(homeDir, ".agents", "commands", "superset", `${name}.md`),
			`${LEGACY_MANAGED_SKILL_MARKER}\nlegacy`,
		);
	}
}

beforeEach(() => {
	root = fs.mkdtempSync(path.join(os.tmpdir(), "legacy-skill-cleanup-"));
	homeDir = path.join(root, "home");
	supersetHomeDir = path.join(root, "superset-home");
});

afterEach(() => {
	fs.rmSync(root, { recursive: true, force: true });
});

describe("legacy managed skill cleanup", () => {
	it("removes marker-owned legacy artifacts and is idempotent", () => {
		const claudeDir = path.join(homeDir, ".claude");
		seedManagedClaudePlugin(claudeDir);
		seedManagedAgentSkill("superset-doctor");
		seedManagedAgentSkill("superset-page");
		seedManagedCommands();
		writeJson(path.join(supersetHomeDir, "disabled-skills.json"), {
			disabledSkillIds: ["doctor"],
		});

		const first = cleanupLegacyManagedSkillsHome({
			homeDir,
			supersetHomeDir,
		});

		expect(first).toHaveLength(9);
		expect(fs.existsSync(path.join(claudeDir, "skills", "superset"))).toBe(
			false,
		);
		expect(
			fs.existsSync(path.join(homeDir, ".agents", "skills", "superset-doctor")),
		).toBe(false);
		expect(
			fs.existsSync(path.join(homeDir, ".agents", "skills", "superset-page")),
		).toBe(false);
		expect(
			fs.existsSync(path.join(homeDir, ".agents", "commands", "superset")),
		).toBe(false);
		expect(
			fs.existsSync(path.join(supersetHomeDir, "disabled-skills.json")),
		).toBe(false);

		expect(
			cleanupLegacyManagedSkillsHome({ homeDir, supersetHomeDir }),
		).toEqual([]);
	});

	it("preserves user files while removing marker-owned siblings", () => {
		const claudeDir = path.join(homeDir, ".claude");
		write(
			path.join(claudeDir, "skills", "superset", ".superset-managed"),
			"user-owned",
		);
		write(
			path.join(homeDir, ".agents", "skills", "superset-doctor", "SKILL.md"),
			"user-owned",
		);
		seedManagedAgentSkill("superset-retired");
		seedManagedCommands();
		write(
			path.join(homeDir, ".agents", "commands", "superset", "mine.md"),
			"user-owned",
		);
		writeJson(path.join(supersetHomeDir, "disabled-skills.json"), {
			disabledSkillIds: ["doctor"],
			mine: true,
		});

		const removed = cleanupLegacyManagedSkillsHome({
			homeDir,
			supersetHomeDir,
		});

		expect(removed).toHaveLength(5);
		expect(fs.existsSync(path.join(claudeDir, "skills", "superset"))).toBe(
			true,
		);
		expect(
			fs.existsSync(path.join(homeDir, ".agents", "skills", "superset-doctor")),
		).toBe(true);
		expect(
			fs.existsSync(
				path.join(homeDir, ".agents", "skills", "superset-retired"),
			),
		).toBe(false);
		const commandsDir = path.join(homeDir, ".agents", "commands", "superset");
		expect(fs.existsSync(path.join(commandsDir, "mine.md"))).toBe(true);
		for (const name of ["10x", "doctor", "feedback", "setup"]) {
			expect(fs.existsSync(path.join(commandsDir, `${name}.md`))).toBe(false);
		}
		expect(
			fs.existsSync(path.join(supersetHomeDir, "disabled-skills.json")),
		).toBe(true);
	});

	it("cleans direct legacy copies in custom Claude config dirs", () => {
		const customClaudeDir = path.join(root, "claude-profile");
		seedManagedClaudePlugin(customClaudeDir, "superset-retired");

		cleanupLegacyClaudeConfigDir(customClaudeDir);

		expect(
			fs.existsSync(path.join(customClaudeDir, "skills", "superset-retired")),
		).toBe(false);
	});
});

