node <<'NODE'
const fs = require('fs');
const path = require('path');
const os = require('os');
const marker = '<!-- superset-managed-skill v1 -->';
const home = os.homedir();
const hits = [];
function scanDirs(root, sentinelName) {
  if (!fs.existsSync(root)) return;
  for (const entry of fs.readdirSync(root, { withFileTypes: true })) {
    if (!entry.isDirectory() || entry.isSymbolicLink()) continue;
    const sentinel = path.join(root, entry.name, sentinelName);
    if (fs.existsSync(sentinel) && fs.lstatSync(sentinel).isFile() && fs.readFileSync(sentinel, 'utf8').includes(marker)) hits.push(path.join(root, entry.name));
  }
}
scanDirs(path.join(home, '.claude', 'skills'), '.superset-managed');
scanDirs(path.join(home, '.agents', 'skills'), 'SKILL.md');
const commands = path.join(home, '.agents', 'commands', 'superset');
if (fs.existsSync(commands) && fs.lstatSync(commands).isDirectory()) {
  for (const entry of fs.readdirSync(commands, { withFileTypes: true })) {
    const target = path.join(commands, entry.name);
    if (entry.isFile() && fs.readFileSync(target, 'utf8').includes(marker)) hits.push(target);
  }
}
const disabled = path.join(home, '.superset', 'disabled-skills.json');
if (fs.existsSync(disabled)) hits.push(disabled);
if (hits.length) {
  console.error('Superset-managed skill artifacts remain:\n' + hits.map((v) => '- ' + v).join('\n'));
  process.exit(1);
}
console.log('No Superset-managed skill copies remain in Claude, agents, commands, or Superset state.');
