220	 * `terminalAction` is the whole difference between the two callers. Sidebar
221	 * REMOVAL only `release`s — it detaches the renderer view and leaves the host
222	 * PTY running, because a removed row is a display decision the user can undo by
223	 * re-opening the workspace. (WORKTREE-EXIT-CLEANUP) An EXIT is not: the user is
224	 * done with the thread, so the terminal runtime is `dispose`d outright (which
225	 * also tells host-service to kill the session and clears the persisted
226	 * snapshot, so nothing survives to be restored). Browser panes are destroyed
227	 * either way — they hold no host-side session.
228	 */
229	function cleanupWorkspacePaneRuntimes(
230		rows: PaneLifecycleRow[],
231		terminalAction: "release" | "dispose" = "release",
232	): void {
233		for (const terminalId of extractPaneIds(rows, getTerminalRuntimeId)) {
234			if (terminalAction === "dispose")
235				terminalRuntimeRegistry.dispose(terminalId);
236			else terminalRuntimeRegistry.release(terminalId);
237		}
238		for (const browserId of extractPaneIds(rows, getBrowserRuntimeId)) {
239			browserRuntimeRegistry.destroy(browserId);
240		}
241	}
