 * `terminalAction` is the whole difference between the two callers. Sidebar
 * REMOVAL only `release`s — it detaches the renderer view and leaves the host
 * PTY running, because a removed row is a display decision the user can undo by
 * re-opening the workspace. (WORKTREE-EXIT-CLEANUP) An EXIT is not: the user is
 * done with the thread, so the terminal runtime is `dispose`d outright (which
 * also tells host-service to kill the session and clears the persisted
 * snapshot, so nothing survives to be restored). Browser panes are destroyed
 * either way — they hold no host-side session.
 */
function cleanupWorkspacePaneRuntimes(
	rows: PaneLifecycleRow[],
	terminalAction: "release" | "dispose" = "release",
): void {
	for (const terminalId of extractPaneIds(rows, getTerminalRuntimeId)) {
		if (terminalAction === "dispose")
			terminalRuntimeRegistry.dispose(terminalId);
		else terminalRuntimeRegistry.release(terminalId);
	}
	for (const browserId of extractPaneIds(rows, getBrowserRuntimeId)) {
		browserRuntimeRegistry.destroy(browserId);
	}
}

/**
 * (WORKTREE-EXIT-CLEANUP) Tear down the renderer half of a workspace the user
 * has exited. Call this immediately BEFORE the row update that wipes
 * `paneLayout` — the pane ids it needs live in the layout it is about to clear.
 * A row-less workspace (an insert branch) has no panes to dispose, only the
 * host's half to request.
 */
function disposeExitedWorkspaceRuntimes(
	collections: AppCollections,
	workspaceId: string,
): void {
	const existing = collections.v2WorkspaceLocalState.get(workspaceId);
	if (existing) cleanupWorkspacePaneRuntimes([existing], "dispose");
}

/**
 * (WORKTREE-EXIT-CLEANUP) Exit a workspace row that already exists — Archive,
 * Snooze, Recycle Bin and Completed all end here, and none of them owns any of
 * the four steps below.
 *
 * ONE TIMESTAMP FOR THE WHOLE ACTION, read here and handed to `applyExitFlags`.
 * The pending stamp IDENTIFIES the debt, so the lifecycle stamp a caller writes
 * (`archivedAt`, `deletedAt`) has to name the same instant the cleanup stamp
 * does — a second `Date.now()` would stamp a debt no host reply could quote.
 *
 * THE ORDER IS LOAD-BEARING. Renderer runtimes are disposed BEFORE the update,
 * because the pane ids they need live in the `paneLayout` the update clears.
 *
 * ROW-LESS WORKSPACES NEVER REACH HERE: with no row there are no panes to
 * dispose and nothing to update, so each caller's insert branch stamps
 * {@link workspaceExitCleanupState} on the row it creates instead — its host
 * may still be running terminals and holding a pinned account for it.
 */
