42	// absent from the merged host lists before the card row is pruned.
43	const PRUNE_MISSING_GRACE_MS = 10 * 60_000;
44	
45	// (DEADLINE-TIE-ORDER) Within a deadline tie group (same due day, or the
46	// no-deadline tail): cards the user explicitly drag-ordered in deadline mode
47	// (deadlineTabOrder set) come first in that order; never-ordered cards (new
48	// arrivals, changed deadlines, column moves) follow underneath in manual
49	// tabOrder. The manual order itself is never touched from deadline mode.
50	function deadlineTieBreak(a: KanbanCardView, b: KanbanCardView): number {
51		const oa = a.card.deadlineTabOrder;
52		const ob = b.card.deadlineTabOrder;
53		if (oa != null && ob != null) {
54			return oa - ob || a.card.tabOrder - b.card.tabOrder;
55		}
56		if (oa != null) return -1;
57		if (ob != null) return 1;
58		return a.card.tabOrder - b.card.tabOrder;
59	}
60	
61	// (KANBAN COMPLETED) The Completed column ignores sortMode entirely: most
62	// recently completed first (ties by manual tabOrder). Intra-column drags are
63	// no-ops there, so there is no manual order to preserve.
64	function sortCompletedCards(cards: KanbanCardView[]): KanbanCardView[] {
65		return [...cards].sort(
66			(a, b) =>
67				(b.card.completedAt ?? 0) - (a.card.completedAt ?? 0) ||
68				a.card.tabOrder - b.card.tabOrder,
69		);
70	}
71	
72	function sortCards(
73		cards: KanbanCardView[],
74		sortMode: string,
75	): KanbanCardView[] {
76		const next = [...cards];
77		if (sortMode === "deadline") {
78			// Display-only: soonest due DAY first (deadlineGroupKey — the same group
79			// identity the board's drag handler uses), no-deadline last; within a tie
80			// group the deadline-mode drag order wins (see deadlineTieBreak) and the
81			// manual tabOrder is preserved untouched underneath.
82			next.sort((a, b) => {
83				const ka = deadlineGroupKey(a.card.deadline);
84				const kb = deadlineGroupKey(b.card.deadline);
85				if (ka == null && kb == null) return deadlineTieBreak(a, b);
86				if (ka == null) return 1;
87				if (kb == null) return -1;
88				return ka - kb || deadlineTieBreak(a, b);
89			});
90		} else {
