export interface KanbanWorkspaceLifecycleSnapshot {
	cardId: string;
	workspaceId: string;
	projectId: string | null;
	bucket: string;
	isCompletedCard: boolean;
	isMainWorkspace: boolean;
	hasLocalState: boolean;
	cardCompletedAt: number | null;
	sidebarCompletedAt: number | null;
	now: number;
}

export interface KanbanWorkspaceLifecycleActions {
	ensureWorkspaceInSidebar: (
		workspaceId: string,
		projectId: string | null,
	) => void;
	completeWorkspace: (workspaceId: string, completedAt: number) => void;
	uncompleteWorkspace: (workspaceId: string) => void;
	getWorkspaceBucket: (workspaceId: string) => string;
	getCardCompletedAt: (cardId: string) => number | null | undefined;
	setCardCompletedAt: (cardId: string, completedAt: number) => void;
}

/**
 * Repairs a bound card after a prior multi-collection update stopped halfway.
 * The sidebar lifecycle actions own every runtime cleanup invariant; this
 * reconciler only decides which action is missing and repairs the card stamp.
 */
export function repairKanbanWorkspaceLifecycle(
	snapshot: KanbanWorkspaceLifecycleSnapshot,
	actions: KanbanWorkspaceLifecycleActions,
): void {
	if (
		snapshot.isCompletedCard &&
		snapshot.bucket !== "completed" &&
		snapshot.bucket !== "hidden" &&
		!snapshot.isMainWorkspace
	) {
		const completedAt = snapshot.cardCompletedAt ?? snapshot.now;
		if (!snapshot.hasLocalState) {
			actions.ensureWorkspaceInSidebar(
				snapshot.workspaceId,
				snapshot.projectId,
			);
		}
		const liveBucket = actions.getWorkspaceBucket(snapshot.workspaceId);
		if (liveBucket !== "completed" && liveBucket !== "hidden") {
			actions.completeWorkspace(snapshot.workspaceId, completedAt);
		}
		if (actions.getCardCompletedAt(snapshot.cardId) == null) {
			actions.setCardCompletedAt(snapshot.cardId, completedAt);
		}
		return;
	}

	if (
		snapshot.isCompletedCard &&
		snapshot.bucket === "completed" &&
		snapshot.cardCompletedAt === null
	) {
		actions.setCardCompletedAt(
			snapshot.cardId,
			snapshot.sidebarCompletedAt ?? snapshot.now,
		);
		return;
	}

	if (!snapshot.isCompletedCard && snapshot.bucket === "completed") {
		actions.uncompleteWorkspace(snapshot.workspaceId);
	}
}

