953				// A repo's main workspace can never be soft-deleted — mains stay
954				// archive-only (MASTER-ARCHIVE-ONLY). Resolve the type from the
955				// host-owned workspace record FIRST (source of truth since v1.14's
956				// host-owned table); the cloud v2Workspaces cache is a fallback. An
957				// unresolvable type FAILS LOUD instead of proceeding — the old
958				// cache-only check failed OPEN on a cold cache and could soft-delete
959				// a master.
960				const hostWorkspace =
961					hostWorkspaces.find((candidate) => candidate.id === workspaceId) ??
962					null;
963				const workspaceType = hostWorkspace?.type ?? null;
964				if (hostWorkspace === null || workspaceType == null) {
965					console.error(
