967					);
968					return false;
969				}
970				if (workspaceType === "main") {
971					console.warn(
972						`[deleteWorkspace] refusing to delete main workspace ${workspaceId} — mains are archive-only`,
973					);
974					return false;
975				}
976				if (!collections.v2WorkspaceLocalState.get(workspaceId)) {
