983					const resolvedProjectId = resolveSidebarRowProjectId(
984						projectId,
985						hostWorkspace.projectId,
986					);
987					collections.v2WorkspaceLocalState.insert({
988						workspaceId,
989						createdAt: new Date(),
990						sidebarState: {
