992							tabOrder: 0,
993							sectionId: null,
994							// isHidden too, so raw-visibility consumers (notifications, ports,
995							// accessible-list "in sidebar") treat it like an archived row. The
996							// bucket classifier checks deletedAt FIRST, so it never surfaces
997							// under Archived/Completed.
998							isHidden: true,
999							deletedAt: exitedAt,
1000							...workspaceExitCleanupState(exitedAt),
1001						},
1002						paneLayout: createEmptyPaneLayout(),
1003					});
1004					return true;
1005				}
1006				exitWorkspaceRow(collections, workspaceId, (draft, exitedAt) => {
1007					draft.sidebarState.deletedAt = exitedAt;
1008					draft.sidebarState.isHidden = true;
