207	function getTerminalRuntimeId(pane: Pane<unknown>): string | null {
208		if (pane.kind !== "terminal") return null;
209		if (!pane.data || typeof pane.data !== "object") return null;
210		const data = pane.data as { terminalId?: unknown };
211		return typeof data.terminalId === "string" ? data.terminalId : null;
212	}
213	
214	function getBrowserRuntimeId(pane: Pane<unknown>): string | null {
215		return pane.kind === "browser" ? pane.id : null;
216	}
217	
218	/**
219	 * Tears down the renderer runtimes behind a workspace's panes.
220	 *
221	 * `terminalAction` is the whole difference between the two callers. Sidebar
222	 * REMOVAL only `release`s — it detaches the renderer view and leaves the host
223	 * PTY running, because a removed row is a display decision the user can undo by
224	 * re-opening the workspace. (WORKTREE-EXIT-CLEANUP) An EXIT is not: the user is
225	 * done with the thread, so the terminal runtime is `dispose`d outright (which
226	 * also tells host-service to kill the session and clears the persisted
227	 * snapshot, so nothing survives to be restored). Browser panes are destroyed
228	 * either way — they hold no host-side session.
229	 */
230	function cleanupWorkspacePaneRuntimes(
231		rows: PaneLifecycleRow[],
232		terminalAction: "release" | "dispose" = "release",
233	): void {
234		for (const terminalId of extractPaneIds(rows, getTerminalRuntimeId)) {
235			if (terminalAction === "dispose")
236				terminalRuntimeRegistry.dispose(terminalId);
237			else terminalRuntimeRegistry.release(terminalId);
238		}
239		for (const browserId of extractPaneIds(rows, getBrowserRuntimeId)) {
240			browserRuntimeRegistry.destroy(browserId);
241		}
242	}
243	
244	/**
245	 * (WORKTREE-EXIT-CLEANUP) Tear down the renderer half of a workspace the user
246	 * has exited. Call this immediately BEFORE the row update that wipes
247	 * `paneLayout` — the pane ids it needs live in the layout it is about to clear.
248	 * A row-less workspace (an insert branch) has no panes to dispose, only the
249	 * host's half to request.
250	 */
251	function disposeExitedWorkspaceRuntimes(
252		collections: AppCollections,
253		workspaceId: string,
254	): void {
255		const existing = collections.v2WorkspaceLocalState.get(workspaceId);
256		if (existing) cleanupWorkspacePaneRuntimes([existing], "dispose");
257	}
258	
259	/**
260	 * (WORKTREE-EXIT-CLEANUP) Exit a workspace row that already exists — Archive,
261	 * Snooze, Recycle Bin and Completed all end here, and none of them owns any of
262	 * the four steps below.
263	 *
264	 * ONE TIMESTAMP FOR THE WHOLE ACTION, read here and handed to `applyExitFlags`.
265	 * The pending stamp IDENTIFIES the debt, so the lifecycle stamp a caller writes
266	 * (`archivedAt`, `deletedAt`) has to name the same instant the cleanup stamp
267	 * does — a second `Date.now()` would stamp a debt no host reply could quote.
268	 *
269	 * THE ORDER IS LOAD-BEARING. Renderer runtimes are disposed BEFORE the update,
270	 * because the pane ids they need live in the `paneLayout` the update clears.
271	 *
272	 * ROW-LESS WORKSPACES NEVER REACH HERE: with no row there are no panes to
273	 * dispose and nothing to update, so each caller's insert branch stamps
274	 * {@link workspaceExitCleanupState} on the row it creates instead — its host
275	 * may still be running terminals and holding a pinned account for it.
276	 */
277	function exitWorkspaceRow(
278		collections: AppCollections,
279		workspaceId: string,
280		applyExitFlags: (
281			draft: WritableDeep<WorkspaceLocalStateDraft>,
282			exitedAt: number,
283		) => void,
284	): void {
285		const exitedAt = Date.now();
286		disposeExitedWorkspaceRuntimes(collections, workspaceId);
287		collections.v2WorkspaceLocalState.update(workspaceId, (draft) => {
288			applyExitFlags(draft, exitedAt);
289			applyWorkspaceExitCleanup(draft, exitedAt);
290		});
291	}
292	
293	export function useDashboardSidebarState() {
294		const collections = useCollections();
295		const { workspaces: hostWorkspaces } = useHostWorkspaces();
296		const { machineId } = useLocalHostService();
297	
298		const ensureProjectInSidebar = useCallback(
299			(projectId: string) => {
300				ensureSidebarProjectRecord(collections, projectId);
301			},
302			[collections],
303		);
304	
305		const ensureWorkspaceInSidebar = useCallback(
306			(workspaceId: string, projectId: string | null) => {
307				// Sessions (null projectId) have no project placement row — the
308				// Sessions section renders unconditionally.
309				if (projectId !== null) {
310					ensureSidebarProjectRecord(collections, projectId);
311				}
312				ensureSidebarWorkspaceRecord(
313					collections,
314					workspaceId,
315					projectId,
316					hostWorkspaces.find((candidate) => candidate.id === workspaceId)
317						?.type ?? null,
318				);
319			},
320			[collections, hostWorkspaces],
321		);
322	
323		// (REMOVE-STICKY) Placement for PASSIVE workspace route mounts (session
324		// restore, the kanban collapse-split, background navigation). Unlike
325		// ensureWorkspaceInSidebar it must never undo an explicit "Remove project
326		// from sidebar": it does NOT re-insert the project's sidebar row (the full
327		// ensure did — a restored route silently resurrected a removed project on
328		// the next launch), and it never touches an existing local-state row (so a
329		// hidden/removed row stays put — only an EXPLICIT open pulls a hidden main
330		// back). A genuinely new (row-less) workspace still gets its local-state
331		// row, because pane-layout persistence updates that row in place and needs
