import { describe, expect, it } from "bun:test";
import {
	type KanbanWorkspaceLifecycleActions,
	type KanbanWorkspaceLifecycleSnapshot,
	repairKanbanWorkspaceLifecycle,
} from "./repairWorkspaceLifecycle";

const BASE_SNAPSHOT: KanbanWorkspaceLifecycleSnapshot = {
	cardId: "card-1",
	workspaceId: "workspace-1",
	projectId: "project-1",
	bucket: "active",
	isCompletedCard: true,
	isMainWorkspace: false,
	hasLocalState: true,
	cardCompletedAt: 123,
	sidebarCompletedAt: null,
	now: 999,
};

function makeActions(
	calls: string[],
	live: { workspaceBucket?: string; cardCompletedAt?: number | null } = {},
): KanbanWorkspaceLifecycleActions {
	return {
		ensureWorkspaceInSidebar: (workspaceId, projectId) => {
			calls.push(`ensure:${workspaceId}:${projectId}`);
		},
		completeWorkspace: (workspaceId, completedAt) => {
			calls.push(`complete:${workspaceId}:${completedAt}`);
		},
		uncompleteWorkspace: (workspaceId) => {
			calls.push(`uncomplete:${workspaceId}`);
		},
		getWorkspaceBucket: () => live.workspaceBucket ?? "active",
		getCardCompletedAt: () =>
			live.cardCompletedAt === undefined ? 123 : live.cardCompletedAt,
		setCardCompletedAt: (cardId, completedAt) => {
			calls.push(`stamp:${cardId}:${completedAt}`);
		},
	};
}

describe("repairKanbanWorkspaceLifecycle", () => {
	it("routes a partially completed card through the full completion lifecycle", () => {
		const calls: string[] = [];

		repairKanbanWorkspaceLifecycle(BASE_SNAPSHOT, makeActions(calls));

		expect(calls).toEqual(["complete:workspace-1:123"]);
	});

	it("creates missing sidebar state before completing and preserves one timestamp", () => {
		const calls: string[] = [];

		repairKanbanWorkspaceLifecycle(
			{
				...BASE_SNAPSHOT,
				hasLocalState: false,
				cardCompletedAt: null,
			},
			makeActions(calls, { cardCompletedAt: null }),
		);

		expect(calls).toEqual([
			"ensure:workspace-1:project-1",
			"complete:workspace-1:999",
			"stamp:card-1:999",
		]);
	});

	it("routes a card moved out of Completed through uncompletion", () => {
		const calls: string[] = [];

		repairKanbanWorkspaceLifecycle(
			{
				...BASE_SNAPSHOT,
				bucket: "completed",
				isCompletedCard: false,
				sidebarCompletedAt: 123,
			},
			makeActions(calls, { workspaceBucket: "completed" }),
		);

		expect(calls).toEqual(["uncomplete:workspace-1"]);
	});

	it("fills a missing card timestamp without repeating workspace cleanup", () => {
		const calls: string[] = [];

		repairKanbanWorkspaceLifecycle(
			{
				...BASE_SNAPSHOT,
				bucket: "completed",
				cardCompletedAt: null,
				sidebarCompletedAt: 456,
			},
			makeActions(calls, { cardCompletedAt: null }),
		);

		expect(calls).toEqual(["stamp:card-1:456"]);
	});

	it("does not repeat lifecycle work after another reconciler already repaired it", () => {
		const completedCalls: string[] = [];
		repairKanbanWorkspaceLifecycle(
			BASE_SNAPSHOT,
			makeActions(completedCalls, { workspaceBucket: "completed" }),
		);
		expect(completedCalls).toEqual([]);

		const uncompletedCalls: string[] = [];
		repairKanbanWorkspaceLifecycle(
			{
				...BASE_SNAPSHOT,
				bucket: "completed",
				isCompletedCard: false,
			},
