2	import { peekConnectionStatus } from "@superset/workspace-client";
3	import { isNull, not } from "@tanstack/db";
4	import { useLiveQuery } from "@tanstack/react-db";
5	import { useCallback, useEffect, useMemo, useRef } from "react";
6	import { electronTrpc } from "renderer/lib/electron-trpc";
7	import { getLocalHostServiceUrls } from "renderer/lib/host-service-client";
8	import {
9		decideCleanupOutcome,
10		describeCleanupToast,
11		type RetirementVerdict,
12		resolveRetirementCallUrl,
13		retireWorkspaceRuntime,
14	} from "renderer/lib/workspace-exit-cleanup";
15	import { useCollections } from "renderer/routes/_authenticated/providers/CollectionsProvider";
16	import { useHostWorkspaces } from "renderer/routes/_authenticated/providers/HostWorkspacesProvider";
17	import {
18		cleanupRoutingKey,
19		createSweepQueue,
20		localHostFingerprint,
21	} from "./cleanupTriggers";
22	import { useHostReopenGeneration } from "./useHostReopenGeneration";
23	
24	/** One standing toast for the whole feature, so a sweep can't stack five. */
25	const CLEANUP_TOAST_ID = "workspace-exit-cleanup";
26	
27	/** Where a pending workspace's retirement call has to be sent. */
28	interface CleanupTarget {
29		/** The owning host's URL, or null while that owner is unreachable. */
30		ownerHostUrl: string | null;
31		/** The owner is a cloud sandbox: reachable, but never worth waking. */
32		isSandbox: boolean;
33		/** The workspace's absence from the host lists proves it is gone. */
34		absenceAuthoritative: boolean;
35	}
36	
37	/**
38	 * (WORKTREE-EXIT-CLEANUP) Drives the HOST half of exiting a card. Completed,
39	 * Archive, Snooze and Recycle Bin clear the renderer's tabs and terminals
40	 * synchronously and stamp `runtimeCleanupPendingAt`; this hook is what turns
41	 * that stamp into the host call that kills the terminal sessions and releases
42	 * the workspace's pinned Claude account.
43	 *
44	 * Keeping the stamp in persisted local state rather than firing and forgetting
45	 * is the whole point: the owning machine may be off at the moment the user
46	 * archives a thread, and the debt has to outlive both that outage and the app.
47	 * The sweep therefore re-runs on mount (app restart), when a local host-service
48	 * appears or is replaced, and when an owning host's socket comes back up. The
49	 * stamp is cleared ONLY when a host that OWNS the workspace reports a clean
50	 * teardown, or when the workspace is authoritatively gone.
51	 *
52	 * One sweep runs at a time. A trigger that lands mid-sweep queues exactly one
53	 * rerun for after it settles, rather than being dropped as a duplicate — a
54	 * reconnect arriving while an attempt is still failing against the old socket
55	 * is precisely the trigger that must not be lost.
56	 */
57	export function useWorkspaceExitCleanup(): void {
58		const collections = useCollections();
59		const utils = electronTrpc.useUtils();
60		const { workspaces, cache, isAbsenceAuthoritative } = useHostWorkspaces();
61		const { data: connections } =
62			electronTrpc.hostServiceCoordinator.getConnections.useQuery();
63	
64		const { data: pendingRows = [], isReady } = useLiveQuery(
65			(query) =>
66				query
67					.from({ state: collections.v2WorkspaceLocalState })
68					.where(({ state }) =>
69						not(isNull(state.sidebarState.runtimeCleanupPendingAt)),
70					)
71					.select(({ state }) => ({ workspaceId: state.workspaceId })),
72			[collections],
73		);
74	
75		// useLiveQuery hands back a new array every tick; collapse it to a value the
76		// effect can compare, or the sweep would re-fire on every unrelated render.
77		const pendingKey = pendingRows
78			.map((row) => row.workspaceId)
79			.sort()
80			.join(",");
81		const pendingWorkspaceIds = useMemo(
82			() => (pendingKey === "" ? [] : pendingKey.split(",")),
83			[pendingKey],
84		);
85	
86		// Where each pending workspace has to be reached, resolved the same way
87		// every other cross-host call resolves a host, plus the two things the
88		// triggers below read off the same pass. A null URL means the owning host
89		// has not resolved — it is offline, or its row has not hydrated — and only
90		// the local broadcast can find it.
91		const { targets, hasOwnerTarget, routingKey, reopenUrls } = useMemo(() => {
92			const resolved = new Map<string, CleanupTarget>();
93			const reachable: string[] = [];
94			// No debt, no routing to work out — and no reason to walk every workspace
95			// the window knows about to find that out.
96			if (pendingWorkspaceIds.length === 0) {
97				return {
98					targets: resolved,
99					hasOwnerTarget: false,
100					routingKey: "",
101					reopenUrls: reachable,
102				};
103			}
104			const hostIds = new Map(
105				workspaces.map((workspace) => [workspace.id, workspace.hostId] as const),
106			);
107			let owned = false;
108			for (const workspaceId of pendingWorkspaceIds) {
109				const hostId = hostIds.get(workspaceId) ?? null;
110				const ownerHostUrl =
111					hostId === null ? null : cache.resolveHostUrl(hostId);
