1	import type { Pane } from "@superset/panes";
2	import type { WritableDeep } from "@tanstack/db";
3	import type { HostShapedWorkspace } from "renderer/hooks/host-workspaces/useHostWorkspaces";
4	import { useCallback } from "react";
5	import { terminalRuntimeRegistry } from "renderer/lib/terminal/terminal-runtime-registry";
6	import { browserRuntimeRegistry } from "renderer/routes/_authenticated/_dashboard/v2-workspace/$workspaceId/hooks/usePaneRegistry/components/BrowserPane/browserRuntimeRegistry";
7	import {
8		extractPaneIds,
9		type PaneLifecycleRow,
10	} from "renderer/routes/_authenticated/components/utils/paneLifecycleRows";
11	import { useCollections } from "renderer/routes/_authenticated/providers/CollectionsProvider";
12	import type { AppCollections } from "renderer/routes/_authenticated/providers/CollectionsProvider/collections";
13	import {
14		APP_LAUNCH_ID,
15		getNextTabOrder,
16		getPrependTabOrder,
17		getWorkspaceSidebarBucket,
18		isSidebarWorkspaceVisible,
19		type WorkspaceLocalStateDraft,
20	} from "renderer/routes/_authenticated/providers/CollectionsProvider/dashboardSidebarLocal";
21	import { useHostWorkspaces } from "renderer/routes/_authenticated/providers/HostWorkspacesProvider";
22	import { useLocalHostService } from "renderer/routes/_authenticated/providers/LocalHostServiceProvider";
23	import { PROJECT_CUSTOM_COLORS } from "shared/constants/project-colors";
24	import {
25		applyAutomaticSnoozeReturn,
26		applyWorkspaceExitCleanup,
27		cancelWorkspaceExitCleanup,
28		createEmptyPaneLayout,
29		removeProjectFromSidebarState,
30		resolveSidebarRowProjectId,
31		tombstoneSidebarWorkspaceRecord,
32		workspaceExitCleanupState,
33	} from "./sidebarMutations";
34	
35	/** The per-project reveal/collapse booleans on the sidebar project row. */
36	export type ProjectSectionFlag =
37		| "showSnoozed"
38		| "showArchived"
39		| "snoozedCollapsed"
40		| "archivedCollapsed"
41		// (RECYCLE-BIN) reveal + collapse for the per-project Recycle Bin section.
42		| "showDeleted"
43		| "deletedCollapsed";
44	
45	type ProjectTopLevelItem = {
46		type: "workspace" | "section";
47		id: string;
48		tabOrder: number;
49	};
50	
51	type ProjectTopLevelCollections = Pick<
52		AppCollections,
53		"v2SidebarSections" | "v2WorkspaceLocalState"
54	>;
55	
56	function compareProjectTopLevelItems(
57		left: ProjectTopLevelItem,
58		right: ProjectTopLevelItem,
59	): number {
60		const orderDelta = left.tabOrder - right.tabOrder;
61		if (orderDelta !== 0) return orderDelta;
62		if (left.type === right.type) return 0;
63		return left.type === "section" ? -1 : 1;
64	}
65	
66	function getProjectTopLevelItems(
67		collections: ProjectTopLevelCollections,
68		// Null scopes to the Sessions section (project-less workspaces).
69		projectId: string | null,
70		options: { excludeWorkspaceId?: string; excludeSectionId?: string } = {},
71	): ProjectTopLevelItem[] {
72		return [
73			...Array.from(collections.v2WorkspaceLocalState.state.values())
74				.filter(
75					(item) =>
76						item.sidebarState.projectId === projectId &&
77						isSidebarWorkspaceVisible(item) &&
78						item.sidebarState.sectionId === null &&
79						item.workspaceId !== options.excludeWorkspaceId,
80				)
81				.map((item) => ({
82					type: "workspace" as const,
83					id: item.workspaceId,
84					tabOrder: item.sidebarState.tabOrder,
85				})),
86			...Array.from(collections.v2SidebarSections.state.values())
87				.filter(
88					(item) =>
89						item.projectId === projectId &&
90						item.sectionId !== options.excludeSectionId,
91				)
92				.map((item) => ({
93					type: "section" as const,
94					id: item.sectionId,
95					tabOrder: item.tabOrder,
96				})),
97		].sort(compareProjectTopLevelItems);
98	}
99	
100	function getFirstSectionIndex(items: ProjectTopLevelItem[]): number {
101		const firstSectionIndex = items.findIndex((item) => item.type === "section");
102		return firstSectionIndex === -1 ? items.length : firstSectionIndex;
103	}
104	
105	/**
106	 * Rewrites the flat top-level project lane. Workspace items are explicitly
107	 * ungrouped by setting sidebarState.projectId and clearing sidebarState.sectionId.
108	 */
109	function writeProjectTopLevelOrder(
110		collections: ProjectTopLevelCollections,
111		projectId: string | null,
112		items: ProjectTopLevelItem[],
113	): void {
114		items.forEach((item, index) => {
115			const tabOrder = index + 1;
116			if (item.type === "workspace") {
117				if (!collections.v2WorkspaceLocalState.get(item.id)) return;
118				collections.v2WorkspaceLocalState.update(item.id, (draft) => {
119					draft.sidebarState.projectId = projectId;
120					draft.sidebarState.sectionId = null;
121					draft.sidebarState.tabOrder = tabOrder;
122					draft.sidebarState.isHidden = false;
123				});
124				return;
125			}
126	
127			if (!collections.v2SidebarSections.get(item.id)) return;
128			collections.v2SidebarSections.update(item.id, (draft) => {
129				draft.tabOrder = tabOrder;
130			});
131		});
132	}
133	
134	function ensureSidebarProjectRecord(
135		collections: Pick<AppCollections, "v2SidebarProjects">,
136		projectId: string,
137	): void {
138		if (collections.v2SidebarProjects.get(projectId)) {
139			return;
140		}
141	
142		collections.v2SidebarProjects.insert({
143			projectId,
144			createdAt: new Date(),
145			// Prepend, matching new workspaces: the project you just added is
146			// the one you're about to work in.
147			tabOrder: getPrependTabOrder([
148				...collections.v2SidebarProjects.state.values(),
149			]),
150			isCollapsed: false,
151		});
152	}
153	
154	function ensureSidebarWorkspaceRecord(
155		collections: Pick<
156			AppCollections,
157			"v2SidebarSections" | "v2WorkspaceLocalState"
158		>,
159		workspaceId: string,
160		// Null places the workspace in the Sessions section.
161		projectId: string | null,
162		// (KANBAN HOST SOURCE) resolved by the caller from the host-served lists;
163		// the Electric mirror lacks post-migration rows. Omitted where the caller
164		// has already established there is no existing row to classify.
165		workspaceType: string | null = null,
166	): void {
167		const existing = collections.v2WorkspaceLocalState.get(workspaceId);
168		// Already placed — don't resurrect into active. An active row, a snoozed row,
169		// or an archived row (archivedAt set, OR a removed non-main thread surfaced
170		// under Archived) all stay put on re-open (view-in-place). Only a "hidden"
171		// row (a removed MAIN workspace: isHidden, no archive) is pulled back into the
172		// active lane when explicitly opened. Classified via the shared
173		// getWorkspaceSidebarBucket so the rule matches exactly what the sidebar renders.
174		if (existing) {
175			if (
176				getWorkspaceSidebarBucket(existing, Date.now(), workspaceType) !==
177				"hidden"
178			) {
179				return;
180			}
181		}
182	
183		const topLevelItems = getProjectTopLevelItems(collections, projectId);
184	
185		if (existing) {
186			collections.v2WorkspaceLocalState.update(workspaceId, (draft) => {
187				draft.sidebarState.projectId = projectId;
188				draft.sidebarState.tabOrder = getPrependTabOrder(topLevelItems);
189				draft.sidebarState.sectionId = null;
190				draft.sidebarState.isHidden = false;
191			});
192			return;
193		}
194	
195		collections.v2WorkspaceLocalState.insert({
196			workspaceId,
197			createdAt: new Date(),
198			sidebarState: {
199				projectId,
200				tabOrder: getPrependTabOrder(topLevelItems),
201				sectionId: null,
202				isHidden: false,
203			},
204			paneLayout: createEmptyPaneLayout(),
205		});
206	}
207	
208	function getTerminalRuntimeId(pane: Pane<unknown>): string | null {
209		if (pane.kind !== "terminal") return null;
210		if (!pane.data || typeof pane.data !== "object") return null;
211		const data = pane.data as { terminalId?: unknown };
212		return typeof data.terminalId === "string" ? data.terminalId : null;
213	}
214	
215	function getBrowserRuntimeId(pane: Pane<unknown>): string | null {
216		return pane.kind === "browser" ? pane.id : null;
217	}
218	
219	/**
220	 * Tears down the renderer runtimes behind a workspace's panes.
221	 *
222	 * `terminalAction` is the whole difference between the two callers. Sidebar
223	 * REMOVAL only `release`s — it detaches the renderer view and leaves the host
224	 * PTY running, because a removed row is a display decision the user can undo by
225	 * re-opening the workspace. (WORKTREE-EXIT-CLEANUP) An EXIT is not: the user is
226	 * done with the thread, so the terminal runtime is `dispose`d outright (which
227	 * also tells host-service to kill the session and clears the persisted
228	 * snapshot, so nothing survives to be restored). Browser panes are destroyed
229	 * either way — they hold no host-side session.
230	 */
231	function cleanupWorkspacePaneRuntimes(
232		rows: PaneLifecycleRow[],
233		terminalAction: "release" | "dispose" = "release",
234	): void {
235		for (const terminalId of extractPaneIds(rows, getTerminalRuntimeId)) {
236			if (terminalAction === "dispose")
237				terminalRuntimeRegistry.dispose(terminalId);
238			else terminalRuntimeRegistry.release(terminalId);
239		}
240		for (const browserId of extractPaneIds(rows, getBrowserRuntimeId)) {
241			browserRuntimeRegistry.destroy(browserId);
242		}
243	}
244	
245	/**
246	 * (WORKTREE-EXIT-CLEANUP) Tear down the renderer half of a workspace the user
247	 * has exited. Call this immediately BEFORE the row update that wipes
248	 * `paneLayout` — the pane ids it needs live in the layout it is about to clear.
249	 * A row-less workspace (an insert branch) has no panes to dispose, only the
250	 * host's half to request.
251	 */
252	function disposeExitedWorkspaceRuntimes(
253		collections: Pick<AppCollections, "v2WorkspaceLocalState">,
254		workspaceId: string,
255	): void {
256		const existing = collections.v2WorkspaceLocalState.get(workspaceId);
257		if (existing) cleanupWorkspacePaneRuntimes([existing], "dispose");
258	}
259	
260	/**
261	 * (WORKTREE-EXIT-CLEANUP) Exit a workspace row that already exists — Archive,
262	 * Snooze, Recycle Bin and Completed all end here, and none of them owns any of
263	 * the four steps below.
264	 *
265	 * ONE TIMESTAMP FOR THE WHOLE ACTION, read here and handed to `applyExitFlags`.
266	 * The pending stamp IDENTIFIES the debt, so the lifecycle stamp a caller writes
267	 * (`archivedAt`, `deletedAt`) has to name the same instant the cleanup stamp
268	 * does — a second `Date.now()` would stamp a debt no host reply could quote.
269	 *
270	 * THE ORDER IS LOAD-BEARING. Renderer runtimes are disposed BEFORE the update,
271	 * because the pane ids they need live in the `paneLayout` the update clears.
272	 *
273	 * ROW-LESS WORKSPACES NEVER REACH HERE: with no row there are no panes to
274	 * dispose and nothing to update, so each caller's insert branch stamps
275	 * {@link workspaceExitCleanupState} on the row it creates instead — its host
276	 * may still be running terminals and holding a pinned account for it.
277	 */
278	function exitWorkspaceRow(
279		collections: Pick<AppCollections, "v2WorkspaceLocalState">,
280		workspaceId: string,
281		applyExitFlags: (
282			draft: WritableDeep<WorkspaceLocalStateDraft>,
283			exitedAt: number,
284		) => void,
285	): void {
286		const exitedAt = Date.now();
287		disposeExitedWorkspaceRuntimes(collections, workspaceId);
288		collections.v2WorkspaceLocalState.update(workspaceId, (draft) => {
289			applyExitFlags(draft, exitedAt);
290			applyWorkspaceExitCleanup(draft, exitedAt);
291		});
292	}
293	
294	type WorkspaceCompletionHostRow = Pick<
295		HostShapedWorkspace,
296		"id" | "projectId" | "type"
297	>;
298	
299	type WorkspaceCompletionCollections = Pick<
300		AppCollections,
301		"v2SidebarProjects" | "v2SidebarSections" | "v2WorkspaceLocalState"
302	>;
303	
304	/**
305	 * Runs the complete-card sidebar lifecycle without requiring the full sidebar
306	 * React hook. The command owns row creation and workspace-type validation so
307	 * repair callers cannot bypass exit cleanup when a prior write stopped halfway.
308	 */
309	export function completeWorkspaceInSidebar(
310		collections: WorkspaceCompletionCollections,
311		hostWorkspaces: readonly WorkspaceCompletionHostRow[],
312		workspaceId: string,
313		completedAt: number,
314	): boolean {
315		const hostWorkspace = hostWorkspaces.find(
316			(candidate) => candidate.id === workspaceId,
317		);
318		if (!hostWorkspace) {
319			console.error(
320				`[completeWorkspace] refusing to complete ${workspaceId}: workspace type unresolvable (host lists miss)`,
321			);
322			return false;
323		}
324		if (hostWorkspace.type === "main") return false;
325	
326		if (!collections.v2WorkspaceLocalState.get(workspaceId)) {
327			if (hostWorkspace.projectId !== null) {
328				ensureSidebarProjectRecord(collections, hostWorkspace.projectId);
329			}
330			ensureSidebarWorkspaceRecord(
331				collections,
332				workspaceId,
333				hostWorkspace.projectId,
334				hostWorkspace.type,
335			);
336		}
337		if (!collections.v2WorkspaceLocalState.get(workspaceId)) {
338			console.error(
339				`[completeWorkspace] failed to create sidebar state for ${workspaceId}`,
340			);
341			return false;
342		}
343	
344		// The caller's `completedAt` is the board's own record of when the card
345		// landed in Completed and can be older than this call, so the cleanup debt
346		// gets its own instant from `exitWorkspaceRow`.
347		exitWorkspaceRow(collections, workspaceId, (draft) => {
348			draft.sidebarState.completedAt = completedAt;
349			// isHidden too, so raw-visibility consumers (notifications, ports,
350			// accessible-list "in sidebar") treat it like an archived row. The bucket
351			// classifier checks completedAt first, so it never appears under Archived.
352			draft.sidebarState.isHidden = true;
353			draft.sidebarState.archivedAt = null;
354			draft.sidebarState.snoozeUntil = null;
355			draft.sidebarState.snoozeLaunchId = null;
356		});
357		return true;
358	}
359	
360	export function uncompleteWorkspaceInSidebar(
361		collections: Pick<AppCollections, "v2WorkspaceLocalState">,
362		workspaceId: string,
363	): boolean {
364		if (!collections.v2WorkspaceLocalState.get(workspaceId)) return false;
365		collections.v2WorkspaceLocalState.update(workspaceId, (draft) => {
366			draft.sidebarState.completedAt = null;
367			draft.sidebarState.isHidden = false;
368			draft.sidebarState.archivedAt = null;
369			cancelWorkspaceExitCleanup(draft.sidebarState);
370		});
371		return true;
372	}
373	
374	export function useDashboardSidebarState() {
375		const collections = useCollections();
376		const { workspaces: hostWorkspaces } = useHostWorkspaces();
377		const { machineId } = useLocalHostService();
378	
379		const ensureProjectInSidebar = useCallback(
380			(projectId: string) => {
381				ensureSidebarProjectRecord(collections, projectId);
382			},
383			[collections],
384		);
385	
386		const ensureWorkspaceInSidebar = useCallback(
387			(workspaceId: string, projectId: string | null) => {
388				// Sessions (null projectId) have no project placement row — the
389				// Sessions section renders unconditionally.
390				if (projectId !== null) {
391					ensureSidebarProjectRecord(collections, projectId);
392				}
393				ensureSidebarWorkspaceRecord(
394					collections,
395					workspaceId,
396					projectId,
397					hostWorkspaces.find((candidate) => candidate.id === workspaceId)
398						?.type ?? null,
399				);
400			},
401			[collections, hostWorkspaces],
402		);
403	
404		// (REMOVE-STICKY) Placement for PASSIVE workspace route mounts (session
405		// restore, the kanban collapse-split, background navigation). Unlike
406		// ensureWorkspaceInSidebar it must never undo an explicit "Remove project
407		// from sidebar": it does NOT re-insert the project's sidebar row (the full
408		// ensure did — a restored route silently resurrected a removed project on
409		// the next launch), and it never touches an existing local-state row (so a
410		// hidden/removed row stays put — only an EXPLICIT open pulls a hidden main
411		// back). A genuinely new (row-less) workspace still gets its local-state
412		// row, because pane-layout persistence updates that row in place and needs
413		// it to exist; the row alone renders nothing while the project row is
414		// absent.
415		const placeWorkspaceFromPassiveMount = useCallback(
416			(workspaceId: string, projectId: string) => {
417				if (collections.v2WorkspaceLocalState.get(workspaceId)) return;
418				ensureSidebarWorkspaceRecord(
419					collections,
420					workspaceId,
421					projectId,
422					hostWorkspaces.find((candidate) => candidate.id === workspaceId)
423						?.type ?? null,
424				);
425			},
426			[collections, hostWorkspaces],
427		);
428	
429		const toggleProjectCollapsed = useCallback(
430			(projectId: string) => {
431				const existing = collections.v2SidebarProjects.get(projectId);
432				if (!existing) return;
433				collections.v2SidebarProjects.update(projectId, (draft) => {
434					draft.isCollapsed = !draft.isCollapsed;
435				});
436			},
437			[collections],
438		);
439	
440		// (ACTIVE-FIRST) Toggle a project's manual pin. Pinned projects form the top
441		// sort tier in the sidebar (pinned > active > idle). Local-only.
442		const togglePinProject = useCallback(
443			(projectId: string) => {
444				ensureSidebarProjectRecord(collections, projectId);
445				collections.v2SidebarProjects.update(projectId, (draft) => {
446					draft.isPinned = !draft.isPinned;
447				});
448			},
449			[collections],
450		);
451	
452		const reorderProjects = useCallback(
453			(projectIds: string[]) => {
454				projectIds.forEach((projectId, index) => {
455					if (!collections.v2SidebarProjects.get(projectId)) return;
456					collections.v2SidebarProjects.update(projectId, (draft) => {
457						draft.tabOrder = index + 1;
458					});
459				});
460			},
461			[collections],
462		);
463	
464		const reorderWorkspaces = useCallback(
465			(workspaceIds: string[]) => {
466				workspaceIds.forEach((workspaceId, index) => {
467					if (!collections.v2WorkspaceLocalState.get(workspaceId)) return;
468					collections.v2WorkspaceLocalState.update(workspaceId, (draft) => {
469						draft.sidebarState.tabOrder = index + 1;
470						draft.sidebarState.isHidden = false;
471					});
472				});
473			},
474			[collections],
475		);
476	
477		const reorderProjectChildren = useCallback(
478			(
479				projectId: string | null,
480				orderedItems: Array<{ type: "workspace" | "section"; id: string }>,
481			) => {
482				orderedItems.forEach((item, index) => {
483					const tabOrder = index + 1;
484					if (item.type === "workspace") {
485						if (!collections.v2WorkspaceLocalState.get(item.id)) return;
486						collections.v2WorkspaceLocalState.update(item.id, (draft) => {
487							draft.sidebarState.tabOrder = tabOrder;
488							draft.sidebarState.sectionId = null;
489							draft.sidebarState.projectId = projectId;
490							draft.sidebarState.isHidden = false;
491						});
492					} else {
493						if (!collections.v2SidebarSections.get(item.id)) return;
494						collections.v2SidebarSections.update(item.id, (draft) => {
