import type { Pane } from "@superset/panes";
import type { WritableDeep } from "@tanstack/db";
import type { HostShapedWorkspace } from "renderer/hooks/host-workspaces/useHostWorkspaces";
import { useCallback } from "react";
import { terminalRuntimeRegistry } from "renderer/lib/terminal/terminal-runtime-registry";
import { browserRuntimeRegistry } from "renderer/routes/_authenticated/_dashboard/v2-workspace/$workspaceId/hooks/usePaneRegistry/components/BrowserPane/browserRuntimeRegistry";
import {
	extractPaneIds,
	type PaneLifecycleRow,
} from "renderer/routes/_authenticated/components/utils/paneLifecycleRows";
import { useCollections } from "renderer/routes/_authenticated/providers/CollectionsProvider";
import type { AppCollections } from "renderer/routes/_authenticated/providers/CollectionsProvider/collections";
import {
	APP_LAUNCH_ID,
	getNextTabOrder,
	getPrependTabOrder,
	getWorkspaceSidebarBucket,
	isSidebarWorkspaceVisible,
	type WorkspaceLocalStateDraft,
} from "renderer/routes/_authenticated/providers/CollectionsProvider/dashboardSidebarLocal";
import { useHostWorkspaces } from "renderer/routes/_authenticated/providers/HostWorkspacesProvider";
import { useLocalHostService } from "renderer/routes/_authenticated/providers/LocalHostServiceProvider";
import { PROJECT_CUSTOM_COLORS } from "shared/constants/project-colors";
import {
	applyAutomaticSnoozeReturn,
	applyWorkspaceExitCleanup,
	cancelWorkspaceExitCleanup,
	createEmptyPaneLayout,
	removeProjectFromSidebarState,
	resolveSidebarRowProjectId,
	tombstoneSidebarWorkspaceRecord,
	workspaceExitCleanupState,
} from "./sidebarMutations";

/** The per-project reveal/collapse booleans on the sidebar project row. */
export type ProjectSectionFlag =
	| "showSnoozed"
	| "showArchived"
	| "snoozedCollapsed"
	| "archivedCollapsed"
	// (RECYCLE-BIN) reveal + collapse for the per-project Recycle Bin section.
	| "showDeleted"
	| "deletedCollapsed";

type ProjectTopLevelItem = {
	type: "workspace" | "section";
	id: string;
	tabOrder: number;
};

type ProjectTopLevelCollections = Pick<
	AppCollections,
	"v2SidebarSections" | "v2WorkspaceLocalState"
>;

function compareProjectTopLevelItems(
	left: ProjectTopLevelItem,
	right: ProjectTopLevelItem,
): number {
	const orderDelta = left.tabOrder - right.tabOrder;
	if (orderDelta !== 0) return orderDelta;
	if (left.type === right.type) return 0;
	return left.type === "section" ? -1 : 1;
}

function getProjectTopLevelItems(
	collections: ProjectTopLevelCollections,
	// Null scopes to the Sessions section (project-less workspaces).
	projectId: string | null,
	options: { excludeWorkspaceId?: string; excludeSectionId?: string } = {},
): ProjectTopLevelItem[] {
	return [
		...Array.from(collections.v2WorkspaceLocalState.state.values())
			.filter(
				(item) =>
					item.sidebarState.projectId === projectId &&
					isSidebarWorkspaceVisible(item) &&
					item.sidebarState.sectionId === null &&
					item.workspaceId !== options.excludeWorkspaceId,
			)
			.map((item) => ({
				type: "workspace" as const,
				id: item.workspaceId,
				tabOrder: item.sidebarState.tabOrder,
			})),
		...Array.from(collections.v2SidebarSections.state.values())
			.filter(
				(item) =>
					item.projectId === projectId &&
					item.sectionId !== options.excludeSectionId,
			)
			.map((item) => ({
				type: "section" as const,
				id: item.sectionId,
				tabOrder: item.tabOrder,
			})),
	].sort(compareProjectTopLevelItems);
}

function getFirstSectionIndex(items: ProjectTopLevelItem[]): number {
	const firstSectionIndex = items.findIndex((item) => item.type === "section");
	return firstSectionIndex === -1 ? items.length : firstSectionIndex;
}

/**
 * Rewrites the flat top-level project lane. Workspace items are explicitly
 * ungrouped by setting sidebarState.projectId and clearing sidebarState.sectionId.
 */
function writeProjectTopLevelOrder(
	collections: ProjectTopLevelCollections,
	projectId: string | null,
	items: ProjectTopLevelItem[],
): void {
	items.forEach((item, index) => {
		const tabOrder = index + 1;
		if (item.type === "workspace") {
			if (!collections.v2WorkspaceLocalState.get(item.id)) return;
			collections.v2WorkspaceLocalState.update(item.id, (draft) => {
				draft.sidebarState.projectId = projectId;
				draft.sidebarState.sectionId = null;
				draft.sidebarState.tabOrder = tabOrder;
				draft.sidebarState.isHidden = false;
			});
			return;
		}

		if (!collections.v2SidebarSections.get(item.id)) return;
		collections.v2SidebarSections.update(item.id, (draft) => {
			draft.tabOrder = tabOrder;
		});
	});
}

function ensureSidebarProjectRecord(
	collections: Pick<AppCollections, "v2SidebarProjects">,
	projectId: string,
): void {
	if (collections.v2SidebarProjects.get(projectId)) {
		return;
	}

	collections.v2SidebarProjects.insert({
		projectId,
		createdAt: new Date(),
		// Prepend, matching new workspaces: the project you just added is
		// the one you're about to work in.
		tabOrder: getPrependTabOrder([
			...collections.v2SidebarProjects.state.values(),
		]),
		isCollapsed: false,
	});
}

function ensureSidebarWorkspaceRecord(
	collections: Pick<
		AppCollections,
		"v2SidebarSections" | "v2WorkspaceLocalState"
	>,
	workspaceId: string,
	// Null places the workspace in the Sessions section.
	projectId: string | null,
	// (KANBAN HOST SOURCE) resolved by the caller from the host-served lists;
	// the Electric mirror lacks post-migration rows. Omitted where the caller
	// has already established there is no existing row to classify.
	workspaceType: string | null = null,
): void {
	const existing = collections.v2WorkspaceLocalState.get(workspaceId);
	// Already placed — don't resurrect into active. An active row, a snoozed row,
	// or an archived row (archivedAt set, OR a removed non-main thread surfaced
	// under Archived) all stay put on re-open (view-in-place). Only a "hidden"
	// row (a removed MAIN workspace: isHidden, no archive) is pulled back into the
	// active lane when explicitly opened. Classified via the shared
	// getWorkspaceSidebarBucket so the rule matches exactly what the sidebar renders.
	if (existing) {
		if (
			getWorkspaceSidebarBucket(existing, Date.now(), workspaceType) !==
			"hidden"
		) {
			return;
		}
	}

	const topLevelItems = getProjectTopLevelItems(collections, projectId);

	if (existing) {
		collections.v2WorkspaceLocalState.update(workspaceId, (draft) => {
			draft.sidebarState.projectId = projectId;
			draft.sidebarState.tabOrder = getPrependTabOrder(topLevelItems);
			draft.sidebarState.sectionId = null;
			draft.sidebarState.isHidden = false;
		});
		return;
	}

	collections.v2WorkspaceLocalState.insert({
		workspaceId,
		createdAt: new Date(),
		sidebarState: {
			projectId,
			tabOrder: getPrependTabOrder(topLevelItems),
			sectionId: null,
			isHidden: false,
		},
		paneLayout: createEmptyPaneLayout(),
	});
}

function getTerminalRuntimeId(pane: Pane<unknown>): string | null {
	if (pane.kind !== "terminal") return null;
	if (!pane.data || typeof pane.data !== "object") return null;
	const data = pane.data as { terminalId?: unknown };
	return typeof data.terminalId === "string" ? data.terminalId : null;
}

function getBrowserRuntimeId(pane: Pane<unknown>): string | null {
	return pane.kind === "browser" ? pane.id : null;
}

/**
 * Tears down the renderer runtimes behind a workspace's panes.
 *
 * `terminalAction` is the whole difference between the two callers. Sidebar
 * REMOVAL only `release`s — it detaches the renderer view and leaves the host
 * PTY running, because a removed row is a display decision the user can undo by
 * re-opening the workspace. (WORKTREE-EXIT-CLEANUP) An EXIT is not: the user is
 * done with the thread, so the terminal runtime is `dispose`d outright (which
 * also tells host-service to kill the session and clears the persisted
 * snapshot, so nothing survives to be restored). Browser panes are destroyed
 * either way — they hold no host-side session.
 */
function cleanupWorkspacePaneRuntimes(
	rows: PaneLifecycleRow[],
	terminalAction: "release" | "dispose" = "release",
): void {
	for (const terminalId of extractPaneIds(rows, getTerminalRuntimeId)) {
		if (terminalAction === "dispose")
			terminalRuntimeRegistry.dispose(terminalId);
		else terminalRuntimeRegistry.release(terminalId);
	}
	for (const browserId of extractPaneIds(rows, getBrowserRuntimeId)) {
		browserRuntimeRegistry.destroy(browserId);
	}
}

/**
 * (WORKTREE-EXIT-CLEANUP) Tear down the renderer half of a workspace the user
 * has exited. Call this immediately BEFORE the row update that wipes
 * `paneLayout` — the pane ids it needs live in the layout it is about to clear.
 * A row-less workspace (an insert branch) has no panes to dispose, only the
 * host's half to request.
 */
function disposeExitedWorkspaceRuntimes(
	collections: Pick<AppCollections, "v2WorkspaceLocalState">,
	workspaceId: string,
): void {
	const existing = collections.v2WorkspaceLocalState.get(workspaceId);
	if (existing) cleanupWorkspacePaneRuntimes([existing], "dispose");
}

/**
 * (WORKTREE-EXIT-CLEANUP) Exit a workspace row that already exists — Archive,
 * Snooze, Recycle Bin and Completed all end here, and none of them owns any of
 * the four steps below.
 *
 * ONE TIMESTAMP FOR THE WHOLE ACTION, read here and handed to `applyExitFlags`.
 * The pending stamp IDENTIFIES the debt, so the lifecycle stamp a caller writes
 * (`archivedAt`, `deletedAt`) has to name the same instant the cleanup stamp
 * does — a second `Date.now()` would stamp a debt no host reply could quote.
 *
 * THE ORDER IS LOAD-BEARING. Renderer runtimes are disposed BEFORE the update,
 * because the pane ids they need live in the `paneLayout` the update clears.
 *
 * ROW-LESS WORKSPACES NEVER REACH HERE: with no row there are no panes to
 * dispose and nothing to update, so each caller's insert branch stamps
 * {@link workspaceExitCleanupState} on the row it creates instead — its host
 * may still be running terminals and holding a pinned account for it.
 */
function exitWorkspaceRow(
	collections: Pick<AppCollections, "v2WorkspaceLocalState">,
	workspaceId: string,
	applyExitFlags: (
		draft: WritableDeep<WorkspaceLocalStateDraft>,
		exitedAt: number,
	) => void,
): void {
	const exitedAt = Date.now();
	disposeExitedWorkspaceRuntimes(collections, workspaceId);
	collections.v2WorkspaceLocalState.update(workspaceId, (draft) => {
		applyExitFlags(draft, exitedAt);
		applyWorkspaceExitCleanup(draft, exitedAt);
	});
}

type WorkspaceCompletionHostRow = Pick<
	HostShapedWorkspace,
	"id" | "projectId" | "type"
>;

type WorkspaceCompletionCollections = Pick<
	AppCollections,
	"v2SidebarProjects" | "v2SidebarSections" | "v2WorkspaceLocalState"
>;

/**
 * Runs the complete-card sidebar lifecycle without requiring the full sidebar
 * React hook. The command owns row creation and workspace-type validation so
 * repair callers cannot bypass exit cleanup when a prior write stopped halfway.
 */
export function completeWorkspaceInSidebar(
	collections: WorkspaceCompletionCollections,
	hostWorkspaces: readonly WorkspaceCompletionHostRow[],
	workspaceId: string,
	completedAt: number,
): boolean {
	const hostWorkspace = hostWorkspaces.find(
		(candidate) => candidate.id === workspaceId,
	);
	if (!hostWorkspace) {
		console.error(
			`[completeWorkspace] refusing to complete ${workspaceId}: workspace type unresolvable (host lists miss)`,
		);
		return false;
	}
	if (hostWorkspace.type === "main") return false;

	if (!collections.v2WorkspaceLocalState.get(workspaceId)) {
		if (hostWorkspace.projectId !== null) {
			ensureSidebarProjectRecord(collections, hostWorkspace.projectId);
		}
		ensureSidebarWorkspaceRecord(
			collections,
			workspaceId,
			hostWorkspace.projectId,
			hostWorkspace.type,
		);
	}
	if (!collections.v2WorkspaceLocalState.get(workspaceId)) {
		console.error(
			`[completeWorkspace] failed to create sidebar state for ${workspaceId}`,
		);
		return false;
	}

	// The caller's `completedAt` is the board's own record of when the card
	// landed in Completed and can be older than this call, so the cleanup debt
	// gets its own instant from `exitWorkspaceRow`.
	exitWorkspaceRow(collections, workspaceId, (draft) => {
		draft.sidebarState.completedAt = completedAt;
		// isHidden too, so raw-visibility consumers (notifications, ports,
		// accessible-list "in sidebar") treat it like an archived row. The bucket
		// classifier checks completedAt first, so it never appears under Archived.
		draft.sidebarState.isHidden = true;
		draft.sidebarState.archivedAt = null;
		draft.sidebarState.snoozeUntil = null;
		draft.sidebarState.snoozeLaunchId = null;
	});
	return true;
}

export function uncompleteWorkspaceInSidebar(
	collections: Pick<AppCollections, "v2WorkspaceLocalState">,
	workspaceId: string,
): boolean {
	if (!collections.v2WorkspaceLocalState.get(workspaceId)) return false;
	collections.v2WorkspaceLocalState.update(workspaceId, (draft) => {
		draft.sidebarState.completedAt = null;
		draft.sidebarState.isHidden = false;
		draft.sidebarState.archivedAt = null;
		cancelWorkspaceExitCleanup(draft.sidebarState);
	});
	return true;
}

