// --- Snooze / Archive ---------------------------------------------------
// The worktree and branch are untouched, and every sidebar flag is
// restorable. The workspace's RUNTIME is not: (WORKTREE-EXIT-CLEANUP) treats
// Snooze and Archive as exits like Completed and Recycle Bin, so both clear
// the tabs, dispose the terminals and hand the host its half of the teardown
// (kill the sessions, release the pinned Claude account). A restored thread
// comes back as an empty workspace, not with a wall of stale panes.
//
// Snooze is TIMED and the account release is not: a snoozed thread returns
// on its own, but it returns Following, and re-pinning it is a manual
// choice. That asymmetry is deliberate and signed off — the point of
// snoozing is to stop the thread consuming an account while it waits, and a
// pin that came back by itself would quietly resume the spend.

const archiveWorkspace = useCallback(
	// (RECYCLE-BIN-SESSIONS) Same contract as deleteWorkspace / snoozeWorkspace:
	// an EXPLICIT null projectId is a session, omitting it falls back to the
	// host record. `RemoveFromSidebarMount` already passes `string | null`.
	(workspaceId: string, projectId?: string | null) => {
		if (!collections.v2WorkspaceLocalState.get(workspaceId)) {
			const exitedAt = Date.now();
			// An auto-included main workspace (shown in the sidebar without an
			// explicit local-state row) has nothing to update yet. Insert a row
			// that is already archived so "Archive" / "Remove from Sidebar" takes
			// effect — a master card can be archived but never hard-removed.
			// Prefer the caller's projectId (the remove intent / row already
			// carries it); fall back to the workspace record.
			const hostWorkspace =
				hostWorkspaces.find((candidate) => candidate.id === workspaceId) ??
				null;
			if (projectId === undefined && hostWorkspace === null) {
				// Fail loud rather than silently dropping the archive — nothing else
				// can recover an un-archived master card from here.
				console.error(
					`[archiveWorkspace] cannot archive ${workspaceId}: no local-state row, no host record and no projectId passed`,
				);
				return;
			}
			const resolvedProjectId = resolveSidebarRowProjectId(
				projectId,
				hostWorkspace?.projectId ?? null,
			);
			collections.v2WorkspaceLocalState.insert({
				workspaceId,
				createdAt: new Date(),
				sidebarState: {
					projectId: resolvedProjectId,
					tabOrder: 0,
					sectionId: null,
					isHidden: true,
					archivedAt: exitedAt,
					...workspaceExitCleanupState(exitedAt),
				},
				paneLayout: createEmptyPaneLayout(),
			});
			return;
		}
		exitWorkspaceRow(collections, workspaceId, (draft, exitedAt) => {
			draft.sidebarState.isHidden = true;
			draft.sidebarState.archivedAt = exitedAt;
			draft.sidebarState.snoozeUntil = null;
			draft.sidebarState.snoozeLaunchId = null;
		});
	},
	[collections, hostWorkspaces],
);

const snoozeWorkspace = useCallback(
	// (RECYCLE-BIN-SESSIONS) Same contract as deleteWorkspace: an EXPLICIT null
	// projectId is a session, omitting it falls back to the host record.
	(
		workspaceId: string,
		until: number | "next-launch",
		projectId?: string | null,
	) => {
		// (SNOOZE-MAIN) An auto-included local MAIN workspace has no local-state
		// row, so the update below used to silently no-op — Snooze on a master
		// row did nothing. Mirror archiveWorkspace: insert a pre-snoozed row.
		if (!collections.v2WorkspaceLocalState.get(workspaceId)) {
			const exitedAt = Date.now();
			const hostWorkspace =
				hostWorkspaces.find((candidate) => candidate.id === workspaceId) ??
				null;
			if (projectId === undefined && hostWorkspace === null) {
				// Nothing to stamp the row with and nothing to read it from — fail
				// loud rather than silently dropping the snooze.
				console.error(
					`[snoozeWorkspace] cannot snooze ${workspaceId}: no local-state row, no host record and no projectId passed`,
				);
				return;
			}
			const resolvedProjectId = resolveSidebarRowProjectId(
				projectId,
				hostWorkspace?.projectId ?? null,
			);
			collections.v2WorkspaceLocalState.insert({
				workspaceId,
				createdAt: new Date(),
				sidebarState: {
					projectId: resolvedProjectId,
					tabOrder: 0,
					sectionId: null,
					isHidden: false,
					...workspaceExitCleanupState(exitedAt),
					...(until === "next-launch"
						? { snoozeLaunchId: APP_LAUNCH_ID }
						: { snoozeUntil: until }),
				},
				paneLayout: createEmptyPaneLayout(),
			});
			return;
		}
		exitWorkspaceRow(collections, workspaceId, (draft) => {
			if (until === "next-launch") {
				draft.sidebarState.snoozeUntil = null;
				draft.sidebarState.snoozeLaunchId = APP_LAUNCH_ID;
			} else {
				draft.sidebarState.snoozeUntil = until;
				draft.sidebarState.snoozeLaunchId = null;
			}
			draft.sidebarState.isHidden = false;
			draft.sidebarState.archivedAt = null;
		});
	},
	[collections, hostWorkspaces],
);

const autoReturnSnoozedWorkspace = useCallback(
	(workspaceId: string) => {
		if (!collections.v2WorkspaceLocalState.get(workspaceId)) return;
		collections.v2WorkspaceLocalState.update(workspaceId, (draft) => {
			applyAutomaticSnoozeReturn(draft.sidebarState);
		});
	},
	[collections],
);

const unsnoozeWorkspace = useCallback(
	(workspaceId: string) => {
		if (!collections.v2WorkspaceLocalState.get(workspaceId)) return;
		collections.v2WorkspaceLocalState.update(workspaceId, (draft) => {
			applyAutomaticSnoozeReturn(draft.sidebarState);
			cancelWorkspaceExitCleanup(draft.sidebarState);
		});
	},
	[collections],
