1	import {
2		createContext,
3		type ReactNode,
4		useCallback,
5		useContext,
6		useEffect,
7		useMemo,
8		useRef,
9		useState,
10	} from "react";
11	import { env } from "renderer/env.renderer";
12	import { authClient } from "renderer/lib/auth-client";
13	import {
14		CLOUD_TRPC_ROUTER_ROOTS,
15		setCloudOrganizationId,
16	} from "renderer/lib/cloud-trpc";
17	import { useActiveOrganizationId } from "renderer/lib/local-identity";
18	import { electronTrpcClient } from "renderer/lib/trpc-client";
19	import { electronQueryClient } from "renderer/providers/ElectronTRPCProvider/ElectronTRPCProvider";
20	import {
21		evictInactiveOrgCollections,
22		getCollections,
23		preloadCollections,
24	} from "./collections";
25	
26	// Cloud query procedures take no organizationId input (the server scopes by
27	// active org), so their React Query keys don't encode the org — on org switch
28	// the previous org's rows must be dropped, not just marked stale.
29	const ORG_SCOPED_CLOUD_ROUTERS = new Set<string>(CLOUD_TRPC_ROUTER_ROOTS);
30	
31	function dropCloudQueriesForOrgSwitch(): void {
32		electronQueryClient.removeQueries({
33			predicate: (query) => {
34				const head = query.queryKey[0];
35				return (
36					Array.isArray(head) &&
37					typeof head[0] === "string" &&
38					ORG_SCOPED_CLOUD_ROUTERS.has(head[0])
39				);
40			},
41		});
42	}
43	
44	type CollectionsContextType = ReturnType<typeof getCollections> & {
45		activeOrganizationId: string;
46		switchOrganization: (organizationId: string) => Promise<void>;
47	};
48	
49	const CollectionsContext = createContext<CollectionsContextType | null>(null);
50	
51	export function preloadActiveOrganizationCollections(
52		activeOrganizationId: string | null | undefined,
53	): void {
54		if (!activeOrganizationId) return;
55		void preloadCollections(activeOrganizationId).catch((error) => {
56			console.error(
57				"[collections-provider] Failed to preload active org collections:",
58				error,
59			);
60		});
61	}
62	
63	export function CollectionsProvider({ children }: { children: ReactNode }) {
64		const { refetch: refetchSession } = authClient.useSession();
65		const [isSwitching, setIsSwitching] = useState(false);
66		// (CLOUD-SEVERANCE-P2) Frozen local organization — the collection keys are
67		// suffixed with it, so it must be stable for the life of the process.
68		//
69		// Upstream made this per-window: it seeded from the shared login session,
70		// reconciled against the account's organization list, and let each window
71		// switch independently. None of those inputs exist here — there is exactly
72		// one organization, resolved from disk by main before this window renders —
73		// so the window's org is simply that one, known synchronously. The two
74		// per-window SINKS below are kept and fed, because they are what the rest of
75		// upstream's multi-window work reads.
76		const activeOrganizationId = useActiveOrganizationId();
77	
78		// Scope this window's cloud reads to its own org, during render rather than
79		// in an effect: children below issue their first queries while this render
80		// commits, and an effect would let those go out on the session's org — the
81		// other window's data — before correcting itself.
82		setCloudOrganizationId(activeOrganizationId);
83	
84		// Keep the main-process window registry in sync with this window's active
85		// org. Declarative and idempotent: re-asserted whenever the org changes, so
86		// the registry (which backs the window title, restore-on-relaunch, and
