15	/**
16	 * Map-backed store that refuses writes once the retained bytes exceed `limit`,
17	 * the way Chromium refuses once the origin's budget is gone.
18	 */
19	function makeQuotaLimitedStorage(limit: number) {
20		const map = new Map<string, string>();
21		const usedBytes = () => {
22			let total = 0;
23			for (const [key, value] of map) total += key.length + value.length;
24			return total;
25		};
26		return {
27			store: map,
28			usedBytes,
29			api: {
30				getItem: (key: string) => map.get(key) ?? null,
31				setItem: (key: string, value: string) => {
32					const replaced = map.get(key)?.length ?? 0;
33					if (usedBytes() - replaced + key.length + value.length > limit) {
34						throw quotaError();
35					}
36					map.set(key, value);
37				},
38				removeItem: (key: string) => {
39					map.delete(key);
40				},
41			},
42		};
43	}
