import { getPersistFailureGeneration } from "./withQuotaGuard";

interface PersistableTransaction {
	isPersisted: { promise: Promise<unknown> };
}

interface PendingExit {
	readonly storageKey: string;
	readonly failureGeneration: number;
	readonly result: Promise<boolean>;
	resolve: (persisted: boolean) => void;
	settled: boolean;
}

export interface WorkspaceExitPersistenceRegistration {
	readonly organizationId: string;
	readonly workspaceId: string;
	readonly cleanupStamp: number;
	readonly pending: PendingExit;
}

const pendingExits = new Map<string, Set<PendingExit>>();

function workspaceLocalStateStorageKey(organizationId: string): string {
	if (organizationId.length === 0) {
		throw new Error(
			"Cannot persist a workspace exit without an organization ID",
		);
	}
	return `v2-workspace-local-state-${organizationId}`;
}

function pendingExitKey(
	organizationId: string,
	workspaceId: string,
	cleanupStamp: number,
): string {
	if (workspaceId.length === 0) {
		throw new Error("Cannot persist a workspace exit without a workspace ID");
	}
	if (!Number.isFinite(cleanupStamp)) {
		throw new Error(
			"Cannot persist a workspace exit with an invalid cleanup stamp",
		);
	}
	return `${organizationId}�${workspaceId}�${cleanupStamp}`;
}

export function registerWorkspaceExitPersistence(
	organizationId: string,
	workspaceId: string,
	cleanupStamp: number,
): WorkspaceExitPersistenceRegistration {
	const storageKey = workspaceLocalStateStorageKey(organizationId);
	const key = pendingExitKey(organizationId, workspaceId, cleanupStamp);
	let resolve!: (persisted: boolean) => void;
	const result = new Promise<boolean>((settle) => {
		resolve = settle;
	});
	const pending: PendingExit = {
		storageKey,
		failureGeneration: getPersistFailureGeneration(storageKey),
		result,
		resolve,
		settled: false,
	};
	const registrations = pendingExits.get(key) ?? new Set<PendingExit>();
	registrations.add(pending);
	pendingExits.set(key, registrations);
	return { organizationId, workspaceId, cleanupStamp, pending };
}

function settleRegistration(
	registration: WorkspaceExitPersistenceRegistration,
	persisted: boolean,
	remove: boolean,
): void {
	const { organizationId, workspaceId, cleanupStamp, pending } = registration;
	if (pending.settled) {
		throw new Error(
			`Workspace exit persistence was settled twice for ${workspaceId}`,
		);
	}
	pending.settled = true;
	if (remove) {
		const key = pendingExitKey(organizationId, workspaceId, cleanupStamp);
		const registrations = pendingExits.get(key);
		registrations?.delete(pending);
		if (registrations?.size === 0) pendingExits.delete(key);
	}
	pending.resolve(persisted);
}

export function cancelWorkspaceExitPersistence(
	registration: WorkspaceExitPersistenceRegistration,
): void {
	settleRegistration(registration, false, true);
}

export async function confirmWorkspaceExitPersistence(
	registration: WorkspaceExitPersistenceRegistration,
	transaction: PersistableTransaction,
): Promise<void> {
	try {
		await transaction.isPersisted.promise;
		const currentGeneration = getPersistFailureGeneration(
			registration.pending.storageKey,
		);
		if (currentGeneration !== registration.pending.failureGeneration) {
			throw new Error(
				`Workspace exit was not saved for ${registration.workspaceId}: local storage is full`,
			);
		}
		settleRegistration(registration, true, true);
	} catch (error) {
		settleRegistration(registration, false, false);
		throw error;
	}
}

export async function waitForWorkspaceExitPersistence(
	organizationId: string,
	workspaceId: string,
	cleanupStamp: number,
): Promise<boolean> {
	const registrations = pendingExits.get(
		pendingExitKey(organizationId, workspaceId, cleanupStamp),
	);
	if (!registrations || registrations.size === 0) return true;
	const results = await Promise.all(
		Array.from(registrations, (pending) => pending.result),
	);
	return results.every(Boolean);
}

