1	import {
2		beginLocalCollectionWrite,
3		confirmLocalCollectionWrite,
4	} from "./localCollectionPersistence";
5	
6	interface PersistableTransaction {
7		isPersisted: { promise: Promise<unknown> };
8	}
9	
10	interface PendingAttempt {
11		readonly result: Promise<boolean>;
12		resolve: (persisted: boolean) => void;
13		settled: boolean;
14	}
15	
16	interface WorkspaceExitEntry {
17		readonly cleanupStamp: number;
18		readonly attempts: Set<PendingAttempt>;
19		failed: boolean;
20	}
21	
22	const pendingExits = new Map<string, WorkspaceExitEntry>();
23	
24	function workspaceLocalStateStorageKey(organizationId: string): string {
25		if (organizationId.length === 0) {
26			throw new Error(
27				"Cannot persist a workspace exit without an organization ID",
28			);
29		}
30		return `v2-workspace-local-state-${organizationId}`;
31	}
32	
33	function workspaceExitKey(organizationId: string, workspaceId: string): string {
34		if (workspaceId.length === 0) {
35			throw new Error("Cannot persist a workspace exit without a workspace ID");
36		}
37		return JSON.stringify([organizationId, workspaceId]);
38	}
39	
40	function validateCleanupStamp(cleanupStamp: number): void {
41		if (!Number.isFinite(cleanupStamp)) {
42			throw new Error(
43				"Cannot persist a workspace exit with an invalid cleanup stamp",
44			);
45		}
46	}
47	
48	function createAttempt(): PendingAttempt {
49		let resolve!: (persisted: boolean) => void;
50		const result = new Promise<boolean>((settle) => {
51			resolve = settle;
52		});
53		return { result, resolve, settled: false };
54	}
55	
56	function settleAttempt(attempt: PendingAttempt, persisted: boolean): void {
57		if (attempt.settled) return;
58		attempt.settled = true;
59		attempt.resolve(persisted);
60	}
61	
62	function getOrReplaceEntry(
63		key: string,
64		cleanupStamp: number,
65	): WorkspaceExitEntry {
66		const existing = pendingExits.get(key);
67		if (existing?.cleanupStamp === cleanupStamp) return existing;
68		if (existing) {
69			for (const attempt of existing.attempts) settleAttempt(attempt, false);
70		}
71		const entry: WorkspaceExitEntry = {
72			cleanupStamp,
73			attempts: new Set(),
74			failed: false,
75		};
76		pendingExits.set(key, entry);
77		return entry;
78	}
79	
80	function finishAttempt(
81		key: string,
82		entry: WorkspaceExitEntry,
83		attempt: PendingAttempt,
84		persisted: boolean,
85	): void {
86		entry.attempts.delete(attempt);
87		if (!persisted) entry.failed = true;
88		settleAttempt(attempt, persisted && !entry.failed);
89		if (
90			pendingExits.get(key) === entry &&
91			entry.attempts.size === 0 &&
92			!entry.failed
93		) {
94			pendingExits.delete(key);
95		}
96	}
97	
98	export function persistWorkspaceExitMutation(
99		organizationId: string,
100		workspaceId: string,
101		cleanupStamp: number,
102		mutate: () => PersistableTransaction,
103	): Promise<void> {
104		validateCleanupStamp(cleanupStamp);
105		const key = workspaceExitKey(organizationId, workspaceId);
106		const entry = getOrReplaceEntry(key, cleanupStamp);
107		const attempt = createAttempt();
108		entry.attempts.add(attempt);
109		const receipt = beginLocalCollectionWrite(
110			workspaceLocalStateStorageKey(organizationId),
111		);
112		let transaction: PersistableTransaction;
113		try {
114			transaction = mutate();
115		} catch (error) {
116			entry.attempts.delete(attempt);
117			settleAttempt(attempt, false);
118			if (entry.attempts.size === 0 && !entry.failed) pendingExits.delete(key);
119			throw error;
120		}
121	
122		return confirmLocalCollectionWrite(receipt, transaction).then(
123			() => {
124				finishAttempt(key, entry, attempt, true);
125			},
126			(error: unknown) => {
127				finishAttempt(key, entry, attempt, false);
128				throw new Error(`Workspace exit was not saved for ${workspaceId}`, {
129					cause: error,
130				});
131			},
132		);
133	}
134	
135	export async function waitForWorkspaceExitPersistence(
136		organizationId: string,
137		workspaceId: string,
138		cleanupStamp: number,
139	): Promise<boolean> {
140		validateCleanupStamp(cleanupStamp);
141		const key = workspaceExitKey(organizationId, workspaceId);
142		const entry = pendingExits.get(key);
143		if (!entry || entry.cleanupStamp !== cleanupStamp) return true;
144		if (entry.failed) return false;
145		const results = await Promise.all(
146			Array.from(entry.attempts, (attempt) => attempt.result),
147		);
148		const current = pendingExits.get(key);
149		if (current !== entry) {
150			return waitForWorkspaceExitPersistence(
151				organizationId,
152				workspaceId,
153				cleanupStamp,
154			);
155		}
156		if (entry.failed) return false;
157		if (entry.attempts.size > 0) {
158			return waitForWorkspaceExitPersistence(
159				organizationId,
160				workspaceId,
161				cleanupStamp,
162			);
163		}
164		return results.every(Boolean);
165	}

