220	/**
221	 * Tears down the renderer runtimes behind a workspace's panes.
222	 *
223	 * `terminalAction` is the whole difference between the two callers. Sidebar
224	 * REMOVAL only `release`s — it detaches the renderer view and leaves the host
225	 * PTY running, because a removed row is a display decision the user can undo by
226	 * re-opening the workspace. (WORKTREE-EXIT-CLEANUP) An EXIT is not: the user is
227	 * done with the thread, so the terminal runtime is `dispose`d outright (which
228	 * also tells host-service to kill the session and clears the persisted
229	 * snapshot, so nothing survives to be restored). Browser panes are destroyed
230	 * either way — they hold no host-side session.
231	 */
232	interface WorkspacePaneRuntimeIds {
233		terminalIds: string[];
234		browserIds: string[];
235	}
236	
237	function extractWorkspacePaneRuntimeIds(
238		rows: PaneLifecycleRow[],
239	): WorkspacePaneRuntimeIds {
240		return {
241			terminalIds: extractPaneIds(rows, getTerminalRuntimeId),
242			browserIds: extractPaneIds(rows, getBrowserRuntimeId),
243		};
244	}
245	
246	function cleanupWorkspacePaneRuntimeIds(
247		{ terminalIds, browserIds }: WorkspacePaneRuntimeIds,
248		terminalAction: "release" | "dispose" = "release",
249	): void {
250		for (const terminalId of terminalIds) {
251			if (terminalAction === "dispose")
252				terminalRuntimeRegistry.dispose(terminalId);
253			else terminalRuntimeRegistry.release(terminalId);
254		}
255		for (const browserId of browserIds) browserRuntimeRegistry.destroy(browserId);
256	}
257	
258	function cleanupWorkspacePaneRuntimes(
259		rows: PaneLifecycleRow[],
260		terminalAction: "release" | "dispose" = "release",
261	): void {
262		cleanupWorkspacePaneRuntimeIds(
263			extractWorkspacePaneRuntimeIds(rows),
264			terminalAction,
265		);
266	}
267	
268	type WorkspaceExitCollections = Pick<
269		AppCollections,
270		"v2WorkspaceLocalState"
271	> & { activeOrganizationId: string };
272	
273	/**
274	 * (WORKTREE-EXIT-CLEANUP) Register cleanup debt before the optimistic mutation,
275	 * then wait for the whole localStorage collection to land before destroying
276	 * renderer runtimes. The reconciler waits on the same registration before it
277	 * asks any host to retire sessions or release the workspace account.
278	 */
279	function persistWorkspaceExit(
280		collections: WorkspaceExitCollections,
281		workspaceId: string,
282		exitedAt: number,
283		mutate: () => {
284			isPersisted: { promise: Promise<unknown> };
285		},
286	): Promise<void> {
287		return persistWorkspaceExitMutation(
288			collections.activeOrganizationId,
289			workspaceId,
290			exitedAt,
291			mutate,
292		);
293	}
294	
295	/**
296	 * (WORKTREE-EXIT-CLEANUP) Exit an existing workspace row. The original pane row
297	 * is captured before the mutation clears it, but its runtimes stay alive until
298	 * the exit and its cleanup stamp are durably saved.
299	 */
300	function exitWorkspaceRow(
301		collections: WorkspaceExitCollections,
302		workspaceId: string,
303		applyExitFlags: (
304			draft: WritableDeep<WorkspaceLocalStateDraft>,
305			exitedAt: number,
306		) => void,
307	): void {
308		const existing = collections.v2WorkspaceLocalState.get(workspaceId);
309		if (!existing) {
310			throw new Error(`Cannot exit missing workspace row ${workspaceId}`);
311		}
312		const exitedAt = Date.now();
313		const runtimeIds = extractWorkspacePaneRuntimeIds([existing]);
314		void persistWorkspaceExit(collections, workspaceId, exitedAt, () =>
315			collections.v2WorkspaceLocalState.update(workspaceId, (draft) => {
316				applyExitFlags(draft, exitedAt);
317				applyWorkspaceExitCleanup(draft, exitedAt);
318			}),
319		).then(() => cleanupWorkspacePaneRuntimeIds(runtimeIds, "dispose"));
320	}
321	
322	type RowlessWorkspaceExitFlags = Pick<
323		WorkspaceLocalStateDraft["sidebarState"],
324		"isHidden"
325	> &
326		Partial<
327			Pick<
328				WorkspaceLocalStateDraft["sidebarState"],
329				| "archivedAt"
330				| "completedAt"
331				| "deletedAt"
332				| "snoozeLaunchId"
333				| "snoozeUntil"
334			>
335		>;
336	
337	function insertWorkspaceExitRow(
338		collections: WorkspaceExitCollections,
339		workspaceId: string,
340		projectId: string | null,
341		createFlags: (exitedAt: number) => RowlessWorkspaceExitFlags,
342	): void {
343		const exitedAt = Date.now();
344		void persistWorkspaceExit(collections, workspaceId, exitedAt, () =>
345			collections.v2WorkspaceLocalState.insert({
346				workspaceId,
347				createdAt: new Date(),
348				sidebarState: {
349					projectId,
350					tabOrder: 0,
351					sectionId: null,
352					...workspaceExitCleanupState(exitedAt),
353					...createFlags(exitedAt),
354				},
355				paneLayout: createEmptyPaneLayout(),
356			}),
357		);
358	}
