370	/**
371	 * Runs the complete-card sidebar lifecycle without requiring the full sidebar
372	 * React hook. The command owns row creation and workspace-type validation so
373	 * repair callers cannot bypass exit cleanup when a prior write stopped halfway.
374	 */
375	export function completeWorkspaceInSidebar(
376		collections: WorkspaceCompletionCollections,
377		hostWorkspaces: readonly WorkspaceCompletionHostRow[],
378		workspaceId: string,
379		completedAt: number,
380	): boolean {
381		const hostWorkspace = hostWorkspaces.find(
382			(candidate) => candidate.id === workspaceId,
383		);
384		if (!hostWorkspace) {
385			console.error(
386				`[completeWorkspace] refusing to complete ${workspaceId}: workspace type unresolvable (host lists miss)`,
387			);
388			return false;
389		}
390		if (hostWorkspace.type === "main") return false;
391	
392		if (!collections.v2WorkspaceLocalState.get(workspaceId)) {
393			if (hostWorkspace.projectId !== null) {
394				ensureSidebarProjectRecord(collections, hostWorkspace.projectId);
395			}
396			insertWorkspaceExitRow(
397				collections,
398				workspaceId,
399				hostWorkspace.projectId,
400				() => ({
401					completedAt,
402					isHidden: true,
403					archivedAt: null,
404					snoozeUntil: null,
405					snoozeLaunchId: null,
406				}),
407			);
408			return true;
409		}
410	
411		// The caller's `completedAt` is the board's own record of when the card
412		// landed in Completed and can be older than this call, so the cleanup debt
413		// gets its own instant from `exitWorkspaceRow`.
414		exitWorkspaceRow(collections, workspaceId, (draft) => {
415			draft.sidebarState.completedAt = completedAt;
416			// isHidden too, so raw-visibility consumers (notifications, ports,
417			// accessible-list "in sidebar") treat it like an archived row. The bucket
418			// classifier checks completedAt first, so it never appears under Archived.
419			draft.sidebarState.isHidden = true;
420			draft.sidebarState.archivedAt = null;
421			draft.sidebarState.snoozeUntil = null;
422			draft.sidebarState.snoozeLaunchId = null;
423		});
424		return true;
425	}
