import { describe, expect, it } from "bun:test";
import { recordLocalCollectionPersistFailure } from "./localCollectionPersistence";
import { withQuotaGuard } from "./withQuotaGuard";
import {
	persistWorkspaceExitMutation,
	waitForWorkspaceExitPersistence,
} from "./workspaceExitPersistence";

function deferred(): {
	promise: Promise<void>;
	resolve: () => void;
} {
	let resolve!: () => void;
	const promise = new Promise<void>((settle) => {
		resolve = settle;
	});
	return { promise, resolve };
}

function quotaError(): Error {
	const error = new Error("exceeded the quota");
	error.name = "QuotaExceededError";
	return error;
}

describe("workspace exit persistence", () => {
	it("blocks host cleanup until the exit transaction is persisted", async () => {
		const transaction = deferred();
		const confirmation = persistWorkspaceExitMutation(
			"org-success",
			"workspace-1",
			100,
			() => ({ isPersisted: transaction }),
		);
		let waitSettled = false;
		const wait = waitForWorkspaceExitPersistence(
			"org-success",
			"workspace-1",
			100,
		).then((result) => {
			waitSettled = true;
			return result;
		});

		await Promise.resolve();
		expect(waitSettled).toBe(false);

		transaction.resolve();
		await confirmation;
		expect(await wait).toBe(true);
	});

	it("keeps the cleanup stamp blocked when quota handling drops the write", async () => {
		const organizationId = "org-quota-failure";
		const workspaceId = "workspace-2";
		const cleanupStamp = 200;
		const storageKey = `v2-workspace-local-state-${organizationId}`;
		const guarded = withQuotaGuard(
			{},
			{
				storage: {
					getItem: () => null,
					removeItem: () => {},
					setItem: () => {
						throw quotaError();
					},
				},
				reclaim: () => 0,
				onPersistFailed: (key) => recordLocalCollectionPersistFailure(key),
			},
		) as { storage: { setItem: (key: string, value: string) => void } };

		const confirmation = persistWorkspaceExitMutation(
			organizationId,
			workspaceId,
			cleanupStamp,
			() => {
				guarded.storage.setItem(storageKey, "exit state");
				return { isPersisted: { promise: Promise.resolve() } };
			},
		);

		await expect(confirmation).rejects.toThrow(
			`Workspace exit was not saved for ${workspaceId}`,
		);
		expect(
			await waitForWorkspaceExitPersistence(
				organizationId,
				workspaceId,
				cleanupStamp,
			),
		).toBe(false);
	});
});

