import type { AppRouter } from "@superset/host-service";
import type { inferRouterOutputs } from "@trpc/server";

/**
 * (WORKTREE-EXIT-CLEANUP) One host's answer, taken from the host-service router
 * so it cannot drift from what the host actually returns.
 */
export type HostRetirementOutcome =
	inferRouterOutputs<AppRouter>["claudeAccounts"]["retireWorkspaceRuntime"];

/**
 * (WORKTREE-EXIT-CLEANUP) What came back from one host, in the three shapes the
 * verdict turns on.
 *
 * A THROW IS NOT ONE THING, and collapsing it into "no answer" is what made a
 * broken owner look like an owner that was merely off. A host that RESPONDED
 * with an error is a machine that is right there and failed — the user should
 * be told and offered a retry. A request that never got a response at all is a
 * machine that is off, which is not a fault and gets the quiet wait.
 */
export type HostRetirementReply =
	| { kind: "answered"; outcome: HostRetirementOutcome }
	/** The host answered, with an error. It is reachable and it failed. */
	| { kind: "failed" }
	/** Nothing came back: connection refused, dropped stream, DNS. */
	| { kind: "unreachable" };

/**
 * (WORKTREE-EXIT-CLEANUP) What the hosts said, in the three shapes the
 * reconciler acts on differently:
 *
 * - `confirmed` — the teardown is finished, or provably has nothing left to do.
 *   Clear the stamp.
 * - `owner-failed` — a host that OWNS the workspace answered and could not
 *   dispose every terminal. The machine is right there; a retry may well work,
 *   and the user should be told the terminals are still up.
 * - `unreachable` — nobody who could own it answered. Nothing is wrong with the
 *   workspace, the owning machine is just off. Keep the debt quietly.
 */
export type RetirementVerdict = "confirmed" | "owner-failed" | "unreachable";

/**
 * (WORKTREE-EXIT-CLEANUP) Decide, from what the hosts said, whether the
 * workspace's exit cleanup is finished — the one question the reconciler asks,
 * because only a confirmed teardown may clear the pending stamp.
 *
 * A workspace has exactly one owning host, so one owner reporting a clean
 * teardown settles it — an unrelated host being unreachable at the same moment
 * cannot un-finish work its owner already confirmed. `every` rather than `some`
 * over the claimants so the pathological two-owner answer (a stale host row, an
 * id collision) keeps the stamp instead of clearing on the happier of two
 * contradictory replies.
 *
 * Absence is the other way to finish, and the reason this feature cannot
 * accumulate permanent debt. Two forms count, and both are authoritative rather
 * than merely quiet:
 *
 * - The host we RESOLVED as the workspace's owner answered `foundWorkspace:
 *   false`. It is the machine the workspace is filed under and it says the row
 *   is gone (destroyed, or the sandbox it lived in was torn down), so there is
 *   no runtime left to retire. A NON-owner saying the same proves nothing.
 * - `absenceProven`: every host we could ask answered, none of them has it, and
 *   the caller's own absence check agrees the workspace is not merely hiding
 *   behind an offline machine (see `isAbsenceAuthoritative`). This is what
 *   settles a workspace whose owning host was decommissioned entirely.
 *
 * AN OWNER THAT ANSWERED WITH AN ERROR IS A FAULT, not a wait. Nothing was
 * retired and the machine is right there, so it reads exactly like an owner
 * that answered and could not dispose a terminal: the user is told and the
 * Retry button means something. `unreachable` is reserved for the case it was
 * named for — nobody who could own this workspace responded at all.
 */
export function classifyRetirement(args: {
	/** The resolved owner's reply; null when there was no owner to ask. */
	owner: HostRetirementReply | null;
	/** Every other host asked. */
	others: readonly HostRetirementReply[];
	/** No host anywhere can still be hiding this workspace. */
	absenceProven: boolean;
}): RetirementVerdict {
	const replies =
		args.owner === null ? args.others : [args.owner, ...args.others];
	const claimants = replies
		.flatMap((reply) => (reply.kind === "answered" ? [reply.outcome] : []))
		.filter((outcome) => outcome.foundWorkspace === true);
	if (claimants.length > 0) {
		return claimants.every((claimant) => claimant.failed.length === 0)
			? "confirmed"
			: "owner-failed";
	}
	if (args.owner?.kind === "failed") return "owner-failed";
	if (args.owner?.kind === "answered" || args.absenceProven) return "confirmed";
	return "unreachable";
}

/**
 * (WORKTREE-EXIT-CLEANUP) Which URL a workspace's retirement call may actually
 * be sent to, once the owner's kind is taken into account.
 *
 * A CLOUD SANDBOX SLEEPS WHEN NOBODY IS LOOKING AT IT, and any request to its
 * URL wakes the VM — a background sweep would spin up a machine, bill for it
 * and keep it warm to retire terminals that died with the sandbox's last
 * suspend. So the call goes out only while something else is ALREADY holding
 * that sandbox open (its socket is up because the user has the workspace on
 * screen). Otherwise there is no target, the debt is retained untouched, and
 * the next time the user opens that workspace the sweep finds it awake.
 *
 * A normal host is never gated: it is either reachable or it is not, and
 * reaching it costs nothing it was not already paying.
 */
export function resolveRetirementCallUrl(target: {
	ownerHostUrl: string | null;
	isSandbox: boolean;
	/** Only meaningful for a sandbox: is its socket up right now? */
	isAwake: boolean;
}): string | null {
	if (target.ownerHostUrl === null) return null;
	if (target.isSandbox && !target.isAwake) return null;
	return target.ownerHostUrl;
}

export function isCleanupStampCurrent(
	expected: number,
	current: number | null,
): boolean {
	return current === expected;
}

/** What the reconciler should do with one workspace's retirement result. */
export type CleanupVerdict = "clear" | "retry" | "abandon";
/**
 * (WORKTREE-EXIT-CLEANUP) The stale-response guard. A retirement call outlives
 * the user, who is free to restore/unarchive/unsnooze/uncomplete the thread
 * while it is in flight — which CANCELS the pending cleanup. Comparing the
 * stamp read before the call with the stamp now is what stops that late reply
 * from writing to a row it no longer speaks for: `null` means the user un-exited
 * (the host call it already started may finish; its answer is simply ignored),
 * and a DIFFERENT number means they exited again after this attempt began, so
 * this attempt cannot vouch for the newer debt either. Both abandon.
 */
export function decideCleanupOutcome(args: {
	stampBefore: number;
	stampAfter: number | null;
	verdict: RetirementVerdict;
}): CleanupVerdict {
	if (!isCleanupStampCurrent(args.stampBefore, args.stampAfter))
		return "abandon";
	return args.verdict === "confirmed" ? "clear" : "retry";
}

/**
 * (WORKTREE-EXIT-CLEANUP) The standing toast's text, or null for no toast at
 * all. Two states the user would act on differently, and one they would not act
 * on at all:
 *
 * - Terminals that would not close on a machine that is RIGHT THERE is a real
 *   fault worth a retry, and it wins when both kinds are outstanding.
 * - An owner that is simply off is not a fault. It is named so the standing
 *   toast reads as a wait rather than a failure.
 * - Nothing outstanding means no toast, which is the rule that stops a toast
 *   from outliving its debt: un-exiting a workspace empties the pending set,
 *   and an empty set dismisses.
 */
export function describeCleanupToast(counts: {
	blocked: number;
	waiting: number;
}): { title: string; description: string } | null {
	if (counts.blocked > 0) {
		return {
			title: `Couldn't finish closing ${plural(counts.blocked)}`,
			description:
				"Some terminals wouldn't close. Retry, or check the machine that owns them.",
		};
	}
	if (counts.waiting > 0) {
		return {
			title: `Still closing ${plural(counts.waiting)}`,
			description:
				"Their terminals may still be running. This finishes on its own when the machine that owns them comes back.",
		};
	}
	return null;
}

function plural(count: number): string {
	return `${count} workspace${count === 1 ? "" : "s"}`;
}

import { describe, expect, it } from "bun:test";
import {
	classifyRetirement,
	decideCleanupOutcome,
	describeCleanupToast,
	type HostRetirementOutcome,
	isCleanupStampCurrent,
	type HostRetirementReply,
	resolveRetirementCallUrl,
} from "./cleanupDecisions";

function owner(
	overrides: Partial<HostRetirementOutcome> = {},
): HostRetirementReply {
	return {
		kind: "answered",
		outcome: {
			foundWorkspace: true,
			terminated: ["term-1"],
			failed: [],
			accountReleased: true,
			...overrides,
		},
	};
}

/** A host that answered, and does not have this workspace. */
const stranger: HostRetirementReply = {
	kind: "answered",
	outcome: {
		foundWorkspace: false,
		terminated: [],
		failed: [],
		accountReleased: false,
	},
};

/** Nothing came back at all: the machine is off. */
const silent: HostRetirementReply = { kind: "unreachable" };

/** The machine responded, with an error. It is there and it failed. */
const errored: HostRetirementReply = { kind: "failed" };

describe("classifyRetirement", () => {
	it("confirms when the owning host tore everything down", () => {
		expect(
			classifyRetirement({
				owner: owner(),
				others: [stranger],
				absenceProven: false,
			}),
		).toBe("confirmed");
	});

	it("confirms when the owner answered from the broadcast alone", () => {
		expect(
			classifyRetirement({
				owner: null,
				others: [silent, owner()],
				absenceProven: false,
			}),
		).toBe("confirmed");
	});

	it("names a disposal failure separately from an outage", () => {
		expect(
			classifyRetirement({
				owner: owner({ failed: ["term-2"] }),
				others: [],
				absenceProven: false,
			}),
		).toBe("owner-failed");
	});

	it("keeps the stamp when two hosts claim it and one failed", () => {
		expect(
			classifyRetirement({
				owner: null,
				others: [owner(), owner({ failed: ["term-9"] })],
				absenceProven: false,
			}),
		).toBe("owner-failed");
	});

	it("does NOT confirm on a non-owner's polite 'not mine'", () => {
		expect(
			classifyRetirement({
				owner: null,
				others: [stranger, stranger],
				absenceProven: false,
			}),
		).toBe("unreachable");
	});

	it("does NOT confirm when no host answered at all", () => {
		expect(
			classifyRetirement({
				owner: silent,
				others: [silent],
				absenceProven: false,
			}),
		).toBe("unreachable");
	});

	it("confirms when the RESOLVED owner says the workspace is gone", () => {
		// The machine the workspace is filed under answered "not mine": the row
		// was destroyed, so there is no runtime left to retire.
		expect(
			classifyRetirement({
				owner: stranger,
				others: [stranger],
				absenceProven: false,
			}),
		).toBe("confirmed");
	});

	it("confirms a vanished owner: nobody has it and nobody is missing", () => {
		// The owning host was decommissioned. Every host that could be asked
		// answered, none of them has the workspace, so the debt is undischargeable
		// and meaningless — clearing it is what stops permanent toast debt.
		expect(
			classifyRetirement({
				owner: null,
				others: [stranger, stranger],
				absenceProven: true,
			}),
		).toBe("confirmed");
	});

	it("keeps the stamp when absence is claimed but a host stayed silent", () => {
		// `absenceProven` is only ever passed true when every asked host answered,
		// but a silent host must lose to the debt regardless.
		expect(
			classifyRetirement({
				owner: null,
				others: [silent, stranger],
				absenceProven: false,
			}),
		).toBe("unreachable");
	});

	it("calls an owner that ANSWERED WITH AN ERROR a fault, not an outage", () => {
		// The machine is right there and the call blew up on it. Nothing was
		// retired, so the user is told and the Retry button means something —
		// exactly as when the owner answered and could not dispose a terminal.
		expect(
			classifyRetirement({
				owner: errored,
				others: [],
				absenceProven: false,
			}),
		).toBe("owner-failed");
	});

	it("still says unreachable when the owner never responded", () => {
		expect(
			classifyRetirement({
				owner: silent,
				others: [errored],
				absenceProven: false,
			}),
		).toBe("unreachable");
	});

	it("lets a live claimant outrank an owner that errored", () => {
		// A second host has the workspace and tore it down. The owner's error says
		// nothing about work another machine has demonstrably finished.
		expect(
			classifyRetirement({
				owner: errored,
				others: [owner()],
				absenceProven: false,
			}),
		).toBe("confirmed");
	});
});

describe("resolveRetirementCallUrl", () => {
	const SANDBOX = "https://sandbox.example";

	it("calls a normal host whenever it resolved", () => {
		expect(
			resolveRetirementCallUrl({
				ownerHostUrl: "http://host-a",
				isSandbox: false,
				isAwake: false,
			}),
		).toBe("http://host-a");
	});

	it("calls a sandbox that something else is already holding open", () => {
		expect(
			resolveRetirementCallUrl({
				ownerHostUrl: SANDBOX,
				isSandbox: true,
				isAwake: true,
			}),
		).toBe(SANDBOX);
	});

	it("leaves a SLEEPING sandbox alone rather than waking it", () => {
		// The request itself would spin the VM up and bill for it, to retire
		// terminals that died with the sandbox's last suspend. No target means the
		// debt is simply retained.
		expect(
			resolveRetirementCallUrl({
				ownerHostUrl: SANDBOX,
				isSandbox: true,
				isAwake: false,
			}),
		).toBeNull();
	});

	it("has nothing to call when the owner did not resolve", () => {
		expect(
			resolveRetirementCallUrl({
				ownerHostUrl: null,
				isSandbox: false,
				isAwake: true,
			}),
		).toBeNull();
	});
});

describe("isCleanupStampCurrent", () => {
	it("allows teardown only while the same cleanup debt is still pending", () => {
		expect(isCleanupStampCurrent(100, 100)).toBe(true);
		expect(isCleanupStampCurrent(100, null)).toBe(false);
		expect(isCleanupStampCurrent(100, 200)).toBe(false);
	});
});

describe("decideCleanupOutcome", () => {
	it("clears the stamp when the owner confirmed and nothing moved underneath", () => {
		expect(
			decideCleanupOutcome({
				stampBefore: 100,
				stampAfter: 100,
				verdict: "confirmed",
			}),
		).toBe("clear");
	});

	it("retries an outage and a disposal failure alike", () => {
		for (const verdict of ["unreachable", "owner-failed"] as const) {
			expect(
				decideCleanupOutcome({ stampBefore: 100, stampAfter: 100, verdict }),
			).toBe("retry");
		}
	});

	it("abandons a confirmation for a cleanup the user cancelled mid-flight", () => {
		expect(
			decideCleanupOutcome({
				stampBefore: 100,
				stampAfter: null,
				verdict: "confirmed",
			}),
		).toBe("abandon");
	});

	it("abandons when the user exited again while the attempt was in flight", () => {
		// Timestamp stability is the whole guard: one exit action reads
		// `Date.now()` once, so a stamp that differs is a DIFFERENT debt this
		// attempt never spoke for.
		expect(
			decideCleanupOutcome({
				stampBefore: 100,
				stampAfter: 200,
				verdict: "confirmed",
			}),
		).toBe("abandon");
	});
});

describe("describeCleanupToast", () => {
	it("says nothing when nothing is owed", () => {
		expect(describeCleanupToast({ blocked: 0, waiting: 0 })).toBeNull();
	});

	it("leads with the fault when both kinds are outstanding", () => {
		expect(describeCleanupToast({ blocked: 1, waiting: 4 })?.title).toBe(
			"Couldn't finish closing 1 workspace",
		);
	});

	it("reads as a wait when only the owner is offline", () => {
		expect(describeCleanupToast({ blocked: 0, waiting: 2 })?.title).toBe(
			"Still closing 2 workspaces",
		);
	});
});

import { toast } from "@superset/ui/sonner";
import { peekConnectionStatus } from "@superset/workspace-client";
import { isNull, not } from "@tanstack/db";
import { useLiveQuery } from "@tanstack/react-db";
import { useCallback, useEffect, useMemo, useRef } from "react";
import { electronTrpc } from "renderer/lib/electron-trpc";
import { getLocalHostServiceUrls } from "renderer/lib/host-service-client";
import {
	decideCleanupOutcome,
	describeCleanupToast,
	isCleanupStampCurrent,
	type RetirementVerdict,
	resolveRetirementCallUrl,
	retireWorkspaceRuntime,
} from "renderer/lib/workspace-exit-cleanup";
import { useCollections } from "renderer/routes/_authenticated/providers/CollectionsProvider";
import { waitForWorkspaceExitPersistence } from "renderer/routes/_authenticated/providers/CollectionsProvider/workspaceExitPersistence";
import { useHostWorkspaces } from "renderer/routes/_authenticated/providers/HostWorkspacesProvider";
import {
	cleanupRoutingKey,
	createSweepQueue,
	localHostFingerprint,
} from "./cleanupTriggers";
import { useHostReopenGeneration } from "./useHostReopenGeneration";

/** One standing toast for the whole feature, so a sweep can't stack five. */
const CLEANUP_TOAST_ID = "workspace-exit-cleanup";

/** Where a pending workspace's retirement call has to be sent. */
interface CleanupTarget {
	/** The owning host's URL, or null while that owner is unreachable. */
	ownerHostUrl: string | null;
	/** The owner is a cloud sandbox: reachable, but never worth waking. */
	isSandbox: boolean;
	/** The workspace's absence from the host lists proves it is gone. */
	absenceAuthoritative: boolean;
}

/**
 * (WORKTREE-EXIT-CLEANUP) Drives the HOST half of exiting a card. Completed,
 * Archive, Snooze and Recycle Bin clear the renderer's tabs and terminals
 * synchronously and stamp `runtimeCleanupPendingAt`; this hook is what turns
 * that stamp into the host call that kills the terminal sessions and releases
 * the workspace's pinned Claude account.
 *
 * Keeping the stamp in persisted local state rather than firing and forgetting
 * is the whole point: the owning machine may be off at the moment the user
 * archives a thread, and the debt has to outlive both that outage and the app.
 * The sweep therefore re-runs on mount (app restart), when a local host-service
 * appears or is replaced, and when an owning host's socket comes back up. The
 * stamp is cleared ONLY when a host that OWNS the workspace reports a clean
 * teardown, or when the workspace is authoritatively gone.
 *
 * One sweep runs at a time. A trigger that lands mid-sweep queues exactly one
 * rerun for after it settles, rather than being dropped as a duplicate — a
 * reconnect arriving while an attempt is still failing against the old socket
 * is precisely the trigger that must not be lost.
 */
export function useWorkspaceExitCleanup(): void {
	const collections = useCollections();
	const utils = electronTrpc.useUtils();
	const { workspaces, cache, isAbsenceAuthoritative } = useHostWorkspaces();
	const { data: connections } =
		electronTrpc.hostServiceCoordinator.getConnections.useQuery();

	const { data: pendingRows = [], isReady } = useLiveQuery(
		(query) =>
			query
				.from({ state: collections.v2WorkspaceLocalState })
				.where(({ state }) =>
					not(isNull(state.sidebarState.runtimeCleanupPendingAt)),
				)
				.select(({ state }) => ({ workspaceId: state.workspaceId })),
		[collections],
	);

	// useLiveQuery hands back a new array every tick; collapse it to a value the
	// effect can compare, or the sweep would re-fire on every unrelated render.
	const pendingKey = pendingRows
		.map((row) => row.workspaceId)
		.sort()
		.join(",");
	const pendingWorkspaceIds = useMemo(
		() => (pendingKey === "" ? [] : pendingKey.split(",")),
		[pendingKey],
	);

	// Where each pending workspace has to be reached, resolved the same way
	// every other cross-host call resolves a host, plus the two things the
	// triggers below read off the same pass. A null URL means the owning host
	// has not resolved — it is offline, or its row has not hydrated — and only
	// the local broadcast can find it.
	const { targets, hasOwnerTarget, routingKey, reopenUrls } = useMemo(() => {
		const resolved = new Map<string, CleanupTarget>();
		const reachable: string[] = [];
		// No debt, no routing to work out — and no reason to walk every workspace
		// the window knows about to find that out.
		if (pendingWorkspaceIds.length === 0) {
			return {
				targets: resolved,
				hasOwnerTarget: false,
				routingKey: "",
				reopenUrls: reachable,
			};
		}
		const hostIds = new Map(
			workspaces.map((workspace) => [workspace.id, workspace.hostId] as const),
		);
		let owned = false;
		for (const workspaceId of pendingWorkspaceIds) {
			const hostId = hostIds.get(workspaceId) ?? null;
			const ownerHostUrl =
				hostId === null ? null : cache.resolveHostUrl(hostId);
			const isSandbox = hostId !== null && cache.isSandboxHost(hostId);
			resolved.set(workspaceId, {
				ownerHostUrl,
				isSandbox,
				// Only asked when no host claims the workspace at all: a row that
				// is absent from every host that answered, with no unanswered host
				// left to be hiding it, is a workspace that no longer exists. The
				// active org is the right scope for that judgement because the
				// collection holding these rows is itself per-org (storage key
				// `v2-workspace-local-state-${organizationId}`), so a pending row
				// can only ever belong to the org this window is in.
				absenceAuthoritative:
					!hostIds.has(workspaceId) && isAbsenceAuthoritative(null),
			});
			if (ownerHostUrl === null) continue;
			owned = true;
			// Sandboxes are deliberately excluded: subscribing holds their VM awake.
			if (!isSandbox) reachable.push(ownerHostUrl);
		}
		return {
			targets: resolved,
			hasOwnerTarget: owned,
			routingKey: cleanupRoutingKey(resolved),
			reopenUrls: reachable,
		};
	}, [pendingWorkspaceIds, workspaces, cache, isAbsenceAuthoritative]);

	// The sweep reads targets through a ref so a Retry click (and a sweep already
	// running) always uses the CURRENT routing rather than whatever was resolved
	// when the toast was raised.
	const targetsRef = useRef(targets);
	targetsRef.current = targets;
	const pendingIdsRef = useRef(pendingWorkspaceIds);
	pendingIdsRef.current = pendingWorkspaceIds;

	// The secret, not just the port: a host-service restart reuses its preferred
	// port and mints a fresh secret, so a ports-only key would miss the one
	// event most likely to make a stuck cleanup work — the local host coming
	// back. The URL is stable across that restart by design.
	const localHostKey = localHostFingerprint(connections);
	const reopenGeneration = useHostReopenGeneration(reopenUrls);

	const sweepRef = useRef<(ids: readonly string[]) => Promise<void>>(
		async () => {},
	);

	const runSweep = useCallback(
		async (workspaceIds: readonly string[]) => {
			// Enumerated once for the whole sweep: the same set of local hosts
			// answers for every workspace in it.
			const localUrlsPromise = getLocalHostServiceUrls(utils);
			const persistedRows = await Promise.all(
				workspaceIds.map(async (workspaceId) => {
					const stampBefore = readCleanupStamp(collections, workspaceId);
					if (stampBefore === null) return null;
					const isPersisted = await waitForWorkspaceExitPersistence(
						collections.activeOrganizationId,
						workspaceId,
						stampBefore,
					);
					return isPersisted ? { workspaceId, stampBefore } : null;
				}),
			);
			const localUrls = await localUrlsPromise;
			if (localUrls === null) {
				console.warn(
					"[workspace-exit-cleanup] could not enumerate local hosts to retire runtime",
					{ workspaceIds },
				);
			}
			const verdicts = new Map<string, RetirementVerdict>();
			await Promise.all(
				persistedRows.map(async (persistedRow) => {
					if (persistedRow === null) return;
					const { workspaceId, stampBefore } = persistedRow;
					if (
						!isCleanupStampCurrent(
							stampBefore,
							readCleanupStamp(collections, workspaceId),
						)
					) {
						return;
					}
					const target = targetsRef.current.get(workspaceId);
					const verdict = await retireWorkspaceRuntime(workspaceId, {
						localUrls: localUrls ?? [],
						// Resolved HERE rather than in the memo above, because whether a
						// sandbox is awake is a live fact: the user may have opened that
						// cloud workspace since the routing was worked out.
						ownerHostUrl:
							target === undefined
								? null
								: resolveRetirementCallUrl({
										ownerHostUrl: target.ownerHostUrl,
										isSandbox: target.isSandbox,
										isAwake: isHostSocketOpen(target.ownerHostUrl),
									}),
						// Only a complete local enumeration can prove absence: a host
						// we never listed is a host that could still own the row.
						absenceAuthoritative:
							localUrls !== null && target?.absenceAuthoritative === true,
					});
					verdicts.set(workspaceId, verdict);
					const outcome = decideCleanupOutcome({
						stampBefore,
						stampAfter: readCleanupStamp(collections, workspaceId),
						verdict,
					});
					if (outcome !== "clear") return;
					collections.v2WorkspaceLocalState.update(workspaceId, (draft) => {
						draft.sidebarState.runtimeCleanupPendingAt = null;
					});
				}),
			);
			showCleanupToast(collections, pendingIdsRef.current, verdicts, () => {
				void sweepRef.current(pendingIdsRef.current);
			});
		},
		[collections, utils],
	);

	// One sweep at a time, with at most one rerun queued behind it. Skipping a
	// trigger outright (the old per-workspace in-flight dedupe) loses exactly the
	// reconnect that arrives while the pre-reconnect attempt is still failing.
	const sweep = useMemo(
		() => createSweepQueue(runSweep, () => pendingIdsRef.current),
		[runSweep],
	);
	sweepRef.current = sweep;

	// No debt, no toast. This is the rule that stops a toast outliving the thing
	// it describes: un-exiting the last failing workspace empties the pending set
	// without any sweep having to complete.
	useEffect(() => {
		if (isReady && pendingWorkspaceIds.length === 0) {
			toast.dismiss(CLEANUP_TOAST_ID);
		}
	}, [isReady, pendingWorkspaceIds]);

	// biome-ignore lint/correctness/useExhaustiveDependencies: reopenGeneration and routingKey are triggers — the sweep reads nothing from either, so an owner's socket coming back (the counter) or a LATER owner resolving to a URL (the key) reaches this effect only through the dependency list
	useEffect(() => {
		if (!isReady || pendingWorkspaceIds.length === 0) return;
		// Nothing is reachable: no local host-service is running and no pending
		// workspace's owner resolved to a URL. Sweeping would only raise a toast
		// about an outage the user can already see; a host arriving changes one of
		// these triggers, which is exactly when the retry should fire.
		if (localHostKey === "" && !hasOwnerTarget) return;
		void sweep(pendingWorkspaceIds);
	}, [
		isReady,
		pendingWorkspaceIds,
		localHostKey,
		reopenGeneration,
		hasOwnerTarget,
		routingKey,
		sweep,
	]);
}

/**
 * (WORKTREE-EXIT-CLEANUP) Raise, replace or dismiss the standing toast from
 * what is STILL owed, read back off the rows rather than from the sweep's own
 * bookkeeping. A sweep may cover a subset (the Retry button re-runs only what
 * failed) and rows can be exited or restored while it runs, so its result set
 * is not the debt — the rows are.
 */
function showCleanupToast(
	collections: ReturnType<typeof useCollections>,
	pendingWorkspaceIds: readonly string[],
	verdicts: ReadonlyMap<string, RetirementVerdict>,
	onRetry: () => void,
): void {
	let blocked = 0;
	let waiting = 0;
	for (const workspaceId of pendingWorkspaceIds) {
		if (readCleanupStamp(collections, workspaceId) === null) continue;
		// A row this sweep never reached is a wait, not a fault.
		if (verdicts.get(workspaceId) === "owner-failed") blocked++;
		else waiting++;
	}
	const content = describeCleanupToast({ blocked, waiting });
	if (content === null) {
		toast.dismiss(CLEANUP_TOAST_ID);
		return;
	}
	toast.error(content.title, {
		id: CLEANUP_TOAST_ID,
		description: content.description,
		duration: Number.POSITIVE_INFINITY,
		action: { label: "Retry", onClick: onRetry },
	});
}

/**
 * Is somebody ALREADY holding this host's socket open? Asked with
 * `peekConnectionStatus`, which never dials — the sweep must not be the thing
 * that wakes a sleeping cloud sandbox.
 */
function isHostSocketOpen(hostUrl: string | null): boolean {
	if (hostUrl === null) return false;
	return peekConnectionStatus(hostUrl)?.state === "open";
}

function readCleanupStamp(
	collections: ReturnType<typeof useCollections>,
	workspaceId: string,
): number | null {
	return (
		collections.v2WorkspaceLocalState.get(workspaceId)?.sidebarState
			.runtimeCleanupPendingAt ?? null
	);
}

export {
	type CleanupVerdict,
	classifyRetirement,
	decideCleanupOutcome,
	describeCleanupToast,
	type HostRetirementOutcome,
	isCleanupStampCurrent,
	type HostRetirementReply,
	type RetirementVerdict,
	resolveRetirementCallUrl,
} from "./cleanupDecisions";
export { retireWorkspaceRuntime } from "./retireWorkspaceRuntime";

import {
	beginLocalCollectionWrite,
	confirmLocalCollectionWrite,
	type PersistableTransaction,
} from "./localCollectionPersistence";

interface PendingAttempt {
	readonly result: Promise<boolean>;
	resolve: (persisted: boolean) => void;
}

interface WorkspaceExitEntry {
	readonly cleanupStamp: number;
	readonly attempts: Set<PendingAttempt>;
	failed: boolean;
}

const pendingExits = new Map<string, WorkspaceExitEntry>();

function validateOrganizationId(organizationId: string): void {
	if (organizationId.length === 0) {
		throw new Error(
			"Cannot persist a workspace exit without an organization ID",
		);
	}
}

function workspaceLocalStateStorageKey(organizationId: string): string {
	validateOrganizationId(organizationId);
	return `v2-workspace-local-state-${organizationId}`;
}

function workspaceExitKey(organizationId: string, workspaceId: string): string {
	validateOrganizationId(organizationId);
	if (workspaceId.length === 0) {
		throw new Error("Cannot persist a workspace exit without a workspace ID");
	}
	return JSON.stringify([organizationId, workspaceId]);
}

function validateCleanupStamp(cleanupStamp: number): void {
	if (!Number.isSafeInteger(cleanupStamp) || cleanupStamp <= 0) {
		throw new Error(
			"Cannot persist a workspace exit with an invalid cleanup stamp",
		);
	}
}

function createAttempt(): PendingAttempt {
	let resolve!: (persisted: boolean) => void;
	const result = new Promise<boolean>((settle) => {
		resolve = settle;
	});
	return { result, resolve };
}

function getOrReplaceEntry(
	key: string,
	cleanupStamp: number,
): WorkspaceExitEntry {
	const existing = pendingExits.get(key);
	if (existing?.cleanupStamp === cleanupStamp) return existing;
	if (existing) {
		for (const attempt of existing.attempts) attempt.resolve(false);
	}
	const entry: WorkspaceExitEntry = {
		cleanupStamp,
		attempts: new Set(),
		failed: false,
	};
	pendingExits.set(key, entry);
	return entry;
}

function finishAttempt(
	key: string,
	entry: WorkspaceExitEntry,
	attempt: PendingAttempt,
	persisted: boolean,
): void {
	entry.attempts.delete(attempt);
	if (!persisted) entry.failed = true;
	attempt.resolve(persisted && !entry.failed);
	if (
		pendingExits.get(key) === entry &&
		entry.attempts.size === 0 &&
		!entry.failed
	) {
		pendingExits.delete(key);
	}
}

export function persistWorkspaceExitMutation(
	organizationId: string,
	workspaceId: string,
	cleanupStamp: number,
	mutate: () => PersistableTransaction,
): Promise<void> {
	validateCleanupStamp(cleanupStamp);
	const key = workspaceExitKey(organizationId, workspaceId);
	const entry = getOrReplaceEntry(key, cleanupStamp);
	const attempt = createAttempt();
	entry.attempts.add(attempt);
	const receipt = beginLocalCollectionWrite(
		workspaceLocalStateStorageKey(organizationId),
	);
	let transaction: PersistableTransaction;
	try {
		transaction = mutate();
	} catch (error) {
		entry.attempts.delete(attempt);
		attempt.resolve(false);
		if (entry.attempts.size === 0 && !entry.failed) pendingExits.delete(key);
		throw error;
	}

	return confirmLocalCollectionWrite(receipt, transaction).then(
		() => {
			finishAttempt(key, entry, attempt, true);
		},
		(error: unknown) => {
			finishAttempt(key, entry, attempt, false);
			throw new Error(`Workspace exit was not saved for ${workspaceId}`, {
				cause: error,
			});
		},
	);
}

export async function waitForWorkspaceExitPersistence(
	organizationId: string,
	workspaceId: string,
	cleanupStamp: number,
): Promise<boolean> {
	validateCleanupStamp(cleanupStamp);
	const key = workspaceExitKey(organizationId, workspaceId);
	while (true) {
		const entry = pendingExits.get(key);
		if (!entry || entry.cleanupStamp !== cleanupStamp) return true;
		if (entry.failed) return false;
		const results = await Promise.all(
			Array.from(entry.attempts, (attempt) => attempt.result),
		);
		if (pendingExits.get(key) !== entry) continue;
		if (entry.failed) return false;
		if (entry.attempts.size > 0) continue;
		return results.every(Boolean);
	}
}

