			const cardStorageKey = kanbanCardsStorageKey(organizationId);
			const exitStorageKey = workspaceLocalStateStorageKey(organizationId);
			const guarded = withQuotaGuard(
				{},
				{
					storage: {
						getItem: () => null,
						removeItem: () => {},
						setItem: () => {
							throw quotaError();
						},
					},
					reclaim: () => 0,

