	// 5. Heal the two-writer pair (KANBAN COMPLETED). Card placement is the
	// single intent signal — complete/uncomplete write the card transaction
	// FIRST, so a crash between the two transactions always converges toward
	// the card's column here:
	//   (a) card in Completed but branch not completed → re-stamp the branch
	//   (b) branch completed but card elsewhere → clear the branch
	for (const card of Array.from(collections.v2KanbanCards.state.values())) {
		if (!card.workspaceId) continue;
		const ws = workspaceById.get(card.workspaceId);
		if (!ws) continue; // frozen record (or pending prune) — nothing to heal
		// (KANBAN HOST SOURCE) Backfill/repair the owner stamp whenever the
		// workspace is visible — legacy rows predate the hostId field.
		if (card.hostId !== ws.hostId) {
			collections.v2KanbanCards.update(card.id, (draft) => {
				draft.hostId = ws.hostId;
			});
		}
		// While a project is removed from the sidebar its local-state rows are
		// deliberately deleted — don't resurrect them from here.
		if (!isKanbanEligibleWorkspace(ws, sidebarProjectIds)) continue;
		const local = localStateByWorkspace.get(card.workspaceId);
		const nowMs = Date.now();
		const bucket = getWorkspaceSidebarBucket(
			local?.sidebarState ?? {},
			nowMs,
			ws.type,
		);
		const isCompletedCard = card.columnId === KANBAN_COMPLETED_COLUMN_ID;
		const needsLifecycleRepair = isCompletedCard
			? bucket !== "hidden" &&
				bucket !== "deleted" &&
				(bucket !== "completed" || card.completedAt == null)
			: bucket === "completed";
		if (!needsLifecycleRepair) continue;

		repairKanbanWorkspaceLifecycle(
			{
				cardId: card.id,
				workspaceId: card.workspaceId,
				isCompletedCard,
				now: nowMs,
			},
			{
				getWorkspaceState: (workspaceId) => {
					const live = collections.v2WorkspaceLocalState.get(workspaceId);
					return {
						bucket: getWorkspaceSidebarBucket(
							live?.sidebarState ?? {},
							Date.now(),
							ws.type,
						),
						completedAt: live?.sidebarState.completedAt ?? null,
					};
				},
				getCardCompletedAt: (cardId) =>
					collections.v2KanbanCards.get(cardId)?.completedAt,
				completeWorkspace: (workspaceId, completedAt) =>
					completeWorkspaceInSidebar(
						collections,
						workspaceRows,
						workspaceId,
						completedAt,
					),
				uncompleteWorkspace: (workspaceId) =>
					uncompleteWorkspaceInSidebar(collections, workspaceId),
				setCardCompletedAt: (cardId, completedAt) => {
					collections.v2KanbanCards.update(cardId, (draft) => {
						draft.completedAt = completedAt;
					});
				},
			},
		);
	}

	// (KANBAN HOST SOURCE) Nothing re-renders on wall-clock alone —
	// steady-state refetches structural-share into identical query data, so
	// an armed missing-clock must schedule its own deadline re-run or a
	// genuinely deleted branch's card would wait forever for an unrelated
	// render before being pruned.
	if (pruneFirstMissingAtRef.current.size > 0) {
		const earliest = Math.min(...pruneFirstMissingAtRef.current.values());
		const delay = Math.max(
			1_000,
			earliest + PRUNE_MISSING_GRACE_MS - Date.now(),
		);
		const timer = window.setTimeout(() => setPruneTick((t) => t + 1), delay);
		return () => window.clearTimeout(timer);
	}
}, [
	isReady,
	collections,
	workspaceRows,
	workspaceById,
	isAbsenceAuthoritative,
	localStateByWorkspace,
	sidebarProjectIds,
	projectNameById,
	columnRows,
	cardRows,
	pruneTick,

