1	import { readFile, stat } from "node:fs/promises";
2	import { join } from "node:path";
3	import type { SlashCommand } from "@superset/shared/slash-commands";
4	import { CLAUDE_BUILTIN_SLASH_COMMANDS } from "../builtins";
5	import type { SlashCommandScanContext } from "../registry";
6	import {
7		dedupeFirstWins,
8		listSkillsDirPlugins,
9		scanCommandDir,
10		scanSkillsDir,
11	} from "../scan-fs";
12	
13	export interface InstalledClaudePlugin {
14		name: string;
15		installPath: string;
16	}
17	
18	/**
19	 * Plugins the Claude CLI has installed, from
20	 * `<configDir>/plugins/installed_plugins.json` (v2 format:
21	 * `{ plugins: { "name@marketplace": [{ installPath, ... }] } }`). Their
22	 * commands and skills surface namespaced as `<plugin>:<name>`. Malformed or
23	 * missing state reads as no plugins; installs whose path is gone are skipped.
24	 */
25	export async function readInstalledClaudePlugins(
26		configDir: string,
27	): Promise<InstalledClaudePlugin[]> {
28		let raw: string;
29		try {
30			raw = await readFile(
31				join(configDir, "plugins", "installed_plugins.json"),
32				"utf-8",
33			);
34		} catch {
35			return [];
36		}
37		let parsed: unknown;
38		try {
39			parsed = JSON.parse(raw);
40		} catch {
41			return [];
42		}
43		const plugins =
44			parsed && typeof parsed === "object"
45				? (parsed as { plugins?: unknown }).plugins
46				: undefined;
47		if (!plugins || typeof plugins !== "object") return [];
48	
49		const installed: InstalledClaudePlugin[] = [];
50		for (const [key, installs] of Object.entries(plugins)) {
51			if (!Array.isArray(installs)) continue;
52			const name = key.split("@")[0];
53			if (!name) continue;
54			const installPath = installs.find(
55				(install): install is { installPath: string } =>
56					install &&
57					typeof install === "object" &&
58					typeof (install as { installPath?: unknown }).installPath === "string",
59			)?.installPath;
60			if (!installPath) continue;
61			try {
62				if (!(await stat(installPath)).isDirectory()) continue;
63			} catch {
64				continue;
65			}
66			installed.push({ name, installPath });
67		}
68		return installed;
69	}
70	
71	/**
72	 * Everything Claude Code offers behind `/` in this workspace: project and
73	 * user commands, project and user skills, and plugin commands and skills —
74	 * both installed plugins and skills-directory plugins whose manifest lives
75	 * inside `skills/`.
76	 */
77	export async function scanClaudeSlashCommands(
78		ctx: SlashCommandScanContext,
79	): Promise<SlashCommand[]> {
80		const [installedPlugins, skillsDirPlugins] = await Promise.all([
81			readInstalledClaudePlugins(ctx.configDir),
82			listSkillsDirPlugins(join(ctx.configDir, "skills")),
83		]);
84		const plugins = [...installedPlugins, ...skillsDirPlugins];
85	
86		const commandScans = [
87			scanCommandDir(join(ctx.worktreePath, ".claude", "commands"), {
88				source: "project",
89				trigger: "/",
90				recursive: true,
91			}),
92			scanCommandDir(join(ctx.configDir, "commands"), {
93				source: "global",
94				trigger: "/",
95				recursive: true,
96			}),
97			...plugins.map((plugin) =>
98				scanCommandDir(join(plugin.installPath, "commands"), {
99					source: "plugin",
100					trigger: "/",
101					recursive: true,
102					namePrefix: `${plugin.name}:`,
103				}),
104			),
