export async function scanCommandDir(
	directory: string,
	options: ScanCommandDirOptions,
): Promise<SlashCommand[]> {
	const commands: SlashCommand[] = [];
	const files = await listMarkdownFilesRecursive(directory, {
		recursive: options.recursive,
	});
