/**
 * Markdown files under `directory`, as sorted relative paths.
 *
 * Symlinked entries are classified with `stat` rather than the dirent: the
 * command dirs in this repo are symlinks into `.agents/`, and a
 * `withFileTypes` walk reports `isDirectory() === false` for a symlinked
 * directory, which is exactly how the legacy registry missed them.
 */
export async function listMarkdownFilesRecursive(
	directory: string,
	options?: { recursive?: boolean },
): Promise<string[]> {
	const recursive = options?.recursive ?? true;
	const files: string[] = [];

	async function visit(relative: string, depth: number): Promise<void> {
		if (files.length >= MAX_SCAN_FILES) return;
		const absolute = relative ? join(directory, relative) : directory;
		let names: string[];
		try {
			names = (await readdir(absolute)).sort((a, b) => a.localeCompare(b));
		} catch {
			return;
		}
		for (const name of names) {
			if (files.length >= MAX_SCAN_FILES) return;
			const entryRelative = relative ? join(relative, name) : name;
			let entryStat: Awaited<ReturnType<typeof stat>>;
			try {
				entryStat = await stat(join(directory, entryRelative));
			} catch {
				continue; // dangling symlink
			}
			if (entryStat.isDirectory()) {
				if (recursive && depth < MAX_SCAN_DEPTH) {
					await visit(entryRelative, depth + 1);
				}
				continue;
			}
			if (entryStat.isFile() && name.endsWith(".md")) {
				files.push(entryRelative);
			}
		}
	}

	await visit("", 0);
	return files;
}

export interface ScanCommandDirOptions {
	source: SlashCommandSource;
	trigger: SlashCommandTrigger;
	recursive: boolean;
	/** Plugin commands surface as `<plugin>:<name>`. */
	namePrefix?: string;
}

/**
 * One `*.md` per command. The name is the relative path minus `.md`, with
 * subdirectories namespacing as `dir:name` — the separator Claude Code itself
 * uses for project command folders and plugins.
 */
export async function scanCommandDir(
	directory: string,
	options: ScanCommandDirOptions,
): Promise<SlashCommand[]> {
	const commands: SlashCommand[] = [];
	const files = await listMarkdownFilesRecursive(directory, {
		recursive: options.recursive,
	});
	for (const file of files) {
		const name =
			(options.namePrefix ?? "") +
			file.replace(/\.md$/, "").split("/").join(":");
		let raw: string;
		try {
			raw = await readFile(join(directory, file), "utf-8");
		} catch (error) {
			console.warn(
				`[agent-tooling] failed to read ${join(directory, file)}:`,
				error,
			);
			continue;
		}
		const metadata = parseSlashCommandFrontmatter(raw);
		commands.push({
			name,
			aliases: metadata.aliases,
			description: metadata.description,
			argumentHint: metadata.argumentHint,
			kind: "custom",
			source: options.source,
			entryKind: "command",
			trigger: options.trigger,
		});
	}
	return commands;
}

export interface ScanSkillsDirOptions {
	source: SlashCommandSource;
	trigger: SlashCommandTrigger;
	/** Plugin skills surface as `<plugin>:<name>`. */
	namePrefix?: string;
}

/** One `<dir>/SKILL.md` per skill; the description comes from frontmatter. */
export async function scanSkillsDir(
	directory: string,
	options: ScanSkillsDirOptions,
): Promise<SlashCommand[]> {
	const skills: SlashCommand[] = [];
	let names: string[];
	try {
		names = (await readdir(directory)).sort((a, b) => a.localeCompare(b));
	} catch {
		return skills;
	}
	for (const name of names) {
		const entryDir = join(directory, name);
		let entryStat: Awaited<ReturnType<typeof stat>>;
		try {
			entryStat = await stat(entryDir);
		} catch {
			continue;
		}
		if (!entryStat.isDirectory()) continue;

		const skill = await readSkill(
			entryDir,
			(options.namePrefix ?? "") + name,
			options,
		);
		if (skill) skills.push(skill);
	}
	return skills;
}

/**
 * Skills-directory plugins inside a Claude `skills/` dir: a child holding a
 * plugin manifest instead of a SKILL.md (e.g. the managed
 * `~/.claude/skills/superset`). Claude Code loads it as a plugin named after
 * the directory, so its commands and skills surface as `<dir>:<name>` — the
 * same shape as an installed plugin, which is how callers should scan it.
 */
export async function listSkillsDirPlugins(
	directory: string,
): Promise<Array<{ name: string; installPath: string }>> {
	const plugins: Array<{ name: string; installPath: string }> = [];
	let names: string[];
	try {
		names = (await readdir(directory)).sort((a, b) => a.localeCompare(b));
	} catch {
		return plugins;
	}
	for (const name of names) {
		const entryDir = join(directory, name);
		try {
			if (!(await stat(entryDir)).isDirectory()) continue;
		} catch {
			continue;
		}
		const hasManifest =
			(await fileExists(join(entryDir, "plugin.json"))) ||
			(await fileExists(join(entryDir, ".claude-plugin", "plugin.json")));
		if (hasManifest) plugins.push({ name, installPath: entryDir });
	}
	return plugins;
}

async function fileExists(path: string): Promise<boolean> {
	try {
		return (await stat(path)).isFile();
	} catch {
		return false;
	}
}

async function readSkill(
	skillDir: string,
	name: string,
	options: Pick<ScanSkillsDirOptions, "source" | "trigger">,
): Promise<SlashCommand | null> {
	let raw: string;
	try {
		raw = await readFile(join(skillDir, "SKILL.md"), "utf-8");
	} catch {
		return null;
	}
	const metadata = parseSlashCommandFrontmatter(raw);
	return {
		name,
		aliases: [],
		description: metadata.description,
		argumentHint: "",
		kind: "custom",
		source: options.source,
		entryKind: "skill",
		trigger: options.trigger,
	};
}

/**
 * First occurrence wins, matching the legacy registry rule: callers scan the
 * project before the config dir, so a project command shadows a global one —
 * and `.claude/commands` symlinked at `.agents/commands` collapses to one
 * entry. Commands and skills may legitimately share a name, so the key spans
 * trigger and entry kind.
 */
export function dedupeFirstWins(commands: SlashCommand[]): SlashCommand[] {
	const seen = new Set<string>();
	const result: SlashCommand[] = [];
	for (const command of commands) {
		const key = `${command.trigger}�${command.entryKind}�${command.name.toLowerCase()}`;
		if (seen.has(key)) continue;
		seen.add(key);
		result.push(command);
	}
	return result;
}

