import { readdir, readFile, stat } from "node:fs/promises";
import { join } from "node:path";
import type {
	SlashCommand,
	SlashCommandSource,
	SlashCommandTrigger,
} from "@superset/shared/slash-commands";
import { parseSlashCommandFrontmatter } from "../frontmatter";

/**
 * Bounds on the recursive command walk. Command trees are tiny in practice
 * (dozens of files); the caps only exist so a pathological directory someone
 * points a config dir at cannot blow the query's 5s budget.
 */
const MAX_SCAN_DEPTH = 5;
const MAX_SCAN_FILES = 500;

/**
 * Markdown files under `directory`, as sorted relative paths.
 *
 * Symlinked entries are classified with `stat` rather than the dirent: the
 * command dirs in this repo are symlinks into `.agents/`, and a
 * `withFileTypes` walk reports `isDirectory() === false` for a symlinked
 * directory, which is exactly how the legacy registry missed them.
 */
export async function listMarkdownFilesRecursive(
	directory: string,
	options?: { recursive?: boolean },
): Promise<string[]> {
	const recursive = options?.recursive ?? true;
	const files: string[] = [];

	async function visit(relative: string, depth: number): Promise<void> {
		if (files.length >= MAX_SCAN_FILES) return;
		const absolute = relative ? join(directory, relative) : directory;
		let names: string[];
		try {
			names = (await readdir(absolute)).sort((a, b) => a.localeCompare(b));
		} catch {
			return;
		}
		for (const name of names) {
			if (files.length >= MAX_SCAN_FILES) return;
			const entryRelative = relative ? join(relative, name) : name;
			let entryStat: Awaited<ReturnType<typeof stat>>;
			try {
				entryStat = await stat(join(directory, entryRelative));
			} catch {
				continue; // dangling symlink
			}
			if (entryStat.isDirectory()) {
				if (recursive && depth < MAX_SCAN_DEPTH) {
					await visit(entryRelative, depth + 1);
				}
				continue;
			}
			if (entryStat.isFile() && name.endsWith(".md")) {
				files.push(entryRelative);
			}
		}
	}

	await visit("", 0);
	return files;
}

export interface ScanCommandDirOptions {
	source: SlashCommandSource;
	trigger: SlashCommandTrigger;
	recursive: boolean;
	/** Plugin commands surface as `<plugin>:<name>`. */
	namePrefix?: string;
}

/**
 * One `*.md` per command. The name is the relative path minus `.md`, with
 * subdirectories namespacing as `dir:name` — the separator Claude Code itself
 * uses for project command folders and plugins.
 */
export async function scanCommandDir(
	directory: string,
	options: ScanCommandDirOptions,
): Promise<SlashCommand[]> {
	const commands: SlashCommand[] = [];
	const files = await listMarkdownFilesRecursive(directory, {
		recursive: options.recursive,
	});
	for (const file of files) {
		const name =
			(options.namePrefix ?? "") +
			file.replace(/\.md$/, "").split(/[\\/]/).join(":");
		let raw: string;
		try {
			raw = await readFile(join(directory, file), "utf-8");
		} catch (error) {
			console.warn(
				`[agent-tooling] failed to read ${join(directory, file)}:`,
				error,
			);
			continue;
		}
		const metadata = parseSlashCommandFrontmatter(raw);
		commands.push({
			name,
			aliases: metadata.aliases,
			description: metadata.description,
			argumentHint: metadata.argumentHint,
			kind: "custom",
			source: options.source,
			entryKind: "command",
			trigger: options.trigger,
		});
	}
	return commands;
}

export interface ScanSkillsDirOptions {
	source: SlashCommandSource;
	trigger: SlashCommandTrigger;
	/** Plugin skills surface as `<plugin>:<name>`. */
	namePrefix?: string;
}

/** One `<dir>/SKILL.md` per skill; the description comes from frontmatter. */
export async function scanSkillsDir(
	directory: string,
	options: ScanSkillsDirOptions,
): Promise<SlashCommand[]> {
	const skills: SlashCommand[] = [];
	let names: string[];
	try {
		names = (await readdir(directory)).sort((a, b) => a.localeCompare(b));
	} catch {
		return skills;
	}
	for (const name of names) {
		const entryDir = join(directory, name);
		let entryStat: Awaited<ReturnType<typeof stat>>;
		try {
			entryStat = await stat(entryDir);
		} catch {
			continue;
		}
		if (!entryStat.isDirectory()) continue;

		const skill = await readSkill(
			entryDir,
			(options.namePrefix ?? "") + name,
			options,
		);
		if (skill) skills.push(skill);
	}
	return skills;
}

/**
 * Skills-directory plugins inside a Claude `skills/` dir: a child holding a
 * plugin manifest instead of a SKILL.md (e.g. the managed
 * `~/.claude/skills/superset`). Claude Code loads it as a plugin named after
 * the directory, so its commands and skills surface as `<dir>:<name>` — the
 * same shape as an installed plugin, which is how callers should scan it.
 */
export async function listSkillsDirPlugins(
	directory: string,
): Promise<Array<{ name: string; installPath: string }>> {
	const plugins: Array<{ name: string; installPath: string }> = [];
	let names: string[];
	try {
		names = (await readdir(directory)).sort((a, b) => a.localeCompare(b));
	} catch {
		return plugins;
	}
	for (const name of names) {
		const entryDir = join(directory, name);
		try {
			if (!(await stat(entryDir)).isDirectory()) continue;
		} catch {
			continue;
		}
		const hasManifest =
			(await fileExists(join(entryDir, "plugin.json"))) ||
			(await fileExists(join(entryDir, ".claude-plugin", "plugin.json")));
		if (hasManifest) plugins.push({ name, installPath: entryDir });
	}
	return plugins;
}

async function fileExists(path: string): Promise<boolean> {
	try {
		return (await stat(path)).isFile();
	} catch {
		return false;
	}
}

async function readSkill(
	skillDir: string,
	name: string,
	options: Pick<ScanSkillsDirOptions, "source" | "trigger">,
): Promise<SlashCommand | null> {
	let raw: string;
	try {
		raw = await readFile(join(skillDir, "SKILL.md"), "utf-8");
	} catch {
		return null;
	}
	const metadata = parseSlashCommandFrontmatter(raw);
	return {
		name,
		aliases: [],
		description: metadata.description,
		argumentHint: "",
		kind: "custom",
		source: options.source,
		entryKind: "skill",
		trigger: options.trigger,
	};
}

/**
 * First occurrence wins, matching the legacy registry rule: callers scan the
 * project before the config dir, so a project command shadows a global one —
 * and `.claude/commands` symlinked at `.agents/commands` collapses to one
 * entry. Commands and skills may legitimately share a name, so the key spans
 * trigger and entry kind.
 */
export function dedupeFirstWins(commands: SlashCommand[]): SlashCommand[] {
	const seen = new Set<string>();
	const result: SlashCommand[] = [];
	for (const command of commands) {
		const key = `${command.trigger}�${command.entryKind}�${command.name.toLowerCase()}`;
		if (seen.has(key)) continue;
		seen.add(key);
		result.push(command);
	}
	return result;
}

import { describe, expect, it } from "bun:test";
import {
	type KanbanWorkspaceLifecycleActions,
	type KanbanWorkspaceLifecycleSnapshot,
	repairKanbanWorkspaceLifecycle,
} from "./repairWorkspaceLifecycle";

const BASE_SNAPSHOT: KanbanWorkspaceLifecycleSnapshot = {
	cardId: "card-1",
	workspaceId: "workspace-1",
	isCompletedCard: true,
	now: 999,
};

interface LiveState {
	workspaceBucket: string;
	workspaceCompletedAt: number | null;
	cardCompletedAt: number | null | undefined;
}

function makeActions(
	calls: string[],
	overrides: Partial<LiveState> = {},
): KanbanWorkspaceLifecycleActions {
	const live: LiveState = {
		workspaceBucket: "active",
		workspaceCompletedAt: null,
		cardCompletedAt: 123,
		...overrides,
	};
	return {
		getWorkspaceState: () => ({
			bucket: live.workspaceBucket,
			completedAt: live.workspaceCompletedAt,
		}),
		getCardCompletedAt: () => live.cardCompletedAt,
		completeWorkspace: (cardId, workspaceId, completedAt) => {
			calls.push(`complete:${cardId}:${workspaceId}:${completedAt}`);
			live.cardCompletedAt = completedAt;
			live.workspaceBucket = "completed";
			live.workspaceCompletedAt = completedAt;
		},
		uncompleteWorkspace: (workspaceId) => {
			calls.push(`uncomplete:${workspaceId}`);
			live.workspaceBucket = "active";
			live.workspaceCompletedAt = null;
		},
		setCardCompletedAt: (cardId, completedAt) => {
			calls.push(`stamp:${cardId}:${completedAt}`);
			live.cardCompletedAt = completedAt;
		},
	};
}

describe("repairKanbanWorkspaceLifecycle", () => {
	it("routes a partially completed card through the full completion lifecycle", () => {
		const calls: string[] = [];

		repairKanbanWorkspaceLifecycle(BASE_SNAPSHOT, makeActions(calls));

		expect(calls).toEqual(["complete:card-1:workspace-1:123"]);
	});

	it("uses one timestamp for the card intent and workspace completion", () => {
		const calls: string[] = [];

		repairKanbanWorkspaceLifecycle(
			BASE_SNAPSHOT,
			makeActions(calls, { cardCompletedAt: null }),
		);

		expect(calls).toEqual(["complete:card-1:workspace-1:999"]);
	});

	it("routes a card moved out of Completed through uncompletion", () => {
		const calls: string[] = [];

		repairKanbanWorkspaceLifecycle(
			{ ...BASE_SNAPSHOT, isCompletedCard: false },
			makeActions(calls, {
				workspaceBucket: "completed",
				workspaceCompletedAt: 123,
			}),
		);

		expect(calls).toEqual(["uncomplete:workspace-1"]);
	});

	it("fills a missing card timestamp without repeating workspace cleanup", () => {
		const calls: string[] = [];

		repairKanbanWorkspaceLifecycle(
			BASE_SNAPSHOT,
			makeActions(calls, {
				workspaceBucket: "completed",
				workspaceCompletedAt: 456,
				cardCompletedAt: null,
			}),
		);

		expect(calls).toEqual(["stamp:card-1:456"]);
	});

	it("does not repeat lifecycle work after another reconciler repaired it", () => {
		const calls: string[] = [];
		const actions = makeActions(calls, { cardCompletedAt: null });

		repairKanbanWorkspaceLifecycle(BASE_SNAPSHOT, actions);
		repairKanbanWorkspaceLifecycle(BASE_SNAPSHOT, actions);

		expect(calls).toEqual(["complete:card-1:workspace-1:999"]);
	});

	it("does not turn a hidden or deleted workspace into Completed", () => {
		for (const workspaceBucket of ["hidden", "deleted"]) {
			const calls: string[] = [];

			repairKanbanWorkspaceLifecycle(
				BASE_SNAPSHOT,
				makeActions(calls, { workspaceBucket }),
			);

			expect(calls).toEqual([]);
		}
	});
});

export interface KanbanWorkspaceLifecycleSnapshot {
	cardId: string;
	workspaceId: string;
	isCompletedCard: boolean;
	now: number;
}

export interface KanbanWorkspaceLifecycleState {
	bucket: string;
	completedAt: number | null;
}

export interface KanbanWorkspaceLifecycleActions {
	getWorkspaceState: (workspaceId: string) => KanbanWorkspaceLifecycleState;
	getCardCompletedAt: (cardId: string) => number | null | undefined;
	completeWorkspace: (
		cardId: string,
		workspaceId: string,
		completedAt: number,
	) => void;
	uncompleteWorkspace: (workspaceId: string) => void;
	setCardCompletedAt: (cardId: string, completedAt: number) => void;
}

/**
 * Repairs a bound card after a prior multi-collection update stopped halfway.
 * The sidebar lifecycle commands own every runtime cleanup invariant; this
 * reconciler reads live state so two mounted reconcilers cannot repeat a repair.
 */
export function repairKanbanWorkspaceLifecycle(
	snapshot: KanbanWorkspaceLifecycleSnapshot,
	actions: KanbanWorkspaceLifecycleActions,
): void {
	const workspace = actions.getWorkspaceState(snapshot.workspaceId);
	const cardCompletedAt = actions.getCardCompletedAt(snapshot.cardId);

	if (snapshot.isCompletedCard) {
		if (workspace.bucket === "hidden" || workspace.bucket === "deleted") return;

		if (workspace.bucket !== "completed") {
			const completedAt = cardCompletedAt ?? snapshot.now;
			actions.completeWorkspace(
				snapshot.cardId,
				snapshot.workspaceId,
				completedAt,
			);
			return;
		}

		if (cardCompletedAt == null) {
			actions.setCardCompletedAt(
				snapshot.cardId,
				workspace.completedAt ?? snapshot.now,
			);
		}
		return;
	}

	if (workspace.bucket === "completed") {
		actions.uncompleteWorkspace(snapshot.workspaceId);
	}
}

