862			// And B is still reportable: opening the chat again names B, not A.
863			autoAcceptSeen = true;
864			startsWorking(8_000);
865			markTerminalSeenAndReportRead({
866				workspaceId: WORKSPACE,
867				terminalId: TERMINAL,
868				lastEventAt: 8_000,
869			});
870			await settle();
871			expect(seenCalls).toHaveLength(2);
872			expect(seenCalls[1]).toMatchObject({ seenThroughAt: 7_000 });
873			expect(
874				useV2NotificationStore.getState().outstandingReadyAt[TERMINAL],
875			).toBeUndefined();
876		});
877	});
878	
879	// --- (ALERT-RETIRE-ON-EXIT) the relaunch boundary ---------------------------
880	
881	/**
882	 * (ALERT-RETIRE-ON-EXIT) The boundary is a ONCE-PER-LAUNCH statement, and the
883	 * latch is what keeps it one. Everything here is about that latch: what sets
884	 * it, what must not, and what a report the host refused leaves behind.
885	 */
886	describe("(ALERT-RETIRE-ON-EXIT) reportRelaunchBoundary", () => {
887		it("sends the boundary and answers true on acceptance", async () => {
888			await expect(
889				reportRelaunchBoundary({ hostUrl: HOST, boundaryMs: 1_700_000_000_000 }),
890			).resolves.toBe(true);
891			expect(relaunchCalls).toHaveLength(1);
892			expect(relaunchCalls[0]?.boundaryMs).toBe(1_700_000_000_000);
893		});
894	
895		it("says nothing a second time — the host already took this launch", async () => {
896			await reportRelaunchBoundary({
897				hostUrl: HOST,
898				boundaryMs: 1_700_000_000_000,
899			});
900			await expect(
901				reportRelaunchBoundary({ hostUrl: HOST, boundaryMs: 1_700_000_000_000 }),
902			).resolves.toBe(false);
903			expect(relaunchCalls).toHaveLength(1);
904		});
905	
906		it("RETRIES after a host that refused it", async () => {
907			autoAcceptRelaunch = false;
908			await expect(
909				reportRelaunchBoundary({ hostUrl: HOST, boundaryMs: 1_700_000_000_000 }),
910			).resolves.toBe(false);
911	
912			autoAcceptRelaunch = true;
913			await expect(
914				reportRelaunchBoundary({ hostUrl: HOST, boundaryMs: 1_700_000_000_000 }),
915			).resolves.toBe(true);
916			expect(relaunchCalls).toHaveLength(2);
917		});
918	
919		it("never rejects when the transport throws, and retries after", async () => {
920			relaunchThrows = true;
921			await expect(
922				reportRelaunchBoundary({ hostUrl: HOST, boundaryMs: 1_700_000_000_000 }),
923			).resolves.toBe(false);
924	
925			relaunchThrows = false;
926			await expect(
927				reportRelaunchBoundary({ hostUrl: HOST, boundaryMs: 1_700_000_000_000 }),
928			).resolves.toBe(true);
929			expect(relaunchCalls).toHaveLength(2);
930		});
931	
932		it("refuses a non-integer boundary without touching the wire", async () => {
933			await expect(
934				reportRelaunchBoundary({
935					hostUrl: HOST,
936					boundaryMs: 1_700_000_000_000.7,
937				}),
938			).resolves.toBe(false);
939			await expect(
940				reportRelaunchBoundary({ hostUrl: HOST, boundaryMs: 0 }),
941			).resolves.toBe(false);
942			await expect(
943				reportRelaunchBoundary({ hostUrl: HOST, boundaryMs: -1 }),
944			).resolves.toBe(false);
945			await expect(
946				reportRelaunchBoundary({ hostUrl: HOST, boundaryMs: Number.NaN }),
947			).resolves.toBe(false);
948			await expect(
949				reportRelaunchBoundary({
950					hostUrl: HOST,
951					boundaryMs: Number.POSITIVE_INFINITY,
952				}),
953			).resolves.toBe(false);
954			expect(relaunchCalls).toHaveLength(0);
955			// And a refusal is not a latch: the real boundary still goes.
956			await expect(
957				reportRelaunchBoundary({ hostUrl: HOST, boundaryMs: 1_700_000_000_000 }),
958			).resolves.toBe(true);
959		});
960	
961		it("latches PER HOST", async () => {
962			await reportRelaunchBoundary({ hostUrl: HOST, boundaryMs: 1_000 });
963			await expect(
964				reportRelaunchBoundary({ hostUrl: "http://host-b", boundaryMs: 1_000 }),
965			).resolves.toBe(true);
966			expect(relaunchCalls).toHaveLength(2);
967		});
968	
969		it("survives a host RECONNECT — a reconnect is not a new launch", async () => {
970			await reportRelaunchBoundary({ hostUrl: HOST, boundaryMs: 1_000 });
971			// The reconnect repair drops the tab-context memory for this host. The
972			// launch boundary is NOT part of that memory: the app did not relaunch.
973			forgetAlertContextSyncsForHost(HOST);
974			await expect(
975				reportRelaunchBoundary({ hostUrl: HOST, boundaryMs: 1_000 }),
976			).resolves.toBe(false);
977			expect(relaunchCalls).toHaveLength(1);
978		});
979	});
