1	/**
2	 * (MASTER-PLUS-LAUNCH) A session created AFTER the terminal list has settled
3	 * still has to get a pane.
4	 *
5	 * The hook's own `isFetching` gate only covers the mount-time race: on open,
6	 * the list is refetching and the effect waits for it. Once it has settled,
7	 * nothing re-runs — a session minted later by the CLI or `agents.run` changes
8	 * no query input, so before the lifecycle subscription it simply never
9	 * appeared. What is asserted here is that wiring end to end: an empty settled
10	 * list, a `terminal:lifecycle` event, the invalidate it triggers, and the pane
11	 * that follows once the refetched list lands.
12	 *
13	 * The event doing the work is the host's `created` eventType, and ONLY that
14	 * one: the command markers fire on every shell command the user runs, and
15	 * refetching the session list for each of them is a daemon round trip plus a
16	 * re-render for nothing. The host side — that a create actually broadcasts
17	 * `created` — is asserted in
18	 * `packages/host-service/src/terminal/terminal.created-event.test.ts`.
19	 */
20	
21	import {
22		afterAll,
23		afterEach,
24		beforeEach,
25		describe,
26		expect,
27		it,
28		mock,
29	} from "bun:test";
30	import { GlobalRegistrator } from "@happy-dom/global-registrator";
31	import type { TerminalLifecyclePayload } from "@superset/workspace-client";
32	import type { PaneViewerData } from "../../types";
33	
34	// happy-dom over the preloaded plain-object document — this renders a real
35	// component tree. Bun runs test files sequentially in one process and
36	// happy-dom's globals are process-wide, so we MUST unregister in afterAll or
37	// unrelated renderer suites inherit readonly DOM globals.
38	const alreadyRegistered = GlobalRegistrator.isRegistered;
39	if (!alreadyRegistered) GlobalRegistrator.register();
40	(
41		globalThis as { IS_REACT_ACT_ENVIRONMENT?: boolean }
42	).IS_REACT_ACT_ENVIRONMENT = true;
43	
44	interface SessionLike {
45		terminalId: string;
46		workspaceId: string;
47		createdAt: number;
48	}
49	
50	interface EventSubscription {
51		type: string;
52		workspaceId: string;
53		callback: (payload: TerminalLifecyclePayload) => void;
54		enabled: boolean;
55	}
56	
57	let sessions: SessionLike[] | undefined;
58	let isFetching = false;
59	let invalidateCalls: Array<{ workspaceId: string }> = [];
60	let subscriptions: EventSubscription[] = [];
61	
62	/**
63	 * `mock.module` is PROCESS-GLOBAL and there is no unmock, so each stub here
64	 * outlives this file. Both are the REAL module with a single export
65	 * overridden, so a module that later grows an export does not silently lose
66	 * it for whatever bun runs next. `workspaceTrpc` is a tRPC proxy that cannot
67	 * be spread, so it is replaced wholesale — only the two members this hook
68	 * touches exist on it.
69	 */
70	const realWorkspaceClient = await import("@superset/workspace-client");
71	const realUseWorkspaceEvent = await import(
72		"renderer/hooks/host-service/useWorkspaceEvent"
73	);
74	
75	function installMocks(): void {
76		mock.module("@superset/workspace-client", () => ({
77			...realWorkspaceClient,
78			workspaceTrpc: {
79				terminal: {
80					list: {
81						useQuery: () => ({
82							data: sessions ? { sessions } : undefined,
83							isFetching,
84						}),
85					},
86				},
87				useUtils: () => ({
88					terminal: {
89						list: {
90							invalidate: (input: { workspaceId: string }) => {
91								invalidateCalls.push(input);
92								return Promise.resolve();
93							},
94						},
95					},
96				}),
97			},
98		}));
99	
100		// The real hook resolves the workspace's host through the auth/cloud
101		// provider tree, which no unit harness has. Recording the subscription is
102		// what this test needs from it anyway.
103		mock.module("renderer/hooks/host-service/useWorkspaceEvent", () => ({
104			...realUseWorkspaceEvent,
105			useWorkspaceEvent: (
106				type: string,
107				workspaceId: string,
108				callback: (payload: TerminalLifecyclePayload) => void,
109				enabled = true,
110			) => {
111				const existing = subscriptions.find(
112					(entry) => entry.type === type && entry.workspaceId === workspaceId,
113				);
114				if (existing) {
115					existing.callback = callback;
116					existing.enabled = enabled;
117					return;
118				}
119				subscriptions.push({ type, workspaceId, callback, enabled });
120			},
121		}));
122	}
123	
124	installMocks();
125	
126	const { act, cleanup, render } = await import("@testing-library/react");
127	const React = await import("react");
128	const { createWorkspaceStore } = await import("@superset/panes");
129	const { useAutoAdoptBackgroundSessions } = await import(
130		"./useAutoAdoptBackgroundSessions"
131	);
132	
133	const WORKSPACE_ID = "workspace-1";
134	
135	type Store = ReturnType<typeof createWorkspaceStore<PaneViewerData>>;
136	
137	function createStore(): Store {
138		return createWorkspaceStore<PaneViewerData>({
139			initialState: { version: 1, tabs: [], activeTabId: null },
140		});
141	}
142	
143	function Probe({
144		store,
145		isLayoutReady,
146		isExitCleanupPending = false,
147	}: {
148		store: Store;
149		isLayoutReady: boolean;
150		isExitCleanupPending?: boolean;
151	}) {
152		useAutoAdoptBackgroundSessions({
153			store,
154			workspaceId: WORKSPACE_ID,
155			isLayoutReady,
156			isExitCleanupPending,
157		});
158		return null;
159	}
160	
161	function mount(
162		store: Store,
163		isLayoutReady = true,
164		isExitCleanupPending = false,
165	) {
166		return render(
167			React.createElement(Probe, { store, isLayoutReady, isExitCleanupPending }),
168		);
169	}
170	
171	/** Terminal ids of every terminal pane currently in the store. */
172	function panedTerminalIds(store: Store): string[] {
173		const ids: string[] = [];
174		for (const tab of store.getState().tabs) {
175			for (const pane of Object.values(tab.panes)) {
176				if (pane.kind !== "terminal") continue;
177				const terminalId = (pane.data as { terminalId?: string } | undefined)
178					?.terminalId;
179				if (terminalId) ids.push(terminalId);
180			}
181		}
182		return ids;
183	}
184	
185	/** Delivers a `terminal:lifecycle` event the way the host event bus would. */
186	function fireTerminalLifecycle(
187		payload: TerminalLifecyclePayload = {
188			eventType: "created",
189			terminalId: "terminal-1",
190			adopted: false,
191			occurredAt: 1,
192		},
193	): void {
194		const subscription = subscriptions.find(
195			(entry) => entry.type === "terminal:lifecycle",
196		);
197		if (!subscription) throw new Error("no terminal:lifecycle subscription");
198		if (!subscription.enabled) return;
199		act(() => {
200			subscription.callback(payload);
201		});
202	}
203	
204	describe("(MASTER-PLUS-LAUNCH) useAutoAdoptBackgroundSessions lifecycle refetch", () => {
205		beforeEach(() => {
206			sessions = [];
207			isFetching = false;
208			invalidateCalls = [];
209			subscriptions = [];
210			installMocks();
211		});
212	
213		afterEach(() => {
214			cleanup();
215		});
216	
217		afterAll(async () => {
218			if (!alreadyRegistered) await GlobalRegistrator.unregister();
219		});
220	
221		it("adopts a session that lands after the list has already settled", async () => {
222			const store = createStore();
223			const view = mount(store);
224	
225			// Settled and empty: nothing to adopt, and no further query change is
226			// coming on its own.
227			expect(panedTerminalIds(store)).toEqual([]);
228			expect(invalidateCalls).toEqual([]);
229	
230			// The host announces the CLI-created session.
231			fireTerminalLifecycle();
232			expect(invalidateCalls).toEqual([{ workspaceId: WORKSPACE_ID }]);
233	
234			// The refetch that invalidate triggered lands.
235			sessions = [
236				{ terminalId: "terminal-1", workspaceId: WORKSPACE_ID, createdAt: 1 },
237			];
238			await act(async () => {
239				view.rerender(React.createElement(Probe, { store, isLayoutReady: true }));
240			});
241	
242			expect(panedTerminalIds(store)).toEqual(["terminal-1"]);
243		});
244	
245		it("ignores command markers — only a create is worth a refetch", () => {
246			const store = createStore();
247			mount(store);
248	
249			fireTerminalLifecycle({
250				eventType: "command-start",
251				terminalId: "terminal-1",
252				occurredAt: 2,
253			});
254			fireTerminalLifecycle({
255				eventType: "command-end",
256				terminalId: "terminal-1",
257				exitCode: 0,
258				occurredAt: 3,
259			});
260	
261			expect(invalidateCalls).toEqual([]);
262		});
263	
264		it("subscribes for this workspace only once the pane layout is ready", () => {
265			const store = createStore();
266			mount(store, false);
267	
268			const subscription = subscriptions.find(
269				(entry) => entry.type === "terminal:lifecycle",
270			);
271			expect(subscription?.workspaceId).toBe(WORKSPACE_ID);
272			expect(subscription?.enabled).toBe(false);
273		});
274	
275		it("does not adopt while the list is still refetching", async () => {
276			const store = createStore();
277			isFetching = true;
278			sessions = [
279				{ terminalId: "terminal-stale", workspaceId: WORKSPACE_ID, createdAt: 1 },
280			];
281			mount(store);
282	
283			expect(panedTerminalIds(store)).toEqual([]);
284		});
285	
286		it("re-adopting an already-paned session adds no second pane", async () => {
287			const store = createStore();
288			sessions = [
289				{ terminalId: "terminal-1", workspaceId: WORKSPACE_ID, createdAt: 1 },
290			];
291			const view = mount(store);
292			expect(panedTerminalIds(store)).toEqual(["terminal-1"]);
293	
294			fireTerminalLifecycle();
295			await act(async () => {
296				view.rerender(React.createElement(Probe, { store, isLayoutReady: true }));
297			});
298	
299			expect(panedTerminalIds(store)).toEqual(["terminal-1"]);
300		});
301	
302		it("(WORKTREE-EXIT-CLEANUP) does not adopt a workspace whose exit cleanup is pending", () => {
303			const store = createStore();
304			sessions = [
305				{
306					terminalId: "terminal-exited",
307					workspaceId: WORKSPACE_ID,
