26	 *
27	 * `seenAtReport` is the seeded seen mark for `terminal-1` AS THE REPORT WENT
28	 * OUT. The host answers this report by retracting pre-launch ready cards, so
29	 * the ordering it pins is a safety property, not a detail: the report may only
30	 * leave after the reconciliation that took those finishes over.
31	 */
32	let relaunchCalls: Array<{
33		hostUrl: string;
34		boundaryMs: number;
35		seenAtReport: number | undefined;
36	}> = [];
37	let acceptSeen = true;
38	/** (ALERT-RETIRE-ON-EXIT) What the host answers a relaunch boundary with. */
39	let acceptRelaunch = true;
40	let rejectSeen = false;
41	let snapshotRows: SnapshotRow[] = [];
42	let knownTerminalIds: string[] = [];
43	let hostNow: number | undefined = 10_000;
