53	mock.module("renderer/lib/host-service-client", () => ({
54		// The module is replaced whole. Without the query-policy helpers other
55		// importers in this graph pull from it, running this file ON ITS OWN dies
56		// with "Export named 'hostServiceQueryRetryDelay' not found" before a single
57		// test executes.
58		getHostServiceClient: () => ({}),
59		isHostServiceConnectionError: () => false,
60		hostServiceQueryRetry: () => false,
61		hostServiceQueryRetryDelay: () => 0,
62		getHostServiceClientByUrl: (hostUrl: string) => ({
63			notifications: {
