65					query: async () => ({
66						rows: snapshotRows,
67						knownTerminalIds,
68						hostNow,
69					}),
70				},
71			},
72			companion: {
73				markLifecycleSeen: {
74					mutate: async (input: SeenCall) => {
75						seenCalls.push(input);
76						if (rejectSeen) throw new Error("host gone");
77						return { accepted: acceptSeen };
78					},
79				},
80				syncAlertContexts: {
81					mutate: async () => ({ accepted: true }),
82				},
