84					mutate: async (input: { boundaryMs: number }) => {
85						relaunchCalls.push({
86							hostUrl,
87							boundaryMs: input.boundaryMs,
88							seenAtReport:
89								useV2NotificationStore.getState().terminalSeenAt["terminal-1"],
90						});
91						return { accepted: acceptRelaunch };
92					},
93				},
94			},
95		}),
96	}));
