412		it("DOES re-report the same terminal for a NEWER finish", async () => {
413			// The finish's instant is part of the cooldown key. Keyed per terminal
414			// alone, a finish repaired at 09:00 suppressed the 09:20 one for the rest
415			// of the half hour, and the phone held an alert for a chat the user had
416			// already read with nothing left to take it down.
417			seenThrough("terminal-1", 5_000);
418			await resyncAgentStatusFromHost({
419				hostUrl: HOST,
420				workspaces: workspaces(),
421			});
422			await settle();
423			expect(seenCalls).toHaveLength(1);
424	
425			seenCalls = [];
426			snapshotRows = [row({ lastEventAt: 7_000 })];
427			seenThrough("terminal-1", 7_000);
428			const result = await resyncAgentStatusFromHost({
