444	describe("(ALERT-CONTEXT-NAMES) resync companion repair — failure is not repair", () => {
445		it("records an ACCEPTED report under the long repair cooldown", async () => {
446			seenThrough("terminal-1", 5_000);
447			await resyncAgentStatusFromHost({
448				hostUrl: HOST,
449				workspaces: workspaces(),
450			});
451			await settle();
