471		it("records a REJECTED report under the short retry cooldown too", async () => {
472			rejectSeen = true;
473			seenThrough("terminal-1", 5_000);
474			await resyncAgentStatusFromHost({
475				hostUrl: HOST,
476				workspaces: workspaces(),
477			});
478			await settle();
479			expect(__peekRepairOutcomeForTest(`${HOST}:terminal-1:5000`)).toBe("failed");
480		});
481	
482		it("keys the cooldown per HOST, so two hosts' terminals are separate subjects", async () => {
483			seenThrough("terminal-1", 5_000);
484			await resyncAgentStatusFromHost({
485				hostUrl: HOST,
486				workspaces: workspaces(),
487			});
488			await settle();
489			expect(__peekRepairOutcomeForTest(`${HOST}:terminal-1:5000`)).not.toBeNull();
490			expect(
491				__peekRepairOutcomeForTest("http://host-b:terminal-1:5000"),
492			).toBeNull();
493		});
494	});
495	/**
496	 * (MANUAL-DISMISS) `pendingPermission: false` — the answer the loop used to
497	 * throw away.
498	 *
499	 * The host reads its marker directory and gives one of three answers: a
500	 * question is pending, none is, or it could not tell. Only the first two were
501	 * ever acted on, and "none is" is the retraction half: a red latched from a
502	 * question whose answer arrived while the bus was down, or one the user has
503	 * since dismissed, was RE-CONFIRMED by every resync instead of being taken
504	 * down by it. The replayed `lastEventType` cannot do the job — a turn-end
505	 * carries no answer-evidence and deliberately leaves the permission axis alone.
506	 */
507	describe("(MANUAL-DISMISS) pendingPermission: false retracts a latched red", () => {
508		const source = { type: "terminal", id: "terminal-1" } as const;
509	
510		function latchRed(workspaceId: string, at: number): void {
511			useV2NotificationStore
512				.getState()
513				.applySourceAxes(
514					source,
515					workspaceId,
516					{ set: ["permission"], clear: [] },
517					at,
518				);
519		}
520	
521		it("clears the permission axis the host says nothing backs", async () => {
522			latchRed(WORKSPACE, 1_000);
523			snapshotRows = [row({ lastEventAt: 5_000, pendingPermission: false })];
524	
525			const result = await resyncAgentStatusFromHost({
526				hostUrl: HOST,
527				workspaces: workspaces(),
528			});
529			await settle();
530	
531			const entry =
532				useV2NotificationStore.getState().sources["terminal:terminal-1"];
533			expect(entry?.axes.permission).toBeUndefined();
534			expect(entry?.status).not.toBe("permission");
535			expect(result?.retractedPermission).toBe(1);
536		});
537	
538		/**
539		 * THE INVARIANT: NO AUTOMATIC PATH DROPS A LIVE RED.
540		 *
541		 * `pendingPermission: false` means "no marker file", and a marker is only
542		 * ever written for `PreToolUse:AskUserQuestion`. An ordinary tool-permission
543		 * prompt (Claude's `Notification` event on the "permission_prompt" matcher,
544		 * and the same shape from the sh-template agents) latches its red with a
545		 * `PermissionRequest` binding and NO marker, so "no marker" says nothing
546		 * about it — yet the periodic resync replayed the row, read `false` as an
547		 * answer, and took the dot down while the prompt was still on screen blocking
548		 * the agent. The occurredAt fence does not catch it: row and latch carry the
549		 * SAME instant, and `5_000 > 5_000` is false.
550		 */
551		it("does NOT retract while the host's own last word is a PermissionRequest", async () => {
552			latchRed(WORKSPACE, 5_000);
553			snapshotRows = [
554				row({
555					lastEventType: "PermissionRequest",
556					lastEventAt: 5_000,
557					pendingPermission: false,
558				}),
559			];
560	
561			const result = await resyncAgentStatusFromHost({
562				hostUrl: HOST,
563				workspaces: workspaces(),
564			});
565			await settle();
566	
567			const entry =
568				useV2NotificationStore.getState().sources["terminal:terminal-1"];
569			expect(entry?.axes.permission).toBe(5_000);
570			expect(entry?.status).toBe("permission");
571			expect(result?.retractedPermission).toBe(0);
572		});
573	
574		/**
575		 * Same fence the unknown branch carries: an entry belonging to another
576		 * workspace is not this row's dot to retract. (Whatever the replay itself
577		 * does with a cross-workspace entry is the replay's business; the counter is
578		 * the honest witness for this branch.)
579		 */
580		it("does not retract an entry belonging to a different workspace", async () => {
581			latchRed("workspace-2", 1_000);
582			snapshotRows = [row({ lastEventAt: 5_000, pendingPermission: false })];
583	
584			const result = await resyncAgentStatusFromHost({
585				hostUrl: HOST,
586				workspaces: workspaces(),
587			});
588			await settle();
589	
590			expect(result?.retractedPermission).toBe(0);
591		});
592	
593		/**
594		 * The snapshot is OLDER truth than anything the open bus is delivering while
595		 * it is in flight. A PermissionRequest that landed after the request went out
596		 * must not be retracted by a row that predates it — the occurredAt fence at
597		 * the top of the loop skips the whole row, and it still does.
598		 */
599		it("leaves a NEWER local PermissionRequest alone", async () => {
600			latchRed(WORKSPACE, 9_000);
601			snapshotRows = [row({ lastEventAt: 5_000, pendingPermission: false })];
602	
603			const result = await resyncAgentStatusFromHost({
604				hostUrl: HOST,
605				workspaces: workspaces(),
606			});
607			await settle();
608	
609			const entry =
610				useV2NotificationStore.getState().sources["terminal:terminal-1"];
611			expect(entry?.status).toBe("permission");
612			expect(entry?.axes.permission).toBe(9_000);
613			expect(result?.retractedPermission).toBe(0);
614			expect(result?.skippedNewerLocal).toBe(1);
615		});
616	
617		/**
618		 * (MANUAL-DISMISS) CROSS-WINDOW CONVERGENCE, as far as this path can carry
619		 * it. A second window dismissed the workspace; THIS renderer's socket saw
620		 * nothing and no reconnect is coming, so the periodic resync is the only way
621		 * its red ever comes down — and it does, because the host no longer has a
622		 * marker to back it AND its binding has been forced off `PermissionRequest`
623		 * to `Stop` by the dismiss, which is what licenses the retraction at all.
624		 *
625		 * The GREEN does not converge the same way and is not expected to: the seen
626		 * watermark is per-renderer (sessionStorage), the snapshot carries no read
627		 * state, so this window keeps its own unread green until its own user reads
628		 * it. Only the red is a claim about the host's durable truth.
629		 */
630		it("takes down a red another window dismissed", async () => {
631			const store = useV2NotificationStore.getState();
632			store.applySourceAxes(
633				source,
634				WORKSPACE,
635				{ set: ["permission"], clear: [] },
636				1_000,
637			);
638			snapshotRows = [
639				row({
640					lastEventType: "Stop",
641					lastEventAt: 5_000,
642					pendingPermission: false,
643				}),
644			];
645	
646			const result = await resyncAgentStatusFromHost({
647				hostUrl: HOST,
648				workspaces: workspaces(),
649			});
650			await settle();
651	
652			const entry =
653				useV2NotificationStore.getState().sources["terminal:terminal-1"];
654			expect(entry?.axes.permission).toBeUndefined();
655			expect(entry?.status).not.toBe("permission");
656			expect(result?.retractedPermission).toBe(1);
657		});
658	
659		/**
660		 * The durability half of the fix. After a "Clear Status" the store is empty
661		 * and the seen watermark sits at the host's `lastEventAt`, so the very next
662		 * resync — which replays the same resting turn-end the host still holds —
663		 * must not put either dot back.
664		 */
665		it("does not resurrect a dismissed workspace's dots", async () => {
666			seenThrough("terminal-1", 5_000);
667			snapshotRows = [
668				row({
669					lastEventType: "Stop",
670					lastEventAt: 5_000,
671					pendingPermission: false,
672				}),
673			];
674	
675			await resyncAgentStatusFromHost({
676				hostUrl: HOST,
677				workspaces: workspaces(),
678			});
679			await settle();
680	
681			expect(
682				useV2NotificationStore.getState().sources["terminal:terminal-1"],
683			).toBeUndefined();
684		});
685	});
686	
687	// ---------------------------------------------------------------------------
688	// (ALERT-RETIRE-ON-EXIT) the relaunch boundary
689	// ---------------------------------------------------------------------------
690	
691	/**
692	 * (ALERT-RETIRE-ON-EXIT) The resync is the only thing that can put this
693	 * desktop's launch on a HOST's clock — it derives the boundary from the host's
694	 * own `hostNow` less the renderer's elapsed monotonic time — so it is where the
695	 * report belongs.
696	 *
697	 * EACH TEST USES ITS OWN HOST URL. `hostSessionBoundaries` is module state that
698	 * deliberately outlives a resync (a launch happens once), so a host another
699	 * test has already boundaried cannot be re-tested here.
700	 */
701	describe("(ALERT-RETIRE-ON-EXIT) the relaunch boundary report", () => {
702		beforeEach(() => {
703			// The tests above deliberately populate the store before their first
704			// resync, which decides this session WARM for the whole module. A relaunch
705			// only exists on a cold start, so it is re-decided here.
706			__resetColdStartForTest();
707			resetRelaunchBoundaryLatchForTest();
708			resetV2NotificationStoreForTest();
709		});
710	
711		it("reports a FLOORED boundary once per host, AFTER the seeding pass", async () => {
712			const hostA = "http://host-relaunch-a";
713			// Far enough ahead of the row's 5_000 that the cold-start seed cannot be
714			// squeezed out by however long this process has been up.
715			hostNow = 1_000_000;
716			await resyncAgentStatusFromHost({
717				hostUrl: hostA,
718				workspaces: workspaces(),
719			});
720			await settle();
721			expect(relaunchCalls).toHaveLength(1);
722			expect(relaunchCalls[0]?.hostUrl).toBe(hostA);
723			const reported = relaunchCalls[0]?.boundaryMs ?? Number.NaN;
724			// The map keeps the fractional value; the WIRE gets an integer, because
725			// the tRPC input is `.int()` and would refuse anything else.
726			expect(Number.isInteger(reported)).toBe(true);
727			expect(reported).toBeLessThanOrEqual(hostNow ?? 0);
728			// THE ORDERING. The row's pre-launch finish was already seeded seen when
729			// the report went out, so the cards the host is about to retract are ones
730			// this renderer has demonstrably taken over.
731			expect(relaunchCalls[0]?.seenAtReport).toBe(5_000);
732	
733			// A second epoch on the same host finds it latched and says nothing.
734			await resyncAgentStatusFromHost({
735				hostUrl: hostA,
736				workspaces: workspaces(),
737			});
738			await settle();
739			expect(relaunchCalls).toHaveLength(1);
740		});
741	
742		it("reports each host separately", async () => {
743			const hostB = "http://host-relaunch-b";
744			await resyncAgentStatusFromHost({
745				hostUrl: hostB,
746				workspaces: workspaces(),
747			});
748			await settle();
749			expect(relaunchCalls.map((call) => call.hostUrl)).toEqual([hostB]);
750		});
751	
752		it("SKIPS the report when cold-start seeding was skipped", async () => {
753			// A host too old to answer `hostNow` leaves the boundary unset, which
754			// disables seeding for it. There is no launch instant to report either,
755			// and guessing one with this machine's clock would retire alerts against
756			// a timeline the host has never been on.
757			const hostC = "http://host-relaunch-c";
758			hostNow = undefined;
759			await resyncAgentStatusFromHost({
760				hostUrl: hostC,
761				workspaces: workspaces(),
762			});
763			await settle();
764			expect(relaunchCalls).toHaveLength(0);
765		});
766	
767		/**
768		 * A reply that lands after its socket closed describes a connection that no
769		 * longer exists, and the epoch that replaced it runs its own resync. Reported
770		 * from there, the retraction would take down every pre-launch ready card
771		 * having reconciled nothing — and the acknowledgement latch would make that
772		 * loss permanent for the launch, since no later epoch re-reports.
773		 */
774		it("says NOTHING when the epoch guard discards the reply", async () => {
775			const hostE = "http://host-relaunch-e";
776			const result = await resyncAgentStatusFromHost({
777				hostUrl: hostE,
778				workspaces: workspaces(),
779				isCurrent: () => false,
780			});
781			await settle();
782			expect(result?.discarded).toBe(true);
783			expect(relaunchCalls).toEqual([]);
784	
785			// The next live epoch on that host still reports it.
786			await resyncAgentStatusFromHost({
787				hostUrl: hostE,
788				workspaces: workspaces(),
789				isCurrent: () => true,
790			});
791			await settle();
792			expect(relaunchCalls).toHaveLength(1);
793		});
794	
795		it("retries on the next epoch when the host did not consume it", async () => {
796			// The acknowledgement latch, not the boundary map, is what suppresses a
797			// repeat — so a report a still-registering bridge refused comes back.
798			const hostD = "http://host-relaunch-d";
799			await resyncAgentStatusFromHost({
800				hostUrl: hostD,
801				workspaces: workspaces(),
802			});
803			await settle();
804			expect(relaunchCalls).toHaveLength(1);
805	
806			resetRelaunchBoundaryLatchForTest();
807			await resyncAgentStatusFromHost({
808				hostUrl: hostD,
809				workspaces: workspaces(),
810			});
811			await settle();
812			expect(relaunchCalls).toHaveLength(2);
813			// Same launch, same instant — the map kept the fractional value and the
814			// floor is recomputed from it.
815			expect(relaunchCalls[1]?.boundaryMs).toBe(relaunchCalls[0]?.boundaryMs);
816		});
817	
818		/**
819		 * A HOST THAT REFUSED THE BOUNDARY MUST BE OFFERED A DIFFERENT ONE. The
820		 * refusal it actually sends is "that instant is in my future", which its
821		 * clock stepping forward after this renderer derived the value is enough to
822		 * produce — and re-offering the identical number would be refused
823		 * identically until the app restarts. So an unconsumed report drops the
824		 * latched boundary and the next epoch derives a fresh one from a fresher
825		 * `hostNow`.
826		 */
827		it("offers a FRESHLY DERIVED boundary after the host did not take one", async () => {
828			const hostF = "http://host-relaunch-f";
829			hostNow = 1_000_000;
830			acceptRelaunch = false;
831			await resyncAgentStatusFromHost({
832				hostUrl: hostF,
833				workspaces: workspaces(),
834			});
835			await settle();
836			expect(relaunchCalls).toHaveLength(1);
837	
838			// The host's clock has moved on by the next epoch, which is exactly what
839			// makes the second offer usable where the first was not.
840			hostNow = 2_000_000;
841			acceptRelaunch = true;
842			await resyncAgentStatusFromHost({
843				hostUrl: hostF,
844				workspaces: workspaces(),
845			});
846			await settle();
847			expect(relaunchCalls).toHaveLength(2);
848			const first = relaunchCalls[0]?.boundaryMs ?? Number.NaN;
849			const second = relaunchCalls[1]?.boundaryMs ?? Number.NaN;
850			expect(second).toBeGreaterThan(first);
851	
852			// And the host has now ACCEPTED one, so a third epoch says nothing — the
853			// acknowledgement latch, not the boundary map, is what closes it.
854			await resyncAgentStatusFromHost({
855				hostUrl: hostF,
856				workspaces: workspaces(),
857			});
858			await settle();
859			expect(relaunchCalls).toHaveLength(2);
860		});
861	});
